 const blob=new Blob([html],{type:'text/html;charset=utf-8'}),url=URL.createObjectURL(blob),a=node('a');
 a.href=url;a.download='event-workbook-editor-'+value.original.proposal.operation_id+'.html';document.body.append(a);a.click();a.remove();
 setTimeout(()=>URL.revokeObjectURL(url),60000);
