function openColumnChoices(proposal,columns=null){
 if(!proposal||proposal.state!=='WORKBOOK_COLUMN_CHOICES_REQUIRED')return;
 const selected={workspace_id:state.workspace,programme:state.programme.programme.name,proposal};
 workbookChoices.open(selected,{columns});
 $('column-choice').hidden=false;$('column-proposal').textContent=JSON.stringify(proposal,null,2);
