}
function reviewedWorkbookColumns(){
 const selected=workbookChoices.selected();
 if(selected){
  if(selected.workspace_id!==state.workspace||selected.programme!==state.programme?.programme.name||
    selected.proposal.operation_id!==state.operation||selected.proposal.review_sha256!==state.review?.review_sha256)
   throw Error('Open the current original worksheet proposal before applying these retained choices.');
