}
function controls(){
 const unavailable=state.busy||!state.workspace, running=state.action?.status==='RUNNING'||!!state.overview?.active;
 for(const e of document.querySelectorAll('button,input,select,textarea'))e.disabled=unavailable;
 for(const id of ['review','apply','refresh-review','deliver','receive','new-input'])$(id).disabled||=running;
 for(const id of ['review','apply','refresh-review','deliver'])$(id).disabled||=state.programme?.programme.name!==$('programme').value.trim();
 $('review').disabled||=!state.input?.complete;
 $('inspect-fields').disabled||=!state.input?.complete||running;
 $('download-fields').disabled||=!state.catalogue;
 $('export-mapping').disabled||=!state.catalogue;
 $('import-mapping').disabled||=!state.catalogue;
 $('fields-before').disabled||=!state.catalogue||state.fieldPage===0;
 $('fields-after').disabled||=!state.catalogue||(state.fieldPage+1)*50>=catalogueRows().length;
 $('values-before').disabled||=!state.fieldValues||state.fieldValues.offset===0;
 $('values-after').disabled||=!state.fieldValues||state.fieldValues.next_offset===null;
