 for(const control of document.querySelectorAll('[data-field-selectable]'))control.disabled||=control.dataset.fieldSelectable!=='true';
 $('apply').disabled||=!state.review||!!state.programme?.operations.find(x=>x.id===state.operation)?.applied;
 $('refresh-review').disabled||=!state.review||state.programme?.programme.pending!==state.operation;
 $('deliver').disabled||=!state.operation||!state.programme?.operations.find(x=>x.id===state.operation)?.applied;
 $('resume').hidden=!state.action||!['ERROR','INTERRUPTED','READY'].includes(state.action.status);
 $('resume').disabled||=running;
 $('use-accepted').disabled||=!state.programme?.programme.accepted;
