$('new-input').addEventListener('click',()=>{clearCatalogue();state.input=null;$('input-metadata').textContent='';$('input-status').textContent='Choose another complete original source pair.';try{localStorage.removeItem('sf-event-input:'+state.workspace);}catch{}controls();});
$('open-input').addEventListener('click',()=>act(async()=>{if(!$('inputs').value)throw Error('Choose a retained source pair.');renderInput(await api(root+'/inputs/'+$('inputs').value));}));
$('add-field').addEventListener('click',()=>{if(state.fields.length>=100)return;state.fields.push({name:'field_'+(state.fields.length+1),pointer:''});fieldRows();remember();});
$('use-accepted').addEventListener('click',()=>{state.fields=state.programme.programme.accepted.mapping.fields.map(x=>({...x}));fieldRows();remember();});
$('review').addEventListener('click',()=>act(()=>submit('review',{input_id:state.input.id,mapping:{fields:state.fields.map(x=>({...x}))},...(state.programme?.programme.accepted?{mapping_review:mappingReviewSelection()}: {})})));
$('apply').addEventListener('click',()=>act(()=>submit('apply',{review_sha256:state.review.review_sha256,note:$('note').value,columns:reviewedWorkbookColumns()})));
$('refresh-review').addEventListener('click',()=>act(()=>submit('refresh-review',{review_sha256:state.review.review_sha256,note:$('note').value})));
$('deliver').addEventListener('click',()=>act(()=>submit('deliver')));
$('resume').addEventListener('click',()=>act(async()=>{const original=state.action;const value=await api(root+'/named/'+encodeURIComponent(original.programme)+'/actions',{id:original.id,...original.request,resume:true});showAction(value);schedule();}));
$('refresh').addEventListener('click',()=>act(async()=>{if(state.action)showAction(await api(root+'/actions/'+state.action.id));await refresh();await refreshProgramme();schedule();}));
for(const id of ['note','columns'])$(id).addEventListener('input',remember);
for(const kind of ['actions','inputs']){$('older-'+kind).addEventListener('click',()=>act(async()=>{state[kind+'Before']=state.overview['next_'+kind];await refresh();}));$('latest-'+kind).addEventListener('click',()=>act(async()=>{state[kind+'Before']=null;await refresh();}));}
act(async()=>{if(!capability)throw Error('Open this page from the private Analysis launch link.');await refresh();let remembered;try{remembered=JSON.parse(localStorage.getItem('sf-event-input:'+state.workspace));}catch{}if(remembered){try{renderInput(await api(root+'/inputs/'+remembered.id));}catch{}}let previous;try{previous=JSON.parse(localStorage.getItem('sf-event-action:'+state.workspace));}catch{}if(previous){try{await openAction(previous.id);}catch{await openProgramme(previous.programme);state.operation=previous.request.operation_id;showAction({...previous,status:'INTERRUPTED',error:'Reopen or continue the original retained request.'});}}message('Customer workspace ready. Open a programme or receive a complete original file pair.');});
})();
"

"""Complete query-export controls within the original customer workspace."""

