function renderEvents(prefix,events){const select=$(prefix+'-event');const old=Number(select.value)||0;select.replaceChildren();events.forEach((e,index)=>{const o=node('option',(index+1)+' · '+e.eventType+' · '+e.job.name);o.value=String(index);select.append(o);});select.value=String(Math.min(old,Math.max(0,events.length-1)));$(prefix+'-json').textContent=events.length?pretty(events[Number(select.value)]):'No events';select.onchange=()=>{$(prefix+'-json').textContent=pretty(events[Number(select.value)]);};}
