function renderPublication(){const p=s.plan;if(!p)return;const state=status(),accepted=p.publication?.accepted,progress=s.job?.progress||{},latest=progress.observations?.at(-1)?.record;const labels={ACCEPTED:'Recorded by the collector',COMPLETE:'Publication completed',RUNNING:'Publishing the original event source',INTERRUPTED:'Publication interrupted',FAILED:'Attempt requires attention',CANCELLED:'Local attempt stopped',UNKNOWN:'Reply unavailable — original request retained',NOT_STARTED:'Reviewed source is ready',PENDING:'Original request is retained',ADMITTED:'Original publication admitted'};$('lineage-publication-status').textContent=labels[state]||state;let description='Publish the frozen event bytes once with the retained collector key.';if(accepted)description='The original producer acknowledged this exact event source. Its receipt remains available after either workspace is reopened.';else if(state==='RUNNING')description='The original Analysis job owns this attempt. Read its retained status or stop the local attempt.';else if(['FAILED','INTERRUPTED','CANCELLED','UNKNOWN'].includes(state))description='A stopped or interrupted request may already be recorded by the collector. Continue the same job, event bytes and original key to reconcile it.';else if(publicationRequest())description='The exact publication request is saved. Read its original job, or continue that same request.';$('lineage-publication-explanation').textContent=description;const f=$('lineage-publication-facts');f.replaceChildren();fact(f,'Original publication job',p.publication?.job_id||publicationRequest()?.body.id);fact(f,'Original source key',p.operation_id);fact(f,'Latest observed outcome',accepted?'ACCEPTED':progress.state||publicationRequest()?.state||'Not dispatched');fact(f,'Retained attempts',progress.attempts||accepted?.attempt||0);if(accepted){const receipt=accepted.native.receipt;fact(f,'Collector revision',receipt.revision);fact(f,'Events added / retained',receipt.added+' / '+receip