from .query_export import QueryExport
from .storage import digest, lock, parse, private_directory, read, sync_directory, write

_SCHEMA = "stellar-forge.customer-workbook.v1"
_DEFINITION = "stellar-forge.customer-workbook-definition.v1"
_NAME = re.compile(r"[A-Za-z][A-Za-z0-9_-]{0,63}")
_ID = re.compile(r"[a-f0-9]{32}")
_HASH = re.compile(r"[a-f0-9]{64}")
_BAD_SHEET = re.compile(r"[\\/*?:\[\]]")
_TYPES = {"native", "text", "integer", "number", "decimal-text", "boolean", "date", "datetime-utc", "datetime-local", "binary-base64"}
_ROWS_PER_SHEET = 1_048_575  # One additional row is reserved for column headings.
_MAX_COLUMNS = 16_384
_MAX_MANIFEST = 4 * 1024 * 1024
_MIMES = {"workbook.xlsx": "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
          "handoff.zip": "application/zip", "manifest.json": "application/json"}


def _json(value):
    return json.dumps(value, ensure_ascii=False, allow_nan=False, separators=(",", ":"))


def _now():
    return datetime.now(timezone.utc).isoformat()


def _error(code):
    raise StateError("ANALYSIS_WORKBOOK_" + code)


def _name(value):
    if not isinstance(value, str) or not _NAME.fullmatch(value):
        _error("NAME_INVALID")
    return value


def _id(value):
    if not isinstance(value, str) or not _ID.fullmatch(value):
        _error("REQUEST_ID_REQUIRED")
    return value


def _hash(value):
    if not isinstance(value, str) or not _HASH.fullmatch(value):
        _error("DIGEST_REQUIRED")
    return value


def _text(value, maximum, *, required=False):
    if not isinstance(value, str) or len(value.encode("utf-8")) > maximum or "\0" in value or required and not value.strip():
        _error("TEXT_INVALID")
    return value


def _unpack(row):
    if row is None:
        _error("NOT_FOUND")
    raw = row["record"].encode()
    if digest(raw) != row["sha256"]:
        _error("RETAINED_RECORD_CHANGED")
    return parse(raw)


def _page(before, limit):
    if type(limit) is not int or not 1 <= limit <= 100 or before is not None and (type(before) is not int or before < 1):
        _error("PAGE_INVALID")


def _source_key(source, column):
    """Select report cells by position while preserving original column labels."""
    if not isinstance(column, dict) or column.get("source") not in source["columns"]:
        _error("SOURCE_COLUMN_CHANGED")
    if source["kind"] != "report":
        return column["source"]
    index = column.get("source_index")
    if index is None:
        matches = [index for index, name in enumerate(source["columns"]) if name == column["source"]]
        if len(matches) != 1:
            _error("SOURCE_COLUMN_INDEX_REQUIRED")
        return matches[0]
    if (type(index) is not int or not 0 <= index < len(source["columns"])
            or source["columns"][index] != column["source"]):
        _error("SOURCE_COLUMN_CHANGED")
    return index


def _relative(value):
    if not isinstance(value, str) or "\\" in value or "\0" in value:
        _error("FILE_INVALID")
    path = PurePosixPath(value)
    if path.is_absolute() or not path.parts or any(part in {".", "..", ""} for part in path.parts) or str(path) != value:
        _error("FILE_INVALID")
    if value in {"workbook.xlsx", "definition.json"}:
        return value
    if len(path.parts) == 2 and path.parts[0] == "history" and re.fullmatch(r"definition-[1-9][0-9]*\.json", path.parts[1]):
        return value
    if (len(path.parts) == 3 and path.parts[0] == "sources"
            and re.fullmatch(r"(?:query-export|report)-[a-f0-9]{32}", path.parts[1])
            and path.parts[2] in {"manifest.json", "rows.jsonl", "rows.csv", "rows.sqlite3", "report.json"}):
        return value
    _error("FILE_INVALID")


@contextmanager
def _open_private(path):
    fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW)
    with os.fdopen(fd, "rb") as stream:
        info = os.fstat(stream.fileno())
        if (not stat.S_ISREG(info.st_mode) or info.st_nlink != 1 or info.st_mode & 0o077
                or hasattr(os, "getuid") and info.st_uid != os.getuid()):
            _error("PRIVATE_FILE_REQUIRED")
        yield stream


def _file_record(path):
    with _open_private(path) as stream:
        return {"bytes": os.fstat(stream.fileno()).st_size, "sha256": hashlib.file_digest(stream, "sha256").hexdigest()}



def _publish_received_directory(source, target):
    """Atomically publish a complete directory without replacing any destination."""
    import ctypes
    import sys

    libc = ctypes.CDLL(None, use_errno=True)
    if sys.platform.startswith("linux") and hasattr(libc, "renameat2"):
        rename = libc.renameat2
        rename.argtypes = [ctypes.c_int, ctypes.c_char_p, ctypes.c_int, ctypes.c_char_p, ctypes.c_uint]
        rename.restype = ctypes.c_int
        result = rename(-100, os.fsencode(source), -100, os.fsencode(target), 1)  # RENAME_NOREPLACE
    elif sys.platform == "darwin" and hasattr(libc, "renamex_np"):
        rename = libc.renamex_np
        rename.argtypes = [ctypes.c_char_p, ctypes.c_char_p, ctypes.c_uint]
        rename.restype = ctypes.c_int
        result = rename(os.fsencode(source), os.fsencode(target), 4)  # RENAME_EXCL
    else:
        _error("ATOMIC_DIRECTORY_PUBLICATION_UNAVAILABLE")
    if result:
        code = ctypes.get_errno()
        raise OSError(code, os.strerror(code), os.fspath(target))
    sync_directory(target.parent)


def _literal(value):
    """Check before openpyxl's string binding can truncate an Excel cell."""
    try:
        length = len(value.encode("utf-16-le")) // 2
    except UnicodeError:
        _error("CELL_UNICODE_INVALID")
    if length > 32_767:
        _error("CELL_TEXT_EXCEEDS_EXCEL_LIMIT")
    if any(ord(c) < 32 and c not in "\t\n\r" or ord(c) in {0xFFFE, 0xFFFF} for c in value):
        _error("CELL_XML_CHARACTER_INVALID")
    return value


def _display(value):
    if isinstance(value, bytes):
        return "base64:" + base64.b64encode(value).decode("ascii")
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, float) and not math.isfinite(value):
        return "NaN" if math.isnan(value) else "Infinity" if value > 0 else "-Infinity"
    return str(value)


def project_cell(value, column):
    """Return (value, Excel number format, conversion), with explicit precision."""
    kind = column["type"]
    if value is None:
        return (None if column["null"] == "blank" else _literal(column["null_text"]), None, "null")
    if kind == "text":
        return _literal(_display(value)), "@", "empty-string" if value == "" else None
    if kind == "binary-base64":
        if not isinstance(value, bytes):
            _error("BINARY_CELL_REQUIRED")
        return _literal(base64.b64encode(value).decode("ascii")), "@", "binary-text"
    if kind == "decimal-text":
        if isinstance(value, bool) or not isinstance(value, (str, int, float, Decimal)):
            _error("DECIMAL_CELL_REQUIRED")
        text = str(value)
        try:
            number = Decimal(text)
        except InvalidOperation:
            _error("DECIMAL_CELL_REQUIRED")
        if not number.is_finite():
            _error("FINITE_DECIMAL_REQUIRED")
        return _literal(text), "@", "decimal-text"
    if kind == "boolean":
        if type(value) is bool:
            return value, None, None
        if type(value) is int and value in {0, 1}:
            return bool(value), None, "boolean"
        if isinstance(value, str) and value.casefold() in {"true", "false"}:
            return value.casefold() == "true", None, "boolean"
        _error("BOOLEAN_CELL_REQUIRED")
    if kind in {"date", "datetime-utc", "datetime-local"}:
        if not isinstance(value, str):
            _error("ISO_DATE_TEXT_REQUIRED")
        try:
            if kind == "date":
                if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", value):
                    _error("ISO_DATE_TEXT_REQUIRED")
                parsed = date.fromisoformat(value)
                if parsed < date(1900, 1, 1):
                    return _literal(value), "@", "date-text"
                return parsed, "yyyy-mm-dd", "date"
            parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
            if "T" not in value and " " not in value:
                _error("ISO_DATETIME_TEXT_REQUIRED")
            if kind == "datetime-utc":
                if parsed.tzinfo is None:
                    _error("DATETIME_TIMEZONE_REQUIRED")
                parsed = parsed.astimezone(timezone.utc).replace(tzinfo=None)
            elif parsed.tzinfo is not None:
                _error("LOCAL_DATETIME_MUST_BE_NAIVE")
            if parsed.year < 1900 or parsed.microsecond % 1000:
                return _literal(value), "@", "datetime-text"
            return parsed, 'yyyy-mm-dd hh:mm:ss.000" UTC"' if kind == "datetime-utc" else "yyyy-mm-dd hh:mm:ss.000", "datetime"
        except (ValueError, OverflowError):
            _error("ISO_DATE_TEXT_REQUIRED")
    if kind == "integer":
        if type(value) is int:
            pass
        elif isinstance(value, str) and re.fullmatch(r"[+-]?\d+", value):
            value = int(value)
        else:
            _error("INTEGER_CELL_REQUIRED")
    elif kind == "number":
        if isinstance(value, bool) or not isinstance(value, (str, int, float, Decimal)):
            _error("NUMERIC_CELL_REQUIRED")
        text = str(value)
        try:
            number = Decimal(text)
        except InvalidOperation:
            _error("NUMERIC_CELL_REQUIRED")
        if not number.is_finite():
            _error("FINITE_NUMBER_REQUIRED")
        if column["precision"] == "preserve" and (len(number.as_tuple().digits) > 15 or number.adjusted() > 307 or number.adjusted() < -307):
            return _literal(text), "@", "precision-text"
        value = float(number)
        if not math.isfinite(value) or value == 0 and number != 0:
            _error("NUMBER_OUTSIDE_EXCEL_RANGE")
    if isinstance(value, bytes):
        return _literal(_display(value)), "@", "binary-text"
    if isinstance(value, str):
        return _literal(value), "@", "empty-string" if value == "" else None
    if isinstance(value, bool):
        return value, None, None
    if type(value) is int:
        if len(str(abs(value))) > 15 and column["precision"] == "preserve":
            return str(value), "@", "precision-text"
        return value, "0", "numeric-choice" if len(str(abs(value))) > 15 else None
    if isinstance(value, float):
        if not math.isfinite(value):
            return _display(value), "@", "nonfinite-text"
        decimal = Decimal(repr(value))
        if column["precision"] == "preserve" and (len(decimal.as_tuple().digits) > 15 or decimal.adjusted() > 307 or decimal.adjusted() < -307):
            return repr(value), "@", "precision-text"
        return value, "General", "numeric-choice" if column["precision"] == "excel-number" else None
    _error("CELL_TYPE_UNSUPPORTED")


def _sheet_layout(sheets):
    used = {"readme", "sources"}
    result = []
    for sheet in sheets:
        names = []
        count = max(1, (sheet["source"]["row_count"] + _ROWS_PER_SHEET - 1) // _ROWS_PER_SHEET)
        for index in range(count):
            suffix = "" if index == 0 else f" ({index + 1})"
            name = sheet["name"][:31 - len(suffix)] + suffix
            if name.casefold() in used:
                _error("SHEET_NAMES_COLLIDE_AFTER_SPLIT")
            used.add(name.casefold())
            names.append(name)
        result.append(names)
    return result


class WorkbookDelivery:
    """Open, inspect, copy or receive a complete workbook without a live workspace."""

    def __init__(self, directory, *, expected_manifest_sha256=None):
        self.directory = Path(directory).absolute()
        if self.directory.resolve() != self.directory or not self.directory.is_dir():
            _error("CANONICAL_DELIVERY_DIRECTORY_REQUIRED")
        self.raw = read(self.directory / "manifest.json", _MAX_MANIFEST)
        if expected_manifest_sha256 is not None and digest(self.raw) != _hash(expected_manifest_sha256):
            _error("MANIFEST_CHANGED")
        self.manifest = parse(self.raw)
        manifest = self.manifest
        if (manifest.get("schema") != _SCHEMA or manifest.get("complete") is not True
                or not isinstance(manifest.get("files"), dict) or not {"workbook.xlsx", "definition.json"} <= set(manifest["files"])):
            _error("COMPLETE_DELIVERY_REQUIRED")
        _id(manifest.get("id"))
        _hash(manifest.get("definition_sha256"))
        for name, record in manifest["files"].items():
            _relative(name)
            if not isinstance(record, dict) or type(record.get("bytes")) is not int or record["bytes"] < 0:
                _error("FILE_METADATA_INVALID")
            _hash(record.get("sha256"))

    @contextmanager
    def open(self, name):
        if name == "manifest.json":
            with io.BytesIO(self.raw) as stream:
                yield stream
            return
        if name not in self.manifest["files"]:
            _error("FILE_INVALID")
        path = self.directory / _relative(name)
        if path.resolve() != path:
            _error("FILE_LOCATION_CHANGED")
        with _open_private(path) as stream:
            expected = self.manifest["files"][name]
            if (os.fstat(stream.fileno()).st_size != expected["bytes"]
                    or hashlib.file_digest(stream, "sha256").hexdigest() != expected["sha256"]):
                _error("FILE_CHANGED")
            stream.seek(0)
            yield stream

    def inspect(self):
        for name in self.manifest["files"]:
            with self.open(name):
                pass
        with self.open("definition.json") as stream:
            raw = stream.read(_MAX_MANIFEST + 1)
        if len(raw) > _MAX_MANIFEST or digest(raw) != self.manifest["definition_sha256"]:
            _error("DEFINITION_CHANGED")
        current = parse(raw)
        while current.get("refresh_origin"):
            origin = current["refresh_origin"]
            revision = origin.get("base_revision")
            if type(revision) is not int or not 1 <= revision < current["revision"]:
                _error("REFRESH_HISTORY_CHANGED")
            name = "history/definition-" + str(revision) + ".json"
            if origin.get("base_definition_file") != name:
                _error("REFRESH_HISTORY_CHANGED")
            with self.open(name) as stream:
                previous_raw = stream.read(_MAX_MANIFEST + 1)
            if len(previous_raw) > _MAX_MANIFEST or digest(previous_raw) != origin.get("base_definition_sha256"):
                _error("REFRESH_HISTORY_CHANGED")
            previous = parse(previous_raw)
            if (previous.get("name") != current["name"] or previous.get("revision") != revision
                    or previous.get("workspace_id") != current["workspace_id"]):
                _error("REFRESH_HISTORY_CHANGED")
            current = previous
        return {**self.manifest, "manifest_sha256": digest(self.raw)}

    def verify_archive(self, path):
        """A recovered ZIP must contain the complete original manifest and files."""
        with _open_private(path) as stream, zipfile.ZipFile(stream) as package:
            names = [entry.filename for entry in package.infolist()]
            if len(names) != len(set(names)) or set(names) != set(self.manifest["files"]) | {"manifest.json"}:
                _error("ARCHIVE_MEMBERS_INVALID")
            meta = package.getinfo("manifest.json")
            if meta.file_size != len(self.raw) or package.read(meta) != self.raw:
                _error("ARCHIVE_MANIFEST_CHANGED")
            for name, expected in self.manifest["files"].items():
                entry = package.getinfo(name)
                if entry.file_size != expected["bytes"] or stat.S_ISLNK(entry.external_attr >> 16):
                    _error("ARCHIVE_MEMBER_CHANGED")
                with package.open(entry) as member:
                    if hashlib.file_digest(member, "sha256").hexdigest() != expected["sha256"]:
                        _error("ARCHIVE_MEMBER_CHANGED")

    def copy_to(self, destination):
        target = Path(destination).absolute()
        parent = private_directory(target.parent)
        if parent / target.name != target:
            _error("CANONICAL_DELIVERY_DIRECTORY_REQUIRED")
        target.mkdir(mode=0o700)
        try:
            for name in self.manifest["files"]:
                path = target / name
                private_directory(path.parent)
                with self.open(name) as source, path.open("xb") as output:
                    os.fchmod(output.fileno(), 0o600)
                    shutil.copyfileobj(source, output, 1024 * 1024)
                    output.flush()
                    os.fsync(output.fileno())
            write(target / "manifest.json", self.raw)
            sync_directory(target)
        except BaseException:
            shutil.rmtree(target)
            raise
        return WorkbookDelivery(target, expected_manifest_sha256=digest(self.raw))

    @classmethod
    def receive(cls, archive, destination, *, expected_sha256=None, max_bytes=1024 * 1024 * 1024):
        """Receive into private staging, then publish one verified complete directory."""
        if type(max_bytes) is not int or max_bytes < 1:
            _error("RECEIVING_LIMIT_REQUIRED")
        target = Path(destination).absolute()
        parent = private_directory(target.parent)
        target = parent / target.name
        if os.path.lexists(target):
            raise FileExistsError(str(target))
        with _open_private(Path(archive).absolute()) as source:
            archive_sha = hashlib.file_digest(source, "sha256").hexdigest()
            if expected_sha256 is not None and archive_sha != _hash(expected_sha256):
                _error("ARCHIVE_CHANGED")
            source.seek(0)
            # The original operation can reclaim its own unfinished staging after
            # process termination. The retained archive remains the only input.
            control = private_directory(parent / (".workbook-receive-" + digest(os.fsencode(target.name))[:24]))
            with lock(control):
                if os.path.lexists(target):
                    raise FileExistsError(str(target))
                intent_path, staging = control / "source.json", control / "content"
                intent = {"schema": "stellar-forge.workbook-receiving.v1", "destination": str(target),
                          "archive_sha256": archive_sha}
                if intent_path.exists():
                    with _open_private(intent_path) as retained:
                        old = retained.read(64 * 1024 + 1)
                    if len(old) > 64 * 1024 or parse(old) != intent:
                        _error("RECEIVING_OPERATION_CHANGED")
                else:
                    if os.path.lexists(staging):
                        _error("RECEIVING_STATE_INVALID")
                    write(intent_path, _json(intent).encode(), exclusive=True)
                if os.path.lexists(staging):
                    private_directory(staging, create=False)
                    shutil.rmtree(staging)
                staging.mkdir(mode=0o700)
                try:
                    with zipfile.ZipFile(source) as package:
                        infos = package.infolist()
                        names = [entry.filename for entry in infos]
                        if len(names) != len(set(names)) or "manifest.json" not in names:
                            _error("ARCHIVE_MEMBERS_INVALID")
                        meta = package.getinfo("manifest.json")
                        if meta.file_size > _MAX_MANIFEST:
                            _error("MANIFEST_TOO_LARGE")
                        raw = package.read(meta)
                        manifest = parse(raw)
                        if manifest.get("schema") != _SCHEMA or manifest.get("complete") is not True or not isinstance(manifest.get("files"), dict):
                            _error("COMPLETE_DELIVERY_REQUIRED")
                        if set(names) != set(manifest["files"]) | {"manifest.json"}:
                            _error("ARCHIVE_MEMBERS_INVALID")
                        if sum(entry.file_size for entry in infos) > max_bytes:
                            _error("RECEIVING_BYTE_LIMIT_EXCEEDED")
                        for name, expected in manifest["files"].items():
                            _relative(name)
                            entry = package.getinfo(name)
                            if entry.file_size != expected["bytes"] or stat.S_ISLNK(entry.external_attr >> 16):
                                _error("ARCHIVE_MEMBER_CHANGED")
                            path = staging / name
                            private_directory(path.parent)
                            sha, size = hashlib.sha256(), 0
                            with package.open(entry) as input_stream, path.open("xb") as output:
                                os.fchmod(output.fileno(), 0o600)
                                for block in iter(lambda: input_stream.read(1024 * 1024), b""):
                                    sha.update(block)
                                    size += len(block)
                                    if size > expected["bytes"]:
                                        _error("ARCHIVE_MEMBER_CHANGED")
                                    output.write(block)
                                output.flush()
                                os.fsync(output.fileno())
                            if size != expected["bytes"] or sha.hexdigest() != expected["sha256"]:
                                _error("ARCHIVE_MEMBER_CHANGED")
                        write(staging / "manifest.json", raw)
                        for directory in sorted((p for p in staging.rglob("*") if p.is_dir()),
                                                key=lambda p: len(p.parts), reverse=True):
                            sync_directory(directory)
                        sync_directory(staging)
                    result = cls(staging)
                    result.inspect()
                    _publish_received_directory(staging, target)
                    sync_directory(control)
                    return cls(target)
                except BaseException:
                    if staging.exists():
                        shutil.rmtree(staging)
                    raise


class AnalysisWorkbooks:
    def __init__(self, database, *, identity, reports=None, initialize=True):
        self.database, self.identity, self.reports = database, identity, reports
        from .workbook_refresh import WorkbookRefresh
        self.refresh = WorkbookRefresh(self)
        self.directory = database.directory / "analysis-workbooks"
        self._mutex = threading.Lock()
        self._signals = {}
        self._closed = False
        if initialize:
            private_directory(self.directory)
            with database._connection() as db:
                db.execute("BEGIN IMMEDIATE")
                db.execute("CREATE TABLE IF NOT EXISTS sf_analysis_workbooks(name TEXT PRIMARY KEY,revision INTEGER NOT NULL,record TEXT NOT NULL,sha256 TEXT NOT NULL)")
                db.execute("CREATE TABLE IF NOT EXISTS sf_analysis_workbook_history(sequence INTEGER PRIMARY KEY,name TEXT NOT NULL,revision INTEGER NOT NULL,request_id TEXT NOT NULL UNIQUE,request_sha256 TEXT NOT NULL,record TEXT NOT NULL,sha256 TEXT NOT NULL,UNIQUE(name,revision))")
                db.execute("CREATE TABLE IF NOT EXISTS sf_analysis_workbook_control(id TEXT PRIMARY KEY REFERENCES sf_analysis_jobs(id),cancel_requested INTEGER NOT NULL DEFAULT 0,progress TEXT NOT NULL)")
                db.commit()

    @staticmethod
    def state(db):
        if db.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name='sf_analysis_workbooks'").fetchone() is None:
            return []
        return [{"name": row["name"], "revision": row["revision"], "sha256": row["sha256"],
                 "title": _unpack(row)["title"], "sheets": len(_unpack(row)["sheets"])}
                for row in db.execute("SELECT * FROM sf_analysis_workbooks ORDER BY name")]

    def source(self, request):
        if not isinstance(request, dict) or request.get("kind") not in {"query-export", "report"}:
            _error("SOURCE_REQUIRED")
        kind, identifier = request["kind"], _id(request.get("id"))
        with self.database._connection(readonly=True) as db:
            db.execute("BEGIN")
            if kind == "query-export":
                row = db.execute("SELECT request,result FROM sf_analysis_jobs WHERE id=? AND kind='query-export' AND status='COMPLETE'", (identifier,)).fetchone()
                if row is None or row["result"] is None:
                    _error("COMPLETE_TYPED_QUERY_EXPORT_REQUIRED")
                result = parse(row["result"].encode())
                export = QueryExport(self.database.directory / "analysis-query-exports" / identifier)
                raw = read(export.directory / "manifest.json", 16 * 1024 * 1024)
                sha = digest(raw)
                manifest = export.manifest
                if result.get("manifest_sha256") != sha:
                    _error("SOURCE_MANIFEST_CHANGED")
                if "rows.jsonl" not in manifest["outputs"]:
                    _error("ORIGINAL_TYPED_JSONL_REQUIRED")
                item = {"kind": kind, "id": identifier, "sha256": sha, "label": result.get("label", identifier),
                        "columns": manifest["columns"], "row_count": manifest["rowCount"],
                        "binding_sha256": manifest["bindingSha256"]}
            else:
                if self.reports is None:
                    _error("ORIGINAL_REPORT_READER_REQUIRED")
                row = db.execute("SELECT * FROM sf_analysis_report_publications WHERE id=?", (identifier,)).fetchone()
                publication = _unpack(row)
                report = AnalysisReports._report(db, publication["job_id"])
                if report["result_sha256"] != publication["result_sha256"]:
                    _error("SOURCE_REPORT_CHANGED")
                section = request.get("section")
                if type(section) is not int or not 0 <= section < len(report["sections"]):
                    _error("REPORT_SECTION_REQUIRED")
                selected = report["sections"][section]
                item = {"kind": kind, "id": identifier, "sha256": row["sha256"], "section": section,
                        "job_id": report["job_id"], "result_sha256": report["result_sha256"],
                        "label": publication["title"] + " / " + selected["title"],
                        "columns": selected["columns"], "row_count": selected["row_count"]}
        if request.get("sha256") is not None and request["sha256"] != item["sha256"]:
            _error("SOURCE_CHANGED")
        return item

    def sources(self, *, kind="query-export", before=None, limit=25):
        _page(before, limit)
        with self.database._connection(readonly=True) as db:
            if kind == "query-export":
                rows = db.execute("SELECT sequence,id FROM sf_analysis_jobs WHERE kind='query-export' AND status='COMPLETE' AND (? IS NULL OR sequence<?) ORDER BY sequence DESC LIMIT ?", (before, before, limit + 1)).fetchall()
            elif kind == "report" and self.reports is not None:
                rows = db.execute("SELECT sequence,id,job_id FROM sf_analysis_report_publications WHERE (? IS NULL OR sequence<?) ORDER BY sequence DESC LIMIT ?", (before, before, limit + 1)).fetchall()
            else:
                _error("SOURCE_KIND_INVALID")
        items = []
        for row in rows[:limit]:
            if kind == "report":
                with self.database._connection(readonly=True) as db:
                    sections = len(AnalysisReports._report(db, row["job_id"])["sections"])
                items.extend(self.source({"kind": kind, "id": row["id"], "section": section}) for section in range(sections))
            else:
                try:
                    items.append(self.source({"kind": kind, "id": row["id"]}))
                except StateError as exc:
                    if exc.code != "ANALYSIS_WORKBOOK_ORIGINAL_TYPED_JSONL_REQUIRED":
                        raise
                    items.append({"kind": kind, "id": row["id"], "available": False, "error": exc.code})
        return {"items": items, "next_before": rows[limit - 1]["sequence"] if len(rows) > limit else None}

    def compose(self, name, request):
        """Normalize a complete definition before its compare-and-swap save."""
        name = _name(name)
        title = _text(request.get("title"), 300, required=True)
        notes = _text(request.get("notes", ""), 16_000)
        sheets = request.get("sheets")
        if not isinstance(sheets, list) or not 1 <= len(sheets) <= 32:
            _error("ONE_TO_32_SHEETS_REQUIRED")
        result = []
        for sheet in sheets:
            if not isinstance(sheet, dict):
                _error("SHEET_REQUIRED")
            label = _text(sheet.get("name"), 124, required=True)
            if len(label) > 31 or _BAD_SHEET.search(label) or label.startswith("'") or label.endswith("'") or any(ord(c) < 32 for c in label):
                _error("EXCEL_SHEET_NAME_INVALID")
            source = self.source(sheet.get("source"))
            columns = sheet.get("columns")
            if not isinstance(columns, list) or not 1 <= len(columns) <= _MAX_COLUMNS:
                _error("COLUMNS_REQUIRED")
            projected, headers = [], set()
            for column in columns:
                source_key = _source_key(source, column)
                header = _literal(_text(column.get("header", column["source"]), 2000, required=True))
                if header.casefold() in headers:
                    _error("COLUMN_HEADERS_MUST_BE_UNIQUE")
                headers.add(header.casefold())
                kind = column.get("type", "native")
                null, precision = column.get("null", "text"), column.get("precision", "preserve")
                if kind not in _TYPES or null not in {"blank", "text"} or precision not in {"preserve", "excel-number"}:
                    _error("COLUMN_PROJECTION_INVALID")
                projected.append({"source": column["source"], "header": header, "type": kind, "null": null,
                                  "null_text": _literal(_text(column.get("null_text", "NULL"), 1000)), "precision": precision,
                                  **({"source_index": source_key} if source["kind"] == "report" and "source_index" in column else {})})
            result.append({"name": label, "source": source, "columns": projected})
        _sheet_layout(result)
        return {"schema": _DEFINITION, "name": name, "title": title, "notes": notes, "sheets": result}

    def save(self, name, request, *, refresh_origin=None):
        request_id = _id(request.get("id"))
        expected = request.get("expected_revision")
        if type(expected) is not int or expected < 0:
            _error("REVISION_REQUIRED")
        normalized = self.compose(name, request)
        if refresh_origin is not None:
            normalized["refresh_origin"] = refresh_origin
        request_sha = digest(_json({"id": request_id, "expected_revision": expected, **normalized}).encode())
        with self.database._connection() as db:
            db.execute("BEGIN IMMEDIATE")
            old = db.execute("SELECT * FROM sf_analysis_workbook_history WHERE request_id=?", (request_id,)).fetchone()
            if old is not None:
                if old["request_sha256"] != request_sha:
                    _error("REQUEST_ID_REUSED")
                return {**_unpack(old), "definition_sha256": old["sha256"]}
            head = db.execute("SELECT revision FROM sf_analysis_workbooks WHERE name=?", (name,)).fetchone()
            if (head[0] if head else 0) != expected:
                _error("DEFINITION_CHANGED")
            record = {**normalized, "revision": expected + 1, "saved_at": _now(), "workspace_id": self.identity}
            raw = _json(record)
            sha = digest(raw.encode())
            db.execute("INSERT INTO sf_analysis_workbooks VALUES(?,?,?,?) ON CONFLICT(name) DO UPDATE SET revision=excluded.revision,record=excluded.record,sha256=excluded.sha256", (name, record["revision"], raw, sha))
            db.execute("INSERT INTO sf_analysis_workbook_history(name,revision,request_id,request_sha256,record,sha256) VALUES(?,?,?,?,?,?)", (name, record["revision"], request_id, request_sha, raw, sha))
            db.commit()
            return {**record, "definition_sha256": sha}

    def definition(self, name, *, revision=None):
        name = _name(name)
        if revision is not None and (type(revision) is not int or revision < 1):
            _error("REVISION_REQUIRED")
        with self.database._connection(readonly=True) as db:
            db.execute("BEGIN")
            if revision is None:
                row = db.execute("SELECT * FROM sf_analysis_workbooks WHERE name=?", (name,)).fetchone()
            else:
                row = db.execute("SELECT * FROM sf_analysis_workbook_history WHERE name=? AND revision=?", (name, revision)).fetchone()
            record = _unpack(row)
            return {"definition": record, "definition_sha256": row["sha256"],
                    "head_revision": db.execute("SELECT revision FROM sf_analysis_workbooks WHERE name=?", (name,)).fetchone()[0],
                    "history": [dict(r) for r in db.execute("SELECT revision,sha256 FROM sf_analysis_workbook_history WHERE name=? ORDER BY revision DESC LIMIT 100", (name,))]}

    def prepare(self, request):
        result = self.definition(request.get("name"), revision=request.get("revision"))
        if request.get("definition_sha256") != result["definition_sha256"]:
            _error("DEFINITION_CHANGED")
        return {"name": result["definition"]["name"], "revision": result["definition"]["revision"],
                "definition_sha256": result["definition_sha256"]}

    @contextmanager
    def _rows(self, source):
        current = self.source(source)
        if current != source:
            _error("SOURCE_CHANGED")
        if source["kind"] == "query-export":
            iterator = QueryExport(self.database.directory / "analysis-query-exports" / source["id"]).rows()
            try:
                yield iterator
            finally:
                iterator.close()
        else:
            with self.database._connection(readonly=True) as db:
                db.execute("BEGIN")
                publication, report = self.reports._export_input(db, {"publication_id": source["id"], "publication_sha256": source["sha256"]})
                selected = report["sections"][source["section"]]
                def values():
                    for cells in AnalysisReports._rows(db, report, selected):
                        result = []
                        for cell in cells:
                            kind, text = cell["type"], cell["text"]
                            result.append(None if kind == "null" else int(text) if kind == "integer" else float(text) if kind in {"number", "sqlite-real"} else base64.b64decode(text, validate=True) if kind == "blob" else text)
                        yield result
                yield values()

    def preview(self, name, *, revision=None, sheet=0, limit=20):
        result = self.definition(name, revision=revision)
        sheets = result["definition"]["sheets"]
        if type(sheet) is not int or not 0 <= sheet < len(sheets) or type(limit) is not int or not 1 <= limit <= 100:
            _error("PREVIEW_PAGE_INVALID")
        selected, rows = sheets[sheet], []
        keys = [_source_key(selected["source"], column) for column in selected["columns"]]
        with self._rows(selected["source"]) as stream:
            for row in stream:
                values = []
                for column, key in zip(selected["columns"], keys):
                    value, number_format, conversion = project_cell(row[key], column)
                    values.append({"value": value.isoformat() if isinstance(value, (date, datetime)) else str(value) if type(value) is int and abs(value) >= 2**53 else value,
                                   "excel_type": "blank" if value is None else "text" if isinstance(value, str) else "date" if isinstance(value, (date, datetime)) else "boolean" if isinstance(value, bool) else "number",
                                   "format": number_format, "conversion": conversion})
                rows.append(values)
                if len(rows) >= limit:
                    break
        return {"definition_sha256": result["definition_sha256"], "sheet": selected, "rows": rows,
                "row_count": selected["source"]["row_count"], "preview_only": len(rows) < selected["source"]["row_count"]}

    def _retain_source(self, source, target):
        target = target / "sources" / (source["kind"] + "-" + source["id"])
        if target.exists():
            return
        private_directory(target.parent)
        if source["kind"] == "query-export":
            QueryExport(self.database.directory / "analysis-query-exports" / source["id"]).copy_to(target)
            if digest(read(target / "manifest.json", 16 * 1024 * 1024)) != source["sha256"]:
                _error("SOURCE_CHANGED")
        else:
            private_directory(target)
            with self.database._connection(readonly=True) as db, (target / "report.json").open("xb") as output:
                os.fchmod(output.fileno(), 0o600)
                db.execute("BEGIN")
                publication, report = self.reports._export_input(db, {"publication_id": source["id"], "publication_sha256": source["sha256"]})
                for block in self.reports._json_blocks(db, publication, report):
                    output.write(block)
                output.flush()
                os.fsync(output.fileno())

    def build(self, definition, job_id, destination, *, cancel=lambda: False, progress=lambda value: None):
        """Build an entire portable delivery from pinned native results, without DB writes."""
        try:
            from openpyxl import Workbook
            from openpyxl.cell import WriteOnlyCell
            from openpyxl.styles import Alignment, Font, PatternFill
            from openpyxl.utils import get_column_letter
        except ImportError:
            _error("INSTALL_WORKBOOKS_EXTRA")
        job_id = _id(job_id)
        if definition.get("schema") != _DEFINITION or type(definition.get("revision")) is not int:
            _error("SAVED_DEFINITION_REQUIRED")
        raw = _json(definition).encode()
        definition_sha = digest(raw)
        layout = _sheet_layout(definition["sheets"])
        target = Path(destination).absolute()
        private_directory(target.parent)
        target.mkdir(mode=0o700)
        workbook = Workbook(write_only=True, iso_dates=True)
        workbook.properties.title = definition["title"]
        workbook.properties.creator = "Stellar Forge"
        workbook.properties.description = "Customer workbook with original typed results and source bindings in its handoff."
        header_fill = PatternFill("solid", fgColor="E7E7E7")
        header_font = Font(name="Calibri", size=11, bold=True, color="202020")
        body_font = Font(name="Calibri", size=11, color="202020")
        body_alignment = Alignment(vertical="top", wrap_text=True)
        outputs, total_rows = [], 0

        def stopped():
            if cancel():
                _error("CANCELLED")

        def cell(sheet, value, number_format=None, heading=False):
            item = WriteOnlyCell(sheet, value=value)
            if isinstance(value, str):
                item.data_type = "s"  # '=' remains original text, never a formula.
            if number_format:
                item.number_format = number_format
            item.font = body_font
            item.alignment = body_alignment
            if heading:
                item.fill, item.font = header_fill, header_font
            return item

        def source_widths(source, columns, keys):
            # Inspect a bounded prefix without retaining rows or materializing the
            # full export. The actual write still streams every original row.
            widths = [min(48, max(14, len(column["header"]) + 3)) for column in columns]
            with self._rows(source) as rows:
                for ordinal, values in enumerate(rows):
                    stopped()
                    for index, (column, key) in enumerate(zip(columns, keys)):
                        value, _, _ = project_cell(values[key], column)
                        if value is not None:
                            text = value.isoformat() if isinstance(value, (date, datetime)) else _display(value)
                            longest = max((len(line) for line in text.splitlines()), default=0)
                            widths[index] = min(48, max(widths[index], longest + 2))
                    if ordinal >= 63:
                        break
            return widths

        def new_sheet(name, columns, row_count, widths=None):
            sheet = workbook.create_sheet(name)
            sheet.freeze_panes = "A2"
            sheet.sheet_view.showGridLines = True
            sheet.auto_filter.ref = f"A1:{get_column_letter(len(columns))}{row_count + 1}"
            # Wide values remain complete original cells. Type-aware widths and
            # wrapping make identifiers and prose readable in Excel and printed
            # pages without changing their projection, precision or null meaning.
            compact = {"integer": 18, "number": 18, "boolean": 16, "date": 16,
                       "datetime-utc": 28, "datetime-local": 26}
            for index, column in enumerate(columns, 1):
                width = widths[index - 1] if widths is not None else compact.get(column.get("type"), 32)
                sheet.column_dimensions[get_column_letter(index)].width = min(48, max(width, len(column["header"]) + 3))
            sheet.print_title_rows = "1:1"
            sheet.sheet_properties.pageSetUpPr.fitToPage = False
            sheet.page_setup.orientation = "landscape" if len(columns) > 5 else "portrait"
            sheet.print_options.gridLines = True
            sheet.append([cell(sheet, _literal(column["header"]), heading=True) for column in columns])
            return sheet

        try:
            write(target / "definition.json", raw)
            definition_history = self.refresh.retain_history(definition, target, cancel=cancel)
            for ordinal, logical in enumerate(definition["sheets"]):
                stopped()
                source = logical["source"]
                keys = [_source_key(source, column) for column in logical["columns"]]
                if self.source(source) != source:
                    _error("SOURCE_CHANGED")
                self._retain_source(source, target)
                expected = source["row_count"]
                widths = source_widths(source, logical["columns"], keys)
                counts, row_count, physical_index = {}, 0, 0
                sheet = new_sheet(layout[ordinal][0], logical["columns"], min(expected, _ROWS_PER_SHEET), widths)
                with self._rows(source) as stream:
                    for values in stream:
                        stopped()
                        if row_count and row_count % _ROWS_PER_SHEET == 0:
                            physical_index += 1
                            sheet = new_sheet(layout[ordinal][physical_index], logical["columns"], min(expected - row_count, _ROWS_PER_SHEET), widths)
                        cells = []
                        for index, (column, key) in enumerate(zip(logical["columns"], keys)):
                            value, format, conversion = project_cell(values[key], column)
                            cells.append(cell(sheet, value, format))
                            if conversion:
                                key = str(index) + ":" + conversion
                                counts[key] = counts.get(key, 0) + 1
                        sheet.append(cells)
                        row_count += 1
                        total_rows += 1
                        if row_count % 1000 == 0:
                            progress({"sheet": logical["name"], "sheet_rows": row_count, "total_rows": total_rows, "expected_rows": sum(s["source"]["row_count"] for s in definition["sheets"])})
                if row_count != expected:
                    _error("SOURCE_ROW_COUNT_CHANGED")
                outputs.append({"name": logical["name"], "worksheets": layout[ordinal], "row_count": row_count,
                                "source": source, "columns": logical["columns"], "conversions": counts})
                progress({"sheet": logical["name"], "sheet_rows": row_count, "total_rows": total_rows})
            # Open on the delivery's context, with the complete data tabs in
            # their original logical order immediately afterward.
            readme = workbook.create_sheet("Readme", 0)
            workbook.active = 0
            readme.freeze_panes = "B2"
            readme.sheet_view.showGridLines = False
            readme.column_dimensions["A"].width = 28
            readme.column_dimensions["B"].width = 100
            readme.page_setup.orientation = "landscape"
            readme.sheet_properties.pageSetUpPr.fitToPage = True
            readme.page_setup.fitToWidth = 1
            readme.page_setup.fitToHeight = 0
            for key, value in [("Workbook", definition["title"]), ("Notes", definition["notes"]),
                               ("Saved definition", definition["name"] + " / revision " + str(definition["revision"])),
                               ("Definition SHA-256", definition_sha), ("Delivery", job_id),
                               ("Text and formulas", "All source strings are literal Excel text, including strings beginning with =. Source formulas are not evaluated."),
                               ("Precision", "Preserve keeps values beyond Excel's numeric precision as text. Excel-number is an explicit column choice. Decimal-text preserves original decimal spelling and scale."),
                               ("Null and empty text", "Each column selects a null label or an empty cell. Excel can display nulls and empty strings alike; the handoff retains their original typed values."),
                               ("Dates", "ISO dates use the 1900 date system. UTC timestamps require a timezone. Values before 1900 or beyond millisecond precision remain original text."),
                               ("Complete rows", "Each data sheet includes every selected source row. Larger results continue on numbered sheets, with a header repeated on each sheet."),
                               ("Offline handoff", "Open manifest.json and the original source exports alongside this workbook to recover exact input types, query bindings, and projections.")]:
                readme.append([cell(readme, key, heading=True), cell(readme, _literal(value))])
            if definition.get("refresh_origin"):
                origin = definition["refresh_origin"]
                readme.append([cell(readme, "Edition note", heading=True), cell(readme, _literal(origin["reason"]))])
                readme.append([cell(readme, "Previous definition", heading=True), cell(readme, origin["base_definition_file"])])
            meta = new_sheet("Sources", [{"header": h} for h in ["Sheet", "Source kind", "Source ID", "Source SHA-256", "Rows", "Input column", "Input ordinal", "Excel heading", "Type", "Null", "Precision"]], sum(len(s["columns"]) for s in outputs))
            for logical in outputs:
                for column in logical["columns"]:
                    values = [logical["name"], logical["source"]["kind"], logical["source"]["id"], logical["source"]["sha256"], logical["row_count"], column["source"], _source_key(logical["source"], column) + 1 if logical["source"]["kind"] == "report" else "", column["header"], column["type"], "blank" if column["null"] == "blank" else column["null_text"], column["precision"]]
                    meta.append([cell(meta, value) for value in values])
            stopped()
            workbook_path = target / "workbook.xlsx"
            with workbook_path.open("xb") as output:
                os.fchmod(output.fileno(), 0o600)
                workbook.save(output)
                output.flush()
                os.fsync(output.fileno())
            files = {}
            for path in sorted(target.rglob("*")):
                if path.is_file():
                    relative = path.relative_to(target).as_posix()
                    _relative(relative)
                    files[relative] = _file_record(path)
            manifest = {"schema": _SCHEMA, "complete": True, "id": job_id, "workspace_id": self.identity,
                        "name": definition["name"], "revision": definition["revision"], "title": definition["title"],
                        "definition_sha256": definition_sha, "created_at": _now(), "row_count": total_rows,
                        "sheets": outputs, "files": files, "definition_history": definition_history, "excel": {"date_system": "1900", "date_encoding": "ISO8601", "strings": "literal", "data_rows_per_sheet": _ROWS_PER_SHEET,
                        "presentation": {"version": 1, "opening_sheet": "Readme", "body_text": "wrapped",
                                         "column_widths": "typed-and-first-64-rows", "print_heading_rows": "1:1"}}}
            manifest_raw = _json(manifest).encode()
            if len(manifest_raw) > _MAX_MANIFEST:
                _error("MANIFEST_TOO_LARGE")
            write(target / "manifest.json", manifest_raw)
            stopped()
            with (target / "handoff.zip").open("xb") as output:
                os.fchmod(output.fileno(), 0o600)
                with zipfile.ZipFile(output, "w", compression=zipfile.ZIP_DEFLATED, compresslevel=6, allowZip64=True) as package:
                    for name in [*files, "manifest.json"]:
                        stopped()
                        info = zipfile.ZipInfo(name)
                        info.compress_type = zipfile.ZIP_DEFLATED
                        info.external_attr = 0o100600 << 16
                        with _open_private(target / name) as source, package.open(info, "w", force_zip64=True) as member:
                            shutil.copyfileobj(source, member, 1024 * 1024)
                output.flush()
                os.fsync(output.fileno())
            sync_directory(target)
            return self._completed(target, expected_definition=definition_sha, inspect=False)
        except BaseException:
            shutil.rmtree(target)
            raise
        finally:
            workbook.close()
            # openpyxl removes its worksheet staging files on successful save.
            # Close and remove only staging paths owned by this failed workbook.
            for sheet in workbook.worksheets:
                writer = getattr(sheet, "_writer", None)
                if writer is not None and isinstance(writer.out, str) and os.path.exists(writer.out):
                    try:
                        sheet.close()
                    finally:
                        Path(writer.out).unlink(missing_ok=True)

    def _completed(self, path, *, expected_definition, inspect=True):
        delivery = WorkbookDelivery(path)
        manifest = delivery.inspect() if inspect else delivery.manifest
        if manifest["definition_sha256"] != expected_definition:
            _error("DEFINITION_CHANGED")
        if manifest["id"] != path.name:
            _error("DELIVERY_ID_CHANGED")
        if inspect:
            try:
                delivery.verify_archive(path / "handoff.zip")
            except zipfile.BadZipFile:
                _error("COMPLETE_ARCHIVE_REQUIRED")
        files = [{"name": name, **(_file_record(path / name) if name == "handoff.zip" else
                   {"bytes": len(delivery.raw), "sha256": digest(delivery.raw)} if name == "manifest.json" else manifest["files"][name]), "mime": mime}
                 for name, mime in _MIMES.items()]
        return {"schema": _SCHEMA, "id": manifest["id"], "name": manifest["name"], "revision": manifest["revision"],
                "title": manifest["title"], "definition_sha256": expected_definition, "directory": str(path),
                "manifest_sha256": digest(delivery.raw), "row_count": manifest["row_count"],
                "sheets": manifest["sheets"], "files": files, "completed_at": manifest["created_at"]}

    def _progress(self, job_id, values):
        with self.database._connection() as db:
            db.execute("INSERT INTO sf_analysis_workbook_control(id,progress) VALUES(?,?) ON CONFLICT(id) DO UPDATE SET progress=excluded.progress", (job_id, _json({**values, "updated_at": _now()})))

    def progress(self, job_id):
        with self.database._connection(readonly=True) as db:
            row = db.execute("SELECT progress,cancel_requested FROM sf_analysis_workbook_control WHERE id=?", (_id(job_id),)).fetchone()
        return {**parse(row["progress"].encode()), "cancel_requested": bool(row["cancel_requested"])} if row else {}

    def cancel(self, job_id):
        job_id = _id(job_id)
        with self.database._connection() as db:
            row = db.execute("SELECT status FROM sf_analysis_jobs WHERE id=? AND kind='workbook'", (job_id,)).fetchone()
            if row is None:
                _error("NOT_FOUND")
            if row["status"] == "RUNNING":
                db.execute("INSERT INTO sf_analysis_workbook_control(id,cancel_requested,progress) VALUES(?,1,'{}') ON CONFLICT(id) DO UPDATE SET cancel_requested=1", (job_id,))
        with self._mutex:
            if job_id in self._signals:
                self._signals[job_id].set()
        return self.progress(job_id)

    def close(self):
        with self._mutex:
            self._closed = True
            for signal in self._signals.values():
                signal.set()

    def _finish(self, job_id, status, *, result=None, error=None):
        with self.database._connection() as db:
            db.execute("UPDATE sf_analysis_jobs SET status=?,result=?,error=?,finished_at=? WHERE id=? AND kind='workbook'", (status, _json(result) if result else None, error, _now(), job_id))

    def run(self, job_id, spec):
        job_id = _id(job_id)
        path = self.directory / job_id
        with self._mutex:
            signal = self._signals.setdefault(job_id, threading.Event())
            if self._closed or self.progress(job_id).get("cancel_requested"):
                signal.set()
        try:
            definition = self.definition(spec["name"], revision=spec["revision"])
            if definition["definition_sha256"] != spec["definition_sha256"]:
                _error("DEFINITION_CHANGED")
            result = self.build(definition["definition"], job_id, path, cancel=signal.is_set,
                                progress=lambda value: self._progress(job_id, value))
            self._finish(job_id, "COMPLETE", result=result)
        except BaseException as exc:
            try:
                result = self._completed(path, expected_definition=spec["definition_sha256"])
            except (BuyerError, OSError, ValueError, TypeError, KeyError):
                code = getattr(exc, "code", None) or type(exc).__name__
                self._finish(job_id, "CANCELLED" if code == "ANALYSIS_WORKBOOK_CANCELLED" else "FAILED", error=str(code)[:256])
            else:
                self._finish(job_id, "COMPLETE", result=result)
        finally:
            with self._mutex:
                self._signals.pop(job_id, None)

    def recover_completed(self):
        with self.database._connection(readonly=True) as db:
            rows = db.execute("SELECT id,request FROM sf_analysis_jobs WHERE kind='workbook' AND status IN ('INTERRUPTED','FAILED','CANCELLED')").fetchall()
        for row in rows:
            spec = parse(row["request"].encode())
            path = self.directory / row["id"]
            if not (path / "handoff.zip").is_file():
                continue
            try:
                result = self._completed(path, expected_definition=spec["definition_sha256"])
            except (BuyerError, OSError, ValueError, TypeError, KeyError):
                continue
            self._finish(row["id"], "COMPLETE", result=result)

    def history(self, *, before=None, limit=25):
        _page(before, limit)
        with self.database._connection(readonly=True) as db:
            rows = db.execute("SELECT sequence,id,status,created_at,finished_at,request,result,error FROM sf_analysis_jobs WHERE kind='workbook' AND (? IS NULL OR sequence<?) ORDER BY sequence DESC LIMIT ?", (before, before, limit + 1)).fetchall()
        items = []
        for row in rows[:limit]:
            request = parse(row["request"].encode())
            item = {key: row[key] for key in ("sequence", "id", "status", "created_at", "finished_at", "error")}
            item.update(name=request["name"], revision=request["revision"], progress=self.progress(row["id"]))
            if row["result"]:
                result = parse(row["result"].encode())
                item.update(row_count=result["row_count"], sheets=len(result["sheets"]), files=result["files"], title=result["title"], manifest_sha256=result["manifest_sha256"])
            items.append(item)
        return {"items": items, "next_before": rows[limit - 1]["sequence"] if len(rows) > limit else None}

    @contextmanager
    def download(self, job_id, name):
        job_id = _id(job_id)
        if name not in _MIMES:
            _error("FILE_INVALID")
        with self.database._connection(readonly=True) as db:
            row = db.execute("SELECT result FROM sf_analysis_jobs WHERE id=? AND kind='workbook' AND status='COMPLETE'", (job_id,)).fetchone()
        if row is None or row["result"] is None:
            _error("COMPLETE_DELIVERY_REQUIRED")
        result = parse(row["result"].encode())
        path = self.directory / job_id
        delivery = WorkbookDelivery(path, expected_manifest_sha256=result["manifest_sha256"])
        record = next((f for f in result["files"] if f["name"] == name), None)
        if record is None:
            _error("FILE_INVALID")
        if name == "handoff.zip":
            with _open_private(path / name) as stream:
                if os.fstat(stream.fileno()).st_size != record["bytes"] or hashlib.file_digest(stream, "sha256").hexdigest() != record["sha256"]:
                    _error("FILE_CHANGED")
                stream.seek(0)
                yield stream, record
        else:
            with delivery.open(name) as stream:
                yield stream, record


def main():
    parser = argparse.ArgumentParser(description="Inspect, receive or copy a complete customer workbook handoff offline.")
    commands = parser.add_subparsers(dest="command", required=True)
    inspect = commands.add_parser("inspect")
    inspect.add_argument("--delivery", required=True)
    inspect.add_argument("--manifest-sha256")
    copy = commands.add_parser("copy")
    copy.add_argument("--delivery", required=True)
    copy.add_argument("--destination", required=True)
    copy.add_argument("--manifest-sha256")
    receive = commands.add_parser("receive")
    receive.add_argument("--archive", required=True)
    receive.add_argument("--destination", required=True)
    receive.add_argument("--sha256")
    receive.add_argument("--max-bytes", type=int, default=1024 * 1024 * 1024)
    args = parser.parse_args()
    if args.command == "receive":
        delivery = WorkbookDelivery.receive(args.archive, args.destination, expected_sha256=args.sha256, max_bytes=args.max_bytes)
    else:
        delivery = WorkbookDelivery(args.delivery, expected_manifest_sha256=args.manifest_sha256)
        if args.command == "copy":
            delivery = delivery.copy_to(args.destination)
    print(_json(delivery.inspect()))


if __name__ == "__main__":
    main()

"""Complete retained-edition review in the original customer analysis database."""
from __future__ import annotations

import csv
from datetime import datetime, timezone
import hashlib
import io
import json
import os
from pathlib import Path
import re
import sqlite3
import stat
import tempfile
import time

from .errors import StateError
from .sqlite_dataset import _identifier, _view_name
from .storage import digest, parse, private_directory, sync_directory

_ID = re.compile(r"[a-f0-9]{32}")
_HEX = re.compile(r"[a-f0-9]{64}")
_KINDS = ("added", "removed", "changed", "moved")
_MISSING = {"type": "missing", "text": ""}
_MAX_RECORD_BYTES = 128 * 1024 * 1024
_SCHEMA = "stellar-forge.customer-dataset-comparison.v1"


def _json(value):
    return json.dumps(value, ensure_ascii=False, allow_nan=False, sort_keys=True, separators=(",", ":"))


def _now():
    return datetime.now(timezone.utc).isoformat()


def _cell(value):
    if value is None:
        return {"type": "null", "text": ""}
    if type(value) is int:
        return {"type": "integer", "text": str(value)}
    if type(value) is float:
        return {"type": "number", "text": repr(value)}
    if isinstance(value, str):
        return {"type": "string", "text": value}
    raise StateError("DATASET_CHANGE_SQL_SCALAR_REQUIRED")


def _id(value):
    if not isinstance(value, str) or not _ID.fullmatch(value):
        raise StateError("DATASET_CHANGE_REQUEST_ID_REQUIRED")
    return value


def _view(db, name):
    row = db.execute("SELECT name,version_id,revision FROM sf_dataset_views WHERE name=?", (_view_name(name),)).fetchone()
    return dict(row) if row else None


class DatasetChanges:
    """One complete comparison, its exact review, and reproducible exports.

    SQL values use the original database's no-affinity representation. Original
    Boolean/number type declarations remain visible as separate source metadata.
    """

    def __init__(self, database):
        self.database = database
        # AnalysisWorkspace already holds its exclusive process lock. No export
        # worker is live at startup. Retire only our private incomplete exports,
        # including the extra temporary hardlink from an interrupted publish.
        directory = database.directory / "analysis-exports"
        if directory.exists() or directory.is_symlink():
            private_directory(directory, create=False)
            for path in directory.iterdir():
                if re.fullmatch(r"\.changes-[A-Za-z0-9_-]+", path.name):
                    info = path.lstat()
                    if stat.S_ISREG(info.st_mode) and not info.st_mode & 0o077:
                        path.unlink()
            sync_directory(directory)
        with database._connection() as db:
            db.executescript("""
CREATE TABLE IF NOT EXISTS sf_analysis_change_rows(
 job_id TEXT NOT NULL REFERENCES sf_analysis_jobs(id),ordinal INTEGER NOT NULL,
 kind TEXT NOT NULL,record TEXT NOT NULL,sha256 TEXT NOT NULL,
 PRIMARY KEY(job_id,ordinal));
CREATE INDEX IF NOT EXISTS sf_analysis_change_kind ON sf_analysis_change_rows(job_id,kind,ordinal);
CREATE TABLE IF NOT EXISTS sf_analysis_change_selections(
 id TEXT PRIMARY KEY,job_id TEXT UNIQUE NOT NULL REFERENCES sf_analysis_jobs(id),
 request_sha256 TEXT NOT NULL,record TEXT NOT NULL);
""")

    def prepare(self, request, *, check=True):
        name = _view_name(request.get("view"))
        revision = request.get("expected_revision")
        base, candidate = request.get("base_version_id"), request.get("candidate_version_id")
        if type(revision) is not int or revision < 1 or any(not isinstance(v, str) or not _HEX.fullmatch(v) for v in (base, candidate)):
            raise StateError("DATASET_CHANGE_REVIEWED_VERSIONS_REQUIRED")
        keys = request.get("keys")
        if not isinstance(keys, list) or not 1 <= len(keys) <= 16 or not all(isinstance(k, str) for k in keys) or len(set(keys)) != len(keys):
            raise StateError("DATASET_CHANGE_SELECT_ONE_TO_SIXTEEN_KEYS")
        spec = {"view": name, "expected_revision": revision, "base_version_id": base,
                "candidate_version_id": candidate, "keys": keys}
        if check:
            with self.database._connection(readonly=True) as db:
                db.execute("BEGIN")
                self._inputs(db, spec)
        return spec

    def _inputs(self, db, spec):
        current = _view(db, spec["view"])
        if current is None or current["version_id"] != spec["base_version_id"] or current["revision"] != spec["expected_revision"]:
            raise StateError("DATASET_CHANGE_CURRENT_VIEW_CHANGED")
        versions = [self.database._version(db, spec[key]) for key in ("base_version_id", "candidate_version_id")]
        for version in versions:
            manifest = db.execute("SELECT manifest FROM sf_dataset_versions WHERE version_id=?", (version["version_id"],)).fetchone()[0]
            if digest(manifest) != version["manifestSha256"]:
                raise StateError("DATASET_SQL_RETAINED_MANIFEST_CHANGED")
            columns = [item["column"] for item in version["column_types"]]
            if any(key not in columns for key in spec["keys"]):
                raise StateError("DATASET_CHANGE_KEYS_MUST_EXIST_IN_BOTH_VERSIONS")
        return current, *versions

    def run(self, job_id, spec):
        """Complete every row or roll the entire report back; never sample."""
        _id(job_id)
        deadline = time.monotonic() + 120
        with self.database._connection() as db:
            db.execute("PRAGMA temp_store=FILE")
            db.execute("PRAGMA temp.cache_size=-4096")
            db.execute("BEGIN IMMEDIATE")
            db.set_progress_handler(lambda: int(time.monotonic() > deadline), 10000)
            try:
                current, baseline, candidate = self._inputs(db, spec)
                before_columns = [c["column"] for c in baseline["column_types"]]
                after_columns = [c["column"] for c in candidate["column_types"]]
                columns = before_columns + [c for c in after_columns if c not in before_columns]
                for side, version in (("before", baseline), ("after", candidate)):
                    temp = "sf_change_" + side
                    db.execute(f"CREATE TEMP TABLE {temp}(key TEXT PRIMARY KEY COLLATE BINARY,row_number INTEGER NOT NULL) WITHOUT ROWID")
                    select = ",".join(_identifier(c) for c in [version["row_order_column"], *spec["keys"]])
                    scanned = 0
                    for row in db.execute(f"SELECT {select} FROM {_identifier(version['table'])} ORDER BY {_identifier(version['row_order_column'])}"):
                        if time.monotonic() > deadline:
                            raise StateError("DATASET_CHANGE_DEADLINE_EXCEEDED")
                        scanned += 1
                        if any(v is None for v in tuple(row)[1:]):
                            raise StateError("DATASET_CHANGE_NULL_KEY:" + side + ":row=" + str(row[0]))
                        key = _json([_cell(v) for v in tuple(row)[1:]])
                        try:
                            db.execute(f"INSERT INTO {temp} VALUES(?,?)", (key, row[0]))
                        except sqlite3.IntegrityError:
                            raise StateError("DATASET_CHANGE_DUPLICATE_KEY:" + side + ":row=" + str(row[0])) from None
                    if scanned != version["row_count"]:
                        raise StateError("DATASET_CHANGE_RETAINED_ROW_COUNT_CHANGED")
                cursor = db.execute("""SELECT * FROM (
 SELECT b.key AS key,b.row_number AS before_number,a.row_number AS after_number
 FROM sf_change_before b LEFT JOIN sf_change_after a ON a.key=b.key
 UNION ALL
 SELECT a.key,NULL,a.row_number FROM sf_change_after a
 LEFT JOIN sf_change_before b ON b.key=a.key WHERE b.key IS NULL
) ORDER BY key COLLATE BINARY""")
                counts = {key: 0 for key in (*_KINDS, "unchanged")}
                fields = {column: 0 for column in columns}
                row_digest, before_digest, after_digest = (hashlib.sha256() for _ in range(3))
                ordinal = payload_bytes = positions_changed = 0
                for joined in cursor:
                    if time.monotonic() > deadline:
                        raise StateError("DATASET_CHANGE_DEADLINE_EXCEEDED")
                    values = []
                    for version, names, number, observed in (
                        (baseline, before_columns, joined["before_number"], before_digest),
                        (candidate, after_columns, joined["after_number"], after_digest)):
                        if number is None:
                            values.append(None)
                            continue
                        source = db.execute(f"SELECT " + ",".join(_identifier(c) for c in names) +
                            f" FROM {_identifier(version['table'])} WHERE {_identifier(version['row_order_column'])}=?", (number,)).fetchone()
                        if source is None:
                            raise StateError("DATASET_CHANGE_RETAINED_ROW_MISSING")
                        mapped = dict(zip(names, [_cell(v) for v in source]))
                        cells = [mapped.get(c, _MISSING) for c in columns]
                        observed.update((_json({"key": joined["key"], "row_number": number, "values": cells}) + "\n").encode())
                        values.append(cells)
                    before, after = values
                    changed = [columns[i] for i in range(len(columns)) if before is None or after is None or before[i] != after[i]]
                    moved = before is not None and after is not None and joined["before_number"] != joined["after_number"]
                    positions_changed += int(moved)
                    kind = "added" if before is None else "removed" if after is None else "changed" if changed else "moved" if moved else "unchanged"
                    counts[kind] += 1
                    if kind == "unchanged":
                        continue
                    for column in changed:
                        fields[column] += 1
                    ordinal += 1
                    record = {"ordinal": ordinal, "kind": kind, "key": parse(joined["key"].encode()),
                        "before_row_number": joined["before_number"], "after_row_number": joined["after_number"],
                        "before": before, "after": after, "changed_columns": changed}
                    raw = _json(record)
                    encoded = (raw + "\n").encode()
                    payload_bytes += len(encoded)
                    if payload_bytes > _MAX_RECORD_BYTES:
                        raise StateError("DATASET_CHANGE_REPORT_EXCEEDS_128_MIB")
                    row_digest.update(encoded)
                    db.execute("INSERT INTO sf_analysis_change_rows VALUES(?,?,?,?,?)", (job_id, ordinal, kind, raw, digest(raw.encode())))
                before_types = {c["column"]:c["json_types"] for c in baseline["column_types"]}
                after_types = {c["column"]:c["json_types"] for c in candidate["column_types"]}
                report = {"schema": _SCHEMA, "id": job_id, "completed_at": _now(), "complete": True,
                    "reviewed_view": current, "keys": spec["keys"], "columns": columns,
                    "baseline": baseline, "candidate": candidate, "counts": counts, "positions_changed": positions_changed,
                    "field_changes": fields, "schema_changes": {"added": [c for c in after_columns if c not in before_columns],
                        "removed": [c for c in before_columns if c not in after_columns],
                        "original_json_types": [{"column": c, "before": before_types[c], "after": after_types[c]} for c in before_columns if c in after_types and before_types[c] != after_types[c]]},
                    "changed_rows": ordinal, "record_bytes": payload_bytes, "rows_sha256": row_digest.hexdigest(),
                    "baseline_observation_sha256": before_digest.hexdigest(), "candidate_observation_sha256": after_digest.hexdigest(),
                    "value_basis": "original SQLite scalars; original JSON type declarations retained separately"}
                report["result_sha256"] = digest(_json(report).encode())
                updated = db.execute("UPDATE sf_analysis_jobs SET status='COMPLETE',result=?,finished_at=? WHERE id=? AND kind='compare' AND status='RUNNING'",
                    (_json(report), report["completed_at"], job_id)).rowcount
                if updated != 1:
                    raise StateError("DATASET_CHANGE_JOB_NOT_RUNNING")
                db.commit()
                return report
            except BaseException as exc:
                db.set_progress_handler(None, 0)
                db.rollback()
                if isinstance(exc, sqlite3.OperationalError) and time.monotonic() > deadline:
                    raise StateError("DATASET_CHANGE_DEADLINE_EXCEEDED") from exc
                raise
            finally:
                db.set_progress_handler(None, 0)

    @staticmethod
    def _report(db, job_id):
        row = db.execute("SELECT status,result FROM sf_analysis_jobs WHERE id=? AND kind='compare'", (_id(job_id),)).fetchone()
        if row is None or row["status"] != "COMPLETE" or row["result"] is None:
            raise StateError("DATASET_CHANGE_COMPLETE_REPORT_REQUIRED")
        result = parse(row["result"].encode())
        if result.get("result_sha256") != digest(_json({k:v for k,v in result.items() if k != "result_sha256"}).encode()):
            raise StateError("DATASET_CHANGE_RETAINED_REPORT_CHANGED")
        return result

    @staticmethod
    def _selection(db, job_id):
        row = db.execute("SELECT record FROM sf_analysis_change_selections WHERE job_id=?", (job_id,)).fetchone()
        return parse(row[0].encode()) if row else None

    @staticmethod
    def _record(row):
        if digest(row["record"].encode()) != row["sha256"]:
            raise StateError("DATASET_CHANGE_RETAINED_ROW_CHANGED")
        return parse(row["record"].encode())

    def history(self, *, before=None, limit=25):
        if type(limit) is not int or not 1 <= limit <= 100 or before is not None and (type(before) is not int or before < 1):
            raise StateError("DATASET_CHANGE_HISTORY_PAGE_INVALID")
        with self.database._connection(readonly=True) as db:
            rows = db.execute("SELECT sequence,id,status,created_at,finished_at,error,result FROM sf_analysis_jobs WHERE kind='compare' AND (? IS NULL OR sequence<?) ORDER BY sequence DESC LIMIT ?", (before,before,limit+1)).fetchall()
        values=[]
        for row in rows[:limit]:
            item=dict(row);report=parse(item.pop("result").encode()) if row["result"] else None
            item.update(view=report["reviewed_view"]["name"] if report else None, counts=report["counts"] if report else None)
            values.append(item)
        return {"comparisons":values,"next_before":rows[limit-1]["sequence"] if len(rows)>limit else None}

    def page(self, job_id, *, kind="all", after=0, limit=50):
        if kind not in ("all", *_KINDS) or type(after) is not int or after < 0 or type(limit) is not int or not 1 <= limit <= 100:
            raise StateError("DATASET_CHANGE_PAGE_INVALID")
        with self.database._connection(readonly=True) as db:
            db.execute("BEGIN")
            report=self._report(db,job_id)
            cursor=db.execute("SELECT * FROM sf_analysis_change_rows WHERE job_id=? AND ordinal>? AND (?='all' OR kind=?) ORDER BY ordinal LIMIT ?", (job_id,after,kind,kind,limit+1))
            rows=[];page_bytes=0;more=False
            for row in cursor:
                size=len(row["record"].encode())
                if rows and (len(rows)==limit or page_bytes+size>4*1024*1024):
                    more=True;break
                rows.append(row);page_bytes+=size
            selection = self._selection(db,job_id)
            return {"report":report,"selection":selection,"selection_sha256":digest(_json(selection).encode()),"current_view":_view(db,report["reviewed_view"]["name"]),
                "kind":kind,"after":after,"rows":[self._record(row) for row in rows],
                "next_after":rows[-1]["ordinal"] if more else None}

    def select(self, job_id, request):
        key=_id(request.get("id"));note=request.get("note", "")
        if not isinstance(note,str) or len(note.encode())>8000:
            raise StateError("DATASET_CHANGE_REVIEW_NOTE_INVALID")
        spec={"id":key,"comparison_id":_id(job_id),"result_sha256":request.get("result_sha256"),"note":note}
        request_sha=digest(_json(spec).encode())
        with self.database._connection() as db:
            db.execute("BEGIN IMMEDIATE")
            old=db.execute("SELECT request_sha256,record FROM sf_analysis_change_selections WHERE id=?", (key,)).fetchone()
            if old:
                if old["request_sha256"]!=request_sha:
                    raise StateError("DATASET_CHANGE_REVIEW_ID_REUSED")
                return parse(old["record"].encode())
            report=self._report(db,job_id)
            if report["result_sha256"]!=spec["result_sha256"]:
                raise StateError("DATASET_CHANGE_REVIEWED_REPORT_CHANGED")
            if self._selection(db,job_id):
                raise StateError("DATASET_CHANGE_REPORT_ALREADY_SELECTED")
            self._verify_rows(db,report)
            activation=self.database._activate(db,report["reviewed_view"]["name"],report["candidate"]["version_id"],expected_revision=report["reviewed_view"]["revision"])
            record={**spec,"selected_at":_now(),"activation":activation,"previous_view":report["reviewed_view"]}
            db.execute("INSERT INTO sf_analysis_change_selections VALUES(?,?,?,?)", (key,job_id,request_sha,_json(record)))
            db.commit()
            return record

    def _verify_rows(self, db, report):
        observed=hashlib.sha256();count=0
        for row in db.execute("SELECT * FROM sf_analysis_change_rows WHERE job_id=? ORDER BY ordinal", (report["id"],)):
            self._record(row);count+=1
            if row["ordinal"]!=count:
                raise StateError("DATASET_CHANGE_RETAINED_ROW_MISSING")
            observed.update((row["record"]+"\n").encode())
        if count!=report["changed_rows"] or observed.hexdigest()!=report["rows_sha256"]:
            raise StateError("DATASET_CHANGE_RETAINED_ROWS_CHANGED")

    def prepare_export(self, request, *, check=True):
        if request.get("format") not in ("json", "csv"):
            raise StateError("DATASET_CHANGE_EXPORT_FORMAT_INVALID")
        spec={"comparison_id":_id(request.get("comparison_id")),"result_sha256":request.get("result_sha256"),
              "format":request["format"],"selection_sha256":request.get("selection_sha256")}
        if any(not isinstance(spec[k],str) or not _HEX.fullmatch(spec[k]) for k in ("result_sha256","selection_sha256")):
            raise StateError("DATASET_CHANGE_EXACT_REPORT_AND_REVIEW_REQUIRED")
        if check:
            with self.database._connection(readonly=True) as db:
                db.execute("BEGIN")
                self._export_input(db,spec)
        return spec

    def _export_input(self, db, spec):
        report=self._report(db,spec["comparison_id"])
        selection=self._selection(db,report["id"])
        if report["result_sha256"]!=spec["result_sha256"] or digest(_json(selection).encode())!=spec["selection_sha256"]:
            raise StateError("DATASET_CHANGE_EXPORT_REVIEW_CHANGED")
        return report,selection

    def _export_blocks(self, db, report, selection, format):
        if format=="json":
            yield ('{"schema":"'+_SCHEMA+'","report":'+_json(report)+',"selection":'+_json(selection)+',"changes":[').encode()
            first=True
            for row in db.execute("SELECT * FROM sf_analysis_change_rows WHERE job_id=? ORDER BY ordinal", (report["id"],)):
                self._record(row)
                yield (("" if first else ",")+row["record"]).encode();first=False
            yield b"]}\n"
        else:
            stream=io.StringIO(newline="");writer=csv.writer(stream)
            def line(values):
                stream.seek(0);stream.truncate();writer.writerow(values);return stream.getvalue().encode()
            identity=[report["id"],report["result_sha256"],report["baseline"]["version_id"],report["baseline"]["manifestSha256"],
                      report["candidate"]["version_id"],report["candidate"]["manifestSha256"],selection["id"] if selection else "",
                      digest(_json(selection).encode()),report["reviewed_view"]["name"],report["reviewed_view"]["revision"],
                      selection["activation"]["revision"] if selection else ""]
            yield line(["record_type","comparison_id","result_sha256","baseline_version_id","baseline_manifest_sha256",
                        "candidate_version_id","candidate_manifest_sha256","selection_id","selection_sha256","view_name","reviewed_view_revision","selected_view_revision",
                        "change","key_json","before_row_number","after_row_number","column","before_type","before_value","after_type","after_value","scope_json"])
            scope={"schema":_SCHEMA,"baseline":report["baseline"]["dataset"],"candidate":report["candidate"]["dataset"],
                   "counts":report["counts"],"schema_changes":report["schema_changes"],"keys":report["keys"],
                   "rows_sha256":report["rows_sha256"],"selection":selection,"value_basis":report["value_basis"]}
            # An unchanged comparison still exports its complete source identity.
            yield line(["comparison",*identity,*([""]*9),_json(scope)])
            for row in db.execute("SELECT * FROM sf_analysis_change_rows WHERE job_id=? ORDER BY ordinal", (report["id"],)):
                record=self._record(row)
                indices=[report["columns"].index(c) for c in record["changed_columns"]]
                if record["kind"]=="moved":
                    yield line(["difference",*identity,record["kind"],_json(record["key"]),record["before_row_number"],record["after_row_number"],"_sf_row_number","integer",record["before_row_number"],"integer",record["after_row_number"],""])
                for i in indices:
                    before=record["before"][i] if record["before"] is not None else _MISSING
                    after=record["after"][i] if record["after"] is not None else _MISSING
                    yield line(["difference",*identity,record["kind"],_json(record["key"]),record["before_row_number"],record["after_row_number"],report["columns"][i],before["type"],before["text"],after["type"],after["text"],""])

    def export(self, spec):
        directory=private_directory(self.database.directory/"analysis-exports")
        identity=digest(_json({"schema":_SCHEMA,**spec}).encode())
        destination=directory/("changes-"+identity+"."+spec["format"])
        temporary=None;existing=None;target=None;reused=False
        try:
            if destination.exists() or destination.is_symlink():
                fd=os.open(destination,os.O_RDONLY|os.O_NOFOLLOW)
                info=os.fstat(fd)
                if not stat.S_ISREG(info.st_mode) or info.st_mode&0o077 or info.st_nlink!=1:
                    os.close(fd);raise StateError("DATASET_CHANGE_PRIVATE_EXPORT_REQUIRED")
                existing=os.fdopen(fd,"rb")
                reused=True
            else:
                fd,temporary=tempfile.mkstemp(prefix=".changes-",dir=directory)
                target=os.fdopen(fd,"wb")
            observed=hashlib.sha256();size=0
            with self.database._connection(readonly=True) as db:
                db.execute("BEGIN")
                report,selection=self._export_input(db,spec)
                self._verify_rows(db,report)
                for block in self._export_blocks(db,report,selection,spec["format"]):
                    observed.update(block);size+=len(block)
                    if existing:
                        if existing.read(len(block))!=block:
                            raise StateError("DATASET_CHANGE_RETAINED_EXPORT_CHANGED")
                    else:
                        target.write(block)
                if existing:
                    if existing.read(1):
                        raise StateError("DATASET_CHANGE_RETAINED_EXPORT_CHANGED")
                else:
                    target.flush();os.fsync(target.fileno());target.close();target=None
            if temporary is not None:
                try:
                    os.link(temporary,destination)
                except FileExistsError:
                    fd=os.open(destination,os.O_RDONLY|os.O_NOFOLLOW)
                    with os.fdopen(fd,"rb") as other:
                        info=os.fstat(other.fileno())
                        if not stat.S_ISREG(info.st_mode) or info.st_mode&0o077 or info.st_nlink!=1 or info.st_size!=size or hashlib.file_digest(other,"sha256").hexdigest()!=observed.hexdigest():
                            raise StateError("DATASET_CHANGE_RETAINED_EXPORT_CHANGED")
                    reused=True
                Path(temporary).unlink()
                temporary=None
                sync_directory(directory)
            return {"path":str(destination),"bytes":size,"sha256":observed.hexdigest(),"filename":destination.name,
                "mime":"application/json" if spec["format"]=="json" else "text/csv;charset=utf-8",
                "comparison_id":report["id"],"result_sha256":report["result_sha256"],"selection_sha256":spec["selection_sha256"],"reused":reused}
        finally:
            if target:target.close()
            if existing:existing.close()
            if temporary is not None:
                Path(temporary).unlink(missing_ok=True)

"""Complete column profiles on the original immutable customer dataset tables.

No data acquisition or SQL-store replacement. Frequencies are grouped by native
storage class AND value, so integer 1, real 1.0 and text '1' remain distinct.
"""
from __future__ import annotations

from datetime import datetime, timezone
import hashlib
import html
import json
import math
from pathlib import Path
import re
import sqlite3
import threading
import time

from .errors import StateError
from .sqlite_dataset import _identifier
from .storage import digest, parse, read, write

SCHEMA = "stellar-forge.customer-data-profile.v1"
DOCUMENT = "stellar-forge.customer-data-profile-document.v1"
COMPARISON = "stellar-forge.customer-data-profile-comparison.v1"
_ID = re.compile(r"[a-f0-9]{32}")
_SHA = re.compile(r"[a-f0-9]{64}")
_MAX_DOCUMENT = 32 * 1024 * 1024
_METRICS = ("rows", "null_rows", "empty_text_rows", "whitespace_text_rows", "distinct_nonnull", "duplicate_nonnull_rows")


def _json(value):
    return json.dumps(value, ensure_ascii=False, allow_nan=False, sort_keys=True, separators=(",", ":"))


def _now():
    return datetime.now(timezone.utc).isoformat()


def _id(value):
    if not isinstance(value, str) or not _ID.fullmatch(value):
        raise StateError("DATA_PROFILE_REQUEST_ID_REQUIRED")
    return value


def _sha(value):
    if not isinstance(value, str) or not _SHA.fullmatch(value):
        raise StateError("DATA_PROFILE_DIGEST_REQUIRED")
    return value


def _sealed(value, key="sha256"):
    return {**value, key: digest(_json(value).encode())}


def _verified(value, key="sha256"):
    if not isinstance(value, dict) or value.get(key) != digest(_json({k: v for k, v in value.items() if k != key}).encode()):
        raise StateError("DATA_PROFILE_RETAINED_RECORD_CHANGED")
    return value


def _value(value, *, preview=384):
    """Exact scalar text; long strings carry an explicitly abbreviated preview."""
    if value is None:
        return {"type": "null", "text": ""}
    if type(value) is int:
        return {"type": "integer", "text": str(value)}
    if type(value) is float and math.isfinite(value):
        return {"type": "real", "text": repr(value)}
    if isinstance(value, str):
        raw = value.encode()
        return {"type": "text", "text": value[:preview], "truncated": len(value) > preview,
                "characters": len(value), "utf8_bytes": len(raw), "sha256": digest(raw)}
    raise StateError("DATA_PROFILE_NATIVE_SCALAR_REQUIRED")


def _portable_version(version):
    # Retain original delivery/query scope, but not the operator's private paths.
    return {key: version[key] for key in (
        "version_id", "manifestSha256", "sourceBindingSha256", "columns", "dataset", "column_types",
        "row_count", "jsonl", "row_representation", "originalPaymentStatus", "source_pages") if key in version}


def compare_profiles(before, after):
    """Compare exact complete profile metrics, not sampled rows or inferred drift."""
    before, after = _verified(before), _verified(after)
    if before.get("schema") != SCHEMA or after.get("schema") != SCHEMA:
        raise StateError("DATA_PROFILE_FORMAT_MISMATCH")
    left = {c["column"]: c for c in before["columns"]}
    right = {c["column"]: c for c in after["columns"]}
    columns = []
    for name in [*left, *(name for name in right if name not in left)]:
        b, a = left.get(name), right.get(name)
        changed = b is None or a is None or any(b.get(k) != a.get(k) for k in (
            *_METRICS, "storage_classes", "numeric_min", "numeric_max", "text_min", "text_max", "value_distribution_sha256", "original_json_types", "source_field"))
        columns.append({"column": name, "status": "added" if b is None else "removed" if a is None else "changed" if changed else "unchanged",
            "before": b, "after": a, "deltas": {k: a[k] - b[k] for k in _METRICS} if a and b else None})
    return _sealed({"schema": COMPARISON, "before_id": before["id"], "after_id": after["id"],
        "before_sha256": before["sha256"], "after_sha256": after["sha256"],
        "before_source": before["source"], "after_source": after["source"],
        "row_delta": after["row_count"] - before["row_count"], "columns": columns,
        "basis": "column names as stored; original field mappings and acquisition scopes remain visible; no causal or statistical drift claim"})


class _Stopped(Exception):
    pass


class DatasetProfiles:
    """Saved profiles and optimistic analyst reviews in AnalysisWorkspace's DB."""

    def __init__(self, database):
        self.database = database
        self._mutex = threading.Lock()
        self._active = {}
        self._closing = False
        with database._connection() as db:
            db.execute("""CREATE TABLE IF NOT EXISTS sf_analysis_profile_reviews(
                sequence INTEGER PRIMARY KEY,job_id TEXT NOT NULL REFERENCES sf_analysis_jobs(id),
                revision INTEGER NOT NULL,request_id TEXT NOT NULL UNIQUE,request_sha256 TEXT NOT NULL,
                record TEXT NOT NULL,UNIQUE(job_id,revision))""")

    def prepare(self, request):
        version_id = _sha(request.get("version_id"))
        columns = request.get("columns")
        if columns is not None and (not isinstance(columns, list) or not columns or not all(isinstance(c, str) for c in columns)
                                    or len(set(columns)) != len(columns)):
            raise StateError("DATA_PROFILE_COLUMNS_INVALID")
        top = request.get("top_values", 12)
        timeout = request.get("timeout", 3600)
        if type(top) is not int or not 1 <= top <= 50 or type(timeout) is not int or not 1 <= timeout <= 86400:
            raise StateError("DATA_PROFILE_OPTIONS_INVALID")
        return {"version_id": version_id, "columns": columns, "top_values": top, "timeout": timeout}

    def validate(self, db, spec):
        version = self.database._version(db, spec["version_id"])
        manifest = db.execute("SELECT manifest FROM sf_dataset_versions WHERE version_id=?", (spec["version_id"],)).fetchone()[0]
        if digest(manifest) != version["manifestSha256"]:
            raise StateError("DATA_PROFILE_MANIFEST_CHANGED")
        available = [c["column"] for c in version["column_types"]]
        if spec["columns"] is not None and any(c not in available for c in spec["columns"]):
            raise StateError("DATA_PROFILE_COLUMN_NOT_IN_VERSION")
        if version["table"] != "sf_dataset_rows_" + spec["version_id"]:
            raise StateError("DATA_PROFILE_ORIGINAL_TABLE_REQUIRED")
        return version

    def _progress(self, job_id, **values):
        with self._mutex:
            self._active[job_id]["progress"].update(values)

    def progress(self, job_id):
        _id(job_id)
        with self._mutex:
            item = self._active.get(job_id)
            return dict(item["progress"]) if item else None

    def cancel(self, job_id):
        _id(job_id)
        with self.database._connection(readonly=True) as db:
            row = db.execute("SELECT kind,status FROM sf_analysis_jobs WHERE id=?", (job_id,)).fetchone()
        if row is None or row["kind"] != "profile":
            raise StateError("DATA_PROFILE_JOB_NOT_FOUND")
        if row["status"] != "RUNNING":
            return {"id": job_id, "status": row["status"], "requested": False}
        with self._mutex:
            item = self._active.setdefault(job_id, {"cancel": threading.Event(), "progress": {}})
            item["cancel"].set()
        return {"id": job_id, "status": "RUNNING", "requested": True}

    def cancel_all(self):
        with self._mutex:
            self._closing = True
            for item in self._active.values():
                item["cancel"].set()

    def run(self, job_id, spec):
        """Read one complete SQLite snapshot; publish only a complete result."""
        _id(job_id)
        started = time.monotonic()
        with self._mutex:
            item = self._active.setdefault(job_id, {"cancel": threading.Event(), "progress": {}})
            event = item["cancel"]
            if self._closing:
                event.set()
        deadline = started + spec["timeout"]
        def stop():
            if event.is_set():
                raise _Stopped()
            if time.monotonic() > deadline:
                raise StateError("DATA_PROFILE_DEADLINE_EXCEEDED")
        try:
            with self.database._connection(readonly=True) as db:
                db.execute("PRAGMA temp_store=FILE")
                db.execute("PRAGMA cache_size=-4096")
                db.execute("BEGIN")
                db.set_progress_handler(lambda: int(event.is_set() or time.monotonic() > deadline), 10000)
                try:
                    version = self.validate(db, spec)
                    table = _identifier(version["table"])
                    stop()
                    rows = db.execute(f"SELECT COUNT(*) FROM {table}").fetchone()[0]
                    if rows != version["row_count"]:
                        raise StateError("DATA_PROFILE_RETAINED_ROW_COUNT_CHANGED")
                    selected = [c for c in version["column_types"] if spec["columns"] is None or c["column"] in spec["columns"]]
                    self._progress(job_id, row_count=rows, columns_total=len(selected), columns_complete=0, current_column=None)
                    profiles = []
                    for index, column in enumerate(selected):
                        stop()
                        name, field = column["column"], _identifier(column["column"])
                        self._progress(job_id, current_column=name, columns_complete=index)
                        stats = {"column": name, "source_field": column["source"], "original_json_types": column["json_types"],
                            "rows": rows, "storage_classes": {k: 0 for k in ("null", "integer", "real", "text")},
                            "distinct_nonnull": 0, "null_rows": 0, "empty_text_rows": 0, "whitespace_text_rows": 0,
                            "top_values": [], "numeric_min": None, "numeric_max": None, "text_min": None, "text_max": None,
                            "text_characters_min": None, "text_characters_max": None, "text_utf8_bytes_min": None, "text_utf8_bytes_max": None}
                        observed, total, groups = hashlib.sha256(), 0, 0
                        extrema = {"numeric_min": None, "numeric_max": None, "text_min": None, "text_max": None}
                        sql = f"SELECT typeof({field}) AS kind,{field} AS value,COUNT(*) AS frequency FROM {table} GROUP BY typeof({field}),{field} COLLATE BINARY ORDER BY frequency DESC,kind,{field} COLLATE BINARY"
                        for group in db.execute(sql):
                            stop()
                            kind, value, count = group["kind"], group["value"], group["frequency"]
                            if kind not in stats["storage_classes"]:
                                raise StateError("DATA_PROFILE_NATIVE_SCALAR_REQUIRED")
                            total += count; groups += 1
                            stats["storage_classes"][kind] += count
                            cell = _value(value)
                            observed.update((_json({"value": cell, "rows": count}) + "\n").encode())
                            if len(stats["top_values"]) < spec["top_values"]:
                                stats["top_values"].append({"value": cell, "rows": count})
                            if value is None:
                                stats["null_rows"] = count
                            else:
                                stats["distinct_nonnull"] += 1
                            if kind == "text":
                                stats["empty_text_rows"] += count if not value else 0
                                stats["whitespace_text_rows"] += count if value and value.isspace() else 0
                                for metric, length in (("text_characters", len(value)), ("text_utf8_bytes", len(value.encode()))):
                                    for direction, fn in (("min", min), ("max", max)):
                                        key = metric + "_" + direction
                                        stats[key] = length if stats[key] is None else fn(stats[key], length)
                                category = "text"
                            elif kind in {"integer", "real"}:
                                category = "numeric"
                            else:
                                continue
                            for direction in ("min", "max"):
                                key = category + "_" + direction
                                previous = extrema[key]
                                if previous is None or (value < previous if direction == "min" else value > previous):
                                    extrema[key] = value
                            if groups % 2048 == 0:
                                self._progress(job_id, value_groups=groups, rows_grouped=total, elapsed_seconds=round(time.monotonic() - started, 3))
                        if total != rows:
                            raise StateError("DATA_PROFILE_INCOMPLETE_COLUMN")
                        for key, value in extrema.items():
                            stats[key] = _value(value) if value is not None else None
                        stats["distinct_including_null"] = groups
                        stats["duplicate_nonnull_rows"] = rows - stats["null_rows"] - stats["distinct_nonnull"]
                        stats["top_values_complete"] = len(stats["top_values"]) == groups
                        stats["value_distribution_sha256"] = observed.hexdigest()
                        profiles.append(stats)
                    stop()
                    result = _sealed({"schema": SCHEMA, "id": job_id, "completed_at": _now(), "complete": True,
                        "source": _portable_version(version), "row_count": rows, "columns": profiles,
                        "options": {k: v for k, v in spec.items() if k != "id"},
                        "scope": {"rows": "all imported rows", "columns": "all" if spec["columns"] is None else "selected",
                            "top_values": "frequency-ranked subset; all groups contribute to counts, extrema and distribution digest",
                            "nulls": "native SQL NULL; empty and whitespace-only text counted separately",
                            "types": "native SQLite storage classes; original JSON type declarations preserved; booleans already stored as integers",
                            "distinct": "storage class plus native BINARY value equality; integer and real values kept separate",
                            "numeric": "native numeric values only; decimal-looking text is never converted"}})
                    db.commit()
                except sqlite3.OperationalError:
                    stop()
                    raise
                finally:
                    db.set_progress_handler(None, 0)
            stop()
            raw = _json(result)
            if len(raw.encode()) > _MAX_DOCUMENT:
                raise StateError("DATA_PROFILE_RESULT_TOO_LARGE")
            with self.database._connection() as db:
                db.execute("BEGIN IMMEDIATE")
                stop()
                changed = db.execute("UPDATE sf_analysis_jobs SET status='COMPLETE',result=?,finished_at=? WHERE id=? AND kind='profile' AND status='RUNNING'", (raw, result["completed_at"], job_id)).rowcount
                if changed != 1:
                    raise StateError("DATA_PROFILE_JOB_NOT_RUNNING")
                db.commit()
            return result
        except _Stopped:
            with self.database._connection() as db:
                db.execute("UPDATE sf_analysis_jobs SET status='CANCELLED',finished_at=?,error='DATA_PROFILE_CANCELLED' WHERE id=? AND kind='profile' AND status='RUNNING'", (_now(), job_id))
            return None
        finally:
            with self._mutex:
                self._active.pop(job_id, None)

    @staticmethod
    def _report(db, job_id):
        row = db.execute("SELECT status,result FROM sf_analysis_jobs WHERE id=? AND kind='profile'", (_id(job_id),)).fetchone()
        if row is None or row["status"] != "COMPLETE" or row["result"] is None:
            raise StateError("DATA_PROFILE_COMPLETE_RESULT_REQUIRED")
        result = _verified(parse(row["result"].encode()))
        if result.get("schema") != SCHEMA or result.get("id") != job_id:
            raise StateError("DATA_PROFILE_FORMAT_MISMATCH")
        return result

    @staticmethod
    def _review(db, job_id):
        row = db.execute("SELECT record FROM sf_analysis_profile_reviews WHERE job_id=? ORDER BY revision DESC LIMIT 1", (job_id,)).fetchone()
        return _verified(parse(row[0].encode())) if row else None

    def document(self, job_id):
        with self.database._connection(readonly=True) as db:
            db.execute("BEGIN")
            return ProfileDocument(_sealed({"schema": DOCUMENT, "profile": self._report(db, job_id), "review": self._review(db, job_id)}))

    def history(self, *, before=None, limit=25):
        if type(limit) is not int or not 1 <= limit <= 100 or before is not None and (type(before) is not int or before < 1):
            raise StateError("DATA_PROFILE_HISTORY_PAGE_INVALID")
        with self.database._connection(readonly=True) as db:
            rows = db.execute("SELECT sequence,id,status,created_at,finished_at,error,request FROM sf_analysis_jobs WHERE kind='profile' AND (? IS NULL OR sequence<?) ORDER BY sequence DESC LIMIT ?", (before, before, limit + 1)).fetchall()
        return {"profiles": [{**{k: row[k] for k in row.keys() if k != "request"}, "version_id": parse(row["request"].encode())["version_id"], "progress": self.progress(row["id"])} for row in rows[:limit]],
                "next_before": rows[limit - 1]["sequence"] if len(rows) > limit else None}

    def save_review(self, job_id, request):
        job_id, request_id = _id(job_id), _id(request.get("id"))
        revision, note, decision = request.get("expected_revision"), request.get("note", ""), request.get("decision", "unclassified")
        notes = request.get("column_notes", {})
        if type(revision) is not int or revision < 0 or decision not in {"unclassified", "usable", "investigate", "reference"}:
            raise StateError("DATA_PROFILE_REVIEW_INVALID")
        if not isinstance(note, str) or len(note.encode()) > 16000 or not isinstance(notes, dict) or not all(isinstance(k, str) and isinstance(v, str) and len(v.encode()) <= 4000 for k, v in notes.items()):
            raise StateError("DATA_PROFILE_NOTES_INVALID")
        spec = {"id": request_id, "job_id": job_id, "profile_sha256": _sha(request.get("profile_sha256")),
                "expected_revision": revision, "note": note, "decision": decision, "column_notes": notes}
        sha = digest(_json(spec).encode())
        with self.database._connection() as db:
            db.execute("BEGIN IMMEDIATE")
            old = db.execute("SELECT request_sha256,record FROM sf_analysis_profile_reviews WHERE request_id=?", (request_id,)).fetchone()
            if old:
                if old[0] != sha:
                    raise StateError("DATA_PROFILE_REVIEW_ID_REUSED")
                return _verified(parse(old[1].encode()))
            report = self._report(db, job_id)
            if report["sha256"] != spec["profile_sha256"]:
                raise StateError("DATA_PROFILE_REVIEWED_RESULT_CHANGED")
            if set(notes) - {c["column"] for c in report["columns"]}:
                raise StateError("DATA_PROFILE_NOTE_COLUMN_UNKNOWN")
            current = self._review(db, job_id)
            if (current["revision"] if current else 0) != revision:
                raise StateError("DATA_PROFILE_REVIEW_REVISION_CHANGED")
            record = _sealed({**spec, "revision": revision + 1, "saved_at": _now()})
            db.execute("INSERT INTO sf_analysis_profile_reviews(job_id,revision,request_id,request_sha256,record) VALUES(?,?,?,?,?)", (job_id, revision + 1, request_id, sha, _json(record)))
            db.commit()
            return record

    def frequency_query(self, job_id, column):
        with self.database._connection(readonly=True) as db:
            report = self._report(db, job_id)
        if column not in {c["column"] for c in report["columns"]}:
            raise StateError("DATA_PROFILE_COLUMN_NOT_IN_RESULT")
        field = _identifier(column)
        table = _identifier("sf_dataset_rows_" + report["source"]["version_id"])
        return {"sql": f"SELECT typeof({field}) AS storage_type,{field} AS value,COUNT(*) AS frequency FROM {table} GROUP BY typeof({field}),{field} COLLATE BINARY ORDER BY frequency DESC,storage_type,{field} COLLATE BINARY", "parameters_text": "[]", "max_rows": 1000,
                "profile_id": job_id, "profile_sha256": report["sha256"], "version_id": report["source"]["version_id"],
                "description": "Complete frequency SQL on this original immutable edition; preview limits belong to the original query UI. Use its full-query export for every group."}

    def compare(self, before, after):
        with self.database._connection(readonly=True) as db:
            db.execute("BEGIN")
            return compare_profiles(self._report(db, before), self._report(db, after))


class ProfileDocument:
    """Portable profile/review; reopens without Node, a seller or the source DB."""
    def __init__(self, record):
        self.record = _verified(record)
        if record.get("schema") != DOCUMENT:
            raise StateError("DATA_PROFILE_DOCUMENT_FORMAT_MISMATCH")
        self.profile = _verified(record.get("profile"))
        if self.profile.get("schema") != SCHEMA or self.profile.get("complete") is not True:
            raise StateError("DATA_PROFILE_DOCUMENT_INCOMPLETE")
        self.review = record.get("review")
        if self.review is not None:
            _verified(self.review)
            if self.review.get("profile_sha256") != self.profile["sha256"] or self.review.get("job_id") != self.profile["id"]:
                raise StateError("DATA_PROFILE_REVIEW_BINDING_CHANGED")

    @classmethod
    def open(cls, path):
        return cls(parse(read(Path(path), _MAX_DOCUMENT)))

    def compare(self, other):
        return compare_profiles(self.profile, other.profile)

    def bytes(self, format="json"):
        if format == "json":
            return (_json(self.record) + "\n").encode()
        if format != "html":
            raise StateError("DATA_PROFILE_EXPORT_FORMAT_INVALID")
        return render_document(self).encode()

    def write(self, destination, *, format="json"):
        path = Path(destination)
        body = self.bytes(format)
        if len(body) > _MAX_DOCUMENT:
            raise StateError("DATA_PROFILE_DOCUMENT_TOO_LARGE")
        write(path, body, exclusive=True)
        return {"path": str(path), "bytes": len(body), "sha256": digest(body)}


_STYLE = """body{font:14px/1.5 system-ui,Arial;color:#242424;background:#fff;max-width:1100px;margin:36px auto;padding:0 20px}h1{font-size:28px}h2{margin-top:32px;font-size:20px}.muted{color:#666}table{border-collapse:collapse;width:100%;font-size:13px}th,td{padding:9px;border:1px solid #ccc;text-align:left;vertical-align:top;overflow-wrap:anywhere}th{background:#eee}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f5f5f5;padding:14px}.scroll{overflow:auto}.note{white-space:pre-wrap;border-left:3px solid #555;padding:0 12px}@media print{body{margin:0}tr{break-inside:avoid}.scroll{overflow:visible}}"""


def render_document(document):
    p, review = document.profile, document.review
    esc = lambda value: html.escape(str(value), quote=True)
    cell = lambda value: "—" if value is None else esc(value["type"] + ": " + value["text"] + ("… [preview]" if value.get("truncated") else ""))
    rows = []
    for c in p["columns"]:
        rows.append("<tr>" + "".join("<td>" + esc(v) + "</td>" for v in (c["column"], c["rows"], c["null_rows"], c["empty_text_rows"], c["distinct_nonnull"], c["duplicate_nonnull_rows"], ", ".join(f"{k}: {v}" for k, v in c["storage_classes"].items() if v))) + "</tr>")
    parts = [f'<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Customer data profile</title><style>{_STYLE}</style><body><p class="muted">STELLAR FORGE / CUSTOMER DATA</p><h1>Dataset column profile</h1><p>{p["row_count"]:,} imported rows · {len(p["columns"])} selected columns · {esc(p["completed_at"])}</p><p>Complete column statistics for the retained edition. Top values are frequency-ranked previews, not the full value dictionary.</p>',
        '<div class="scroll"><table><thead><tr><th>Column</th><th>Rows</th><th>Null</th><th>Empty text</th><th>Distinct non-null</th><th>Repeated non-null rows</th><th>Storage classes</th></tr></thead><tbody>' + "".join(rows) + '</tbody></table></div>']
    if review:
        parts += ["<h2>Analyst review</h2><p>" + esc(review["decision"]) + " · revision " + str(review["revision"]) + "</p><div class=\"note\">" + esc(review["note"]) + "</div>"]
    for c in p["columns"]:
        parts += ["<h2>" + esc(c["column"]) + "</h2><p>Original field: " + esc(c["source_field"]) + "; original JSON types: " + esc(", ".join(c["original_json_types"])) + "</p>",
            "<p>Numeric range: " + cell(c["numeric_min"]) + " → " + cell(c["numeric_max"]) + "<br>Text range (BINARY): " + cell(c["text_min"]) + " → " + cell(c["text_max"]) + "</p>",
            '<div class="scroll"><table><thead><tr><th>Value / storage class</th><th>Rows</th></tr></thead><tbody>' + "".join("<tr><td>" + cell(v["value"]) + "</td><td>" + str(v["rows"]) + "</td></tr>" for v in c["top_values"]) + "</tbody></table></div>"]
        if review and c["column"] in review["column_notes"]:
            parts.append('<p class="note">' + esc(review["column_notes"][c["column"]]) + "</p>")
    parts += ["<h2>Original edition and calculation scope</h2><pre>" + esc(json.dumps({"source": p["source"], "scope": p["scope"]}, ensure_ascii=False, indent=2)) + "</pre><p class=\"muted\">Profile " + esc(p["id"]) + " · " + esc(p["sha256"]) + "</p></body></html>"]
    return "".join(parts)

"""Stable application errors; native stderr and signer output are never echoed."""


class BuyerError(RuntimeError):
    def __init__(self, code: str, *, operation=None):
        self.code = code
        self.operation = operation
        super().__init__(code)


class NativeError(BuyerError):
    def __init__(self, code: str, *, returncode=None, operation=None):
        self.returncode = returncode
        super().__init__(code, operation=operation)


class StateError(BuyerError):
    pass


class DeliveryError(BuyerError):
    def __init__(self, code: str, *, operation=None, record=None):
        self.record = record
        native = (record or {}).get("native") or {}
        self.partial_path = native.get("partialPath")
        self.transfer_state_path = native.get("transferState")
        self.retained_bytes = native.get("retainedBytes", 0)
        self.resumable = native.get("resumable", False)
        super().__init__(code, operation=operation)

