_MANIFEST_LIMIT = 16 * 1024 * 1024
_ORDINAL = "_sf_export_row"


def _json(value):
    return json.dumps(value, ensure_ascii=False, allow_nan=False, separators=(",", ":"), sort_keys=True)


def _encode(value):
    if isinstance(value, bytes):
        return {"$sqliteBlob": base64.b64encode(value).decode("ascii")}
    if type(value) is float and not math.isfinite(value):
        return {"$sqliteFloat": "Infinity" if value > 0 else "-Infinity" if value < 0 else "NaN"}
    if value is None or type(value) in (str, int, float, bool):
        return value
    raise StateError("QUERY_EXPORT_VALUE_INVALID")


def _decode(value):
    if isinstance(value, dict):
        if set(value) == {"$sqliteBlob"} and isinstance(value["$sqliteBlob"], str):
            try:
                return base64.b64decode(value["$sqliteBlob"], validate=True)
            except ValueError:
                pass
        if set(value) == {"$sqliteFloat"} and value["$sqliteFloat"] in ("Infinity", "-Infinity", "NaN"):
            return float(value["$sqliteFloat"])
        raise StateError("QUERY_EXPORT_TYPED_VALUE_INVALID")
    return _encode(value)


def _bindings(parameters, *, decode=False):
    convert = _decode if decode else _encode
    if isinstance(parameters, dict) and all(isinstance(key, str) for key in parameters):
        return {key: convert(value) for key, value in parameters.items()}
    if isinstance(parameters, (list, tuple)):
        return [convert(value) for value in parameters]
    raise StateError("QUERY_EXPORT_PARAMETERS_INVALID")


def _path(value):
    return Path(os.path.abspath(Path(value).expanduser()))


def _new_directory(destination):
    target = _path(destination)
    if private_directory(target.parent, create=False) != target.parent:
        raise StateError("QUERY_EXPORT_CANONICAL_PARENT_REQUIRED")
    try:
        target.mkdir(mode=0o700)
    except FileExistsError:
        raise StateError("QUERY_EXPORT_DESTINATION_EXISTS_USE_OPEN") from None
    sync_directory(target.parent)
    return target


def _cleanup(directory):
    # A completed record, including a lost final reply, is retained for reopen.
    if (directory / "manifest.json").exists():
        return
    for name in (*_FILES.values(), *("." + name + ".part" for name in _FILES.values()),
                 ".rows.sqlite3.part-journal"):
        try:
            (directory / name).unlink(missing_ok=True)
        except OSError:
            pass
    try:
        directory.rmdir()
        sync_directory(directory.parent)
    except OSError:
        pass  # Preserve any other files; never recursively remove this directory.


@contextmanager
def _private_file(path):
    try:
        fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW)
        with os.fdopen(fd, "rb") as stream:
            info = os.fstat(stream.fileno())
            if (not stat.S_ISREG(info.st_mode) or info.st_nlink != 1
                    or info.st_mode & 0o077 or info.st_uid != os.getuid()):
                raise StateError("QUERY_EXPORT_PRIVATE_FILE_REQUIRED")
            yield stream
    except OSError as exc:
        raise StateError("QUERY_EXPORT_FILE_UNAVAILABLE") from exc


def _file_record(path):
    checksum, total = hashlib.sha256(), 0
    with _private_file(path) as source:
        while chunk := source.read(1024 * 1024):
            checksum.update(chunk)
            total += len(chunk)
    return {"bytes": total, "sha256": checksum.hexdigest()}


def _columns(columns, *, sqlite=False):
    if (not columns or any(not isinstance(name, str) or not name
            or len(name.encode("utf-8")) > 512 or any(ord(c) < 32 for c in name) for name in columns)
            or len(set(columns)) != len(columns)):
        raise StateError("QUERY_EXPORT_COLUMN_NAMES_REQUIRE_UNIQUE_ALIASES")
    if sqlite and (len({name.lower() for name in columns}) != len(columns)
                   or _ORDINAL in {name.lower() for name in columns} or len(columns) > 1999):
        raise StateError("QUERY_EXPORT_SQLITE_COLUMNS_REQUIRE_ALIASES")


def _quoted(name):
    return '"' + name.replace('"', '""') + '"'


def _csv_value(value, safe):
    if isinstance(value, bytes):
        return "base64:" + base64.b64encode(value).decode("ascii")
    if isinstance(value, str) and safe and (value.startswith(("\t", "\r", "\n"))
            or value.lstrip(" \t\r\n").startswith(("=", "+", "-", "@"))):
        return "'" + value
    return value


def export_query(database, sql, parameters=(), *, destination, formats=("jsonl", "csv", "sqlite"),
                 expected_views=None, timeout=300, cancel=None, max_rows=None,
                 max_output_bytes=None, spreadsheet_safe=True, progress=None):
    """Export every result row once; errors never publish a complete manifest.

    The query is read-only and uses the existing DatasetDatabase reader. A
    caller may set whole-output limits; reaching one raises instead of silently
    truncating the result. Limits apply to the complete selected output set.
    """
    if (not isinstance(formats, (list, tuple)) or not formats
            or any(not isinstance(value, str) or value not in _FILES for value in formats) or len(set(formats)) != len(formats)
            or any(value is not None and (type(value) is not int or value < 1)
                   for value in (max_rows, max_output_bytes))
            or type(spreadsheet_safe) is not bool or progress is not None and not callable(progress)):
        raise StateError("QUERY_EXPORT_OPTIONS_INVALID")
    formats = tuple(formats)
    parameters = _bindings(_bindings(parameters), decode=True)  # Copy and validate before entering SQL.
    encoded_parameters = _bindings(parameters)
    target = _new_directory(destination)
    started = time.monotonic()
    output_db = None
    try:
        with ExitStack() as stack, database.stream_query(sql, parameters, timeout=timeout,
                expected_views=expected_views, cancel=cancel) as rows:
            _columns(rows.columns, sqlite="sqlite" in formats)
            handles = {}
            hashes = {}
            lengths = {}
            sqlite_bytes = 0
            for kind in formats:
                name = _FILES[kind]
                fd = os.open(target / ("." + name + ".part"), os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o600)
                if kind == "sqlite":
                    os.close(fd)
                    output_db = sqlite3.connect((target / ("." + name + ".part")).as_uri() + "?mode=rw", uri=True)
                    output_db.execute("PRAGMA synchronous=FULL")
                    output_db.execute("PRAGMA cache_size=-2048")
                    output_db.execute("PRAGMA application_id=1397117272")
                    output_db.execute("PRAGMA user_version=1")
                    output_db.execute("BEGIN IMMEDIATE")
                    output_db.execute(f"CREATE TABLE result({_quoted(_ORDINAL)} INTEGER PRIMARY KEY,"
                                      + ",".join(_quoted(column) for column in rows.columns) + ")")
                    insert = "INSERT INTO result VALUES(" + ",".join("?" for _ in range(len(rows.columns) + 1)) + ")"
                else:
                    handles[kind] = stack.enter_context(os.fdopen(fd, "wb"))
                    hashes[kind] = hashlib.sha256()
                    lengths[kind] = 0
            csv_buffer = io.StringIO(newline="")
            csv_writer = csv.writer(csv_buffer, lineterminator="\n")

            def check_size():
                if max_output_bytes is not None and sum(lengths.values()) + sqlite_bytes > max_output_bytes:
                    raise StateError("QUERY_EXPORT_OUTPUT_LIMIT_EXCEEDED")

            def write(kind, raw):
                lengths[kind] += len(raw)
                check_size()
                handles[kind].write(raw)
                hashes[kind].update(raw)

            def write_csv(values):
                csv_buffer.seek(0)
                csv_buffer.truncate()
                csv_writer.writerow(values)
                write("csv", csv_buffer.getvalue().encode("utf-8"))

            if "csv" in formats:
                write_csv([_csv_value(column, spreadsheet_safe) for column in rows.columns])
            count = 0
            for values in rows:
                if max_rows is not None and count == max_rows:
                    raise StateError("QUERY_EXPORT_ROW_LIMIT_EXCEEDED")
                if "jsonl" in formats:
                    write("jsonl", (_json(dict(zip(rows.columns, map(_encode, values)))) + "\n").encode("utf-8"))
                if "csv" in formats:
                    write_csv([_csv_value(value, spreadsheet_safe) for value in values])
                if output_db is not None:
                    output_db.execute(insert, (count + 1, *values))
                count += 1
                if count % 4096 == 0:
                    if output_db is not None:
                        sqlite_bytes = output_db.execute("PRAGMA page_count").fetchone()[0] * output_db.execute("PRAGMA page_size").fetchone()[0]
                    check_size()
                    if progress:
                        progress({"rows": count, "outputBytes": sum(lengths.values()) + sqlite_bytes, "complete": False})
            binding = {"database": str(database.path), "sql": sql, "parameters": encoded_parameters,
                       "views": rows.views, "readTables": list(rows.read_tables), "sourceVersions": rows.source_versions()}
            if isinstance(expected_views, dict):
                binding["viewSelection"] = expected_views
            binding_sha = digest(_json(binding).encode("utf-8"))
            if output_db is not None:
                output_db.execute("CREATE TABLE export_metadata(record TEXT NOT NULL)")
                output_db.execute("INSERT INTO export_metadata VALUES(?)", (_json({"schema": _SCHEMA,
                    "bindingSha256": binding_sha, "columns": list(rows.columns), "rowCount": count,
                    "orderColumn": _ORDINAL}),))
                output_db.commit()
                output_db.close()
                output_db = None
            for handle in handles.values():
                handle.flush()
                os.fsync(handle.fileno())
            manifest = {"schema": _SCHEMA, "queryComplete": rows.complete,
                        "rowCount": count, "columns": list(rows.columns), "binding": binding,
                        "bindingSha256": binding_sha, "createdAt": datetime.now(timezone.utc).isoformat(),
                        "elapsedMs": round((time.monotonic() - started) * 1000),
                        "largestRowBytes": rows.largest_row_bytes,
                        "jsonlEncoding": "sqlite-scalars-v1", "sqliteOrderColumn": _ORDINAL,
                        "csv": {"spreadsheetSafe": spreadsheet_safe, "null": "empty field", "blob": "base64: prefix"},
                        "outputs": {}}
            rows.check()
        # The original snapshot is released before file hashing/publication.
        for kind in formats:
            name = _FILES[kind]
            temporary = target / ("." + name + ".part")
            if kind == "sqlite":
                with _private_file(temporary) as source:
                    os.fsync(source.fileno())
                record = _file_record(temporary)
            else:
                record = {"bytes": lengths[kind], "sha256": hashes[kind].hexdigest()}
            manifest["outputs"][name] = record
        total = sum(record["bytes"] for record in manifest["outputs"].values())
        if max_output_bytes is not None and total > max_output_bytes:
            raise StateError("QUERY_EXPORT_OUTPUT_LIMIT_EXCEEDED")
        if cancel is not None and cancel():
            raise StateError("DATASET_SQL_QUERY_CANCELLED")
        for name in manifest["outputs"]:
            os.rename(target / ("." + name + ".part"), target / name)
        sync_directory(target)
        manifest_raw = (_json(manifest) + "\n").encode("utf-8")
        if len(manifest_raw) > _MANIFEST_LIMIT:
            raise StateError("QUERY_EXPORT_MANIFEST_TOO_LARGE")
        atomic_write(target / "manifest.json", manifest_raw, exclusive=True)
        result = QueryExport(target)
        if progress:
            progress({"rows": count, "outputBytes": total, "complete": True})
        return result
    except BaseException:
        if output_db is not None:
            output_db.close()
        _cleanup(target)
        raise


class QueryExport:
    """Reopen/copy a completed result without its source database or runtime."""

    def __init__(self, directory):
        self.directory = _path(directory)
        if private_directory(self.directory, create=False) != self.directory:
            raise StateError("QUERY_EXPORT_CANONICAL_DIRECTORY_REQUIRED")
        try:
            with _private_file(self.directory / "manifest.json") as source:
                raw = source.read(_MANIFEST_LIMIT + 1)
        except StateError as exc:
            raise StateError("QUERY_EXPORT_MANIFEST_UNAVAILABLE_OR_INCOMPLETE") from exc
        if len(raw) > _MANIFEST_LIMIT:
            raise StateError("QUERY_EXPORT_MANIFEST_TOO_LARGE")
        value = parse(raw)
        if (not isinstance(value, dict) or value.get("schema") != _SCHEMA or value.get("queryComplete") is not True
                or type(value.get("rowCount")) is not int or value["rowCount"] < 0
                or not isinstance(value.get("columns"), list) or not isinstance(value.get("binding"), dict)
                or value.get("bindingSha256") != digest(_json(value["binding"]).encode("utf-8"))
                or not isinstance(value.get("outputs"), dict) or not value["outputs"]
                or set(value["outputs"]) - set(_FILES.values())):
            raise StateError("QUERY_EXPORT_MANIFEST_INVALID")
        _columns(value["columns"], sqlite="rows.sqlite3" in value["outputs"])
        for record in value["outputs"].values():
            if (not isinstance(record, dict) or type(record.get("bytes")) is not int or record["bytes"] < 0
                    or not isinstance(record.get("sha256"), str) or not _HEX.fullmatch(record["sha256"])):
                raise StateError("QUERY_EXPORT_OUTPUT_METADATA_INVALID")
        self._manifest = value
        self._raw = raw

    @property
    def manifest(self):
        return deepcopy(self._manifest)

    @contextmanager
    def open(self, name):
        record = self._manifest["outputs"].get(name)
        if record is None:
            raise StateError("QUERY_EXPORT_OUTPUT_NOT_SELECTED")
        if private_directory(self.directory, create=False) != self.directory:
            raise StateError("QUERY_EXPORT_DIRECTORY_CHANGED")
        with _private_file(self.directory / name) as source:
            if os.fstat(source.fileno()).st_size != record["bytes"]:
                raise StateError("QUERY_EXPORT_FILE_CHANGED")
            checksum, total = hashlib.sha256(), 0
            while chunk := source.read(1024 * 1024):
                total += len(chunk)
                if total > record["bytes"]:
                    raise StateError("QUERY_EXPORT_FILE_CHANGED")
                checksum.update(chunk)
            if total != record["bytes"] or checksum.hexdigest() != record["sha256"]:
                raise StateError("QUERY_EXPORT_FILE_CHANGED")
            source.seek(0)
            yield source

    def inspect(self):
        for name in self._manifest["outputs"]:
            with self.open(name):
                pass
        return self.manifest

    def rows(self):
        columns = self._manifest["columns"]
        count = 0
        with self.open("rows.jsonl") as source:
            while raw := source.readline(_ROW_LIMIT + 1):
                if len(raw) > _ROW_LIMIT or not raw.endswith(b"\n"):
                    raise StateError("QUERY_EXPORT_ROW_FORMAT_INVALID")
                row = parse(raw)
                if not isinstance(row, dict) or set(row) != set(columns):
                    raise StateError("QUERY_EXPORT_ROW_COLUMNS_INVALID")
                count += 1
                if count > self._manifest["rowCount"]:
                    raise StateError("QUERY_EXPORT_ROW_COUNT_CHANGED")
                yield {name: _decode(row[name]) for name in columns}
        if count != self._manifest["rowCount"]:
            raise StateError("QUERY_EXPORT_ROW_COUNT_CHANGED")

    def copy_to(self, destination):
        """Create a verified portable private copy; the original SQL is not run."""
        target = _new_directory(destination)
        try:
            for name in self._manifest["outputs"]:
                with self.open(name) as source:
                    fd = os.open(target / name, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
                    with os.fdopen(fd, "wb") as output:
                        checksum, total = hashlib.sha256(), 0
                        while chunk := source.read(1024 * 1024):
                            total += len(chunk)
                            checksum.update(chunk)
                            output.write(chunk)
                        record = self._manifest["outputs"][name]
                        if total != record["bytes"] or checksum.hexdigest() != record["sha256"]:
                            raise StateError("QUERY_EXPORT_FILE_CHANGED")
                        output.flush()
                        os.fsync(output.fileno())
            # Publish the exact manifest bytes so transfer retains its identity.
            atomic_write(target / "manifest.json", self._raw, exclusive=True)
            return QueryExport(target)
        except BaseException:
            _cleanup(target)
            raise


def prepare_query(database, sql, parameters=(), *, destination, preview_rows=20, timeout=10):
    """Retain query text, bindings, reviewed views and a native preview."""
    bindings = _bindings(parameters)
    preview = database.query(sql, _bindings(bindings, decode=True), max_rows=preview_rows,
                             max_result_bytes=1024 * 1024, timeout=timeout)
    request = {"schema": _REQUEST, "database": str(database.directory), "sql": sql,
               "parameters": bindings, "expectedViews": list(preview.views),
               "preview": {"columns": list(preview.columns), "rows": [[_encode(v) for v in row] for row in preview.rows],
                           "truncated": preview.truncated}}
    path = _path(destination)
    if private_directory(path.parent, create=False) != path.parent:
        raise StateError("QUERY_EXPORT_CANONICAL_PARENT_REQUIRED")
    dump(path, request, exclusive=True)
    return request


def main(argv=None):
    parser = argparse.ArgumentParser(description="Review, export and reopen complete local customer SQL results.")
    commands = parser.add_subparsers(dest="command", required=True)
    prepare = commands.add_parser("prepare", help="Save SQL, typed bindings, native preview and exact selected views")
    prepare.add_argument("--database", required=True)
    prepare.add_argument("--sql-file", required=True)
    prepare.add_argument("--parameters-file")
    prepare.add_argument("--out", required=True)
    run = commands.add_parser("run", help="Export a saved reviewed query into a new private directory")
    run.add_argument("--request", required=True)
    run.add_argument("--out", required=True)
    run.add_argument("--formats", default="jsonl,csv,sqlite")
    run.add_argument("--timeout", type=float, default=300)
    run.add_argument("--max-rows", type=int)
    run.add_argument("--max-output-bytes", type=int)
    run.add_argument("--literal-csv", action="store_true")
    inspect = commands.add_parser("inspect", help="Verify and inspect an existing export, independently of its source")
    inspect.add_argument("--directory", required=True)
    copy = commands.add_parser("copy", help="Copy a verified export without querying or purchasing again")
    copy.add_argument("--directory", required=True)
    copy.add_argument("--out", required=True)
    args = parser.parse_args(argv)
    try:
        if args.command == "prepare":
            from .sqlite_dataset import DatasetDatabase
            database = DatasetDatabase(args.database, create=False)
            sql = read(_path(args.sql_file), 1024 * 1024).decode("utf-8")
            parameters = parse(read(_path(args.parameters_file), 1024 * 1024)) if args.parameters_file else []
            result = prepare_query(database, sql, _bindings(parameters, decode=True), destination=args.out)
        elif args.command == "run":
            from .sqlite_dataset import DatasetDatabase
            with _private_file(_path(args.request)) as source:
                raw = source.read(_MANIFEST_LIMIT + 1)
            if len(raw) > _MANIFEST_LIMIT:
                raise StateError("QUERY_EXPORT_REQUEST_TOO_LARGE")
            request = parse(raw)
            if (not isinstance(request, dict) or request.get("schema") != _REQUEST
                    or not isinstance(request.get("expectedViews"), list)):
                raise StateError("QUERY_EXPORT_REQUEST_INVALID")
            database = DatasetDatabase(request["database"], create=False)
            result = export_query(database, request["sql"], _bindings(request["parameters"], decode=True),
                destination=args.out, expected_views=request["expectedViews"], formats=args.formats.split(","),
                timeout=args.timeout, max_rows=args.max_rows, max_output_bytes=args.max_output_bytes,
                spreadsheet_safe=not args.literal_csv).manifest
        elif args.command == "copy":
            result = QueryExport(args.directory).copy_to(args.out).inspect()
        else:
            result = QueryExport(args.directory).inspect()
        print(_json(result))
        return 0
    except BuyerError as exc:
        print(_json({"error": exc.code}), file=sys.stderr)
        return 2
    except KeyboardInterrupt:
        print(_json({"error": "QUERY_EXPORT_INTERRUPTED"}), file=sys.stderr)
        return 130
    except (OSError, sqlite3.Error, ValueError, KeyError, TypeError) as exc:
        print(_json({"error": "QUERY_EXPORT_FAILED", "kind": type(exc).__name__}), file=sys.stderr)
        return 2


if __name__ == "__main__":
    raise SystemExit(main())

"""The DatasetDatabase SQL reader, shared by previews and complete exports."""
from __future__ import annotations

from contextlib import contextmanager
from copy import deepcopy
import math
import re
import sqlite3
import time

from .errors import StateError

# These are the original DatasetDatabase authorizer and value-size policy.
_READ_ACTIONS = frozenset((sqlite3.SQLITE_SELECT, sqlite3.SQLITE_READ,
                          sqlite3.SQLITE_FUNCTION, sqlite3.SQLITE_RECURSIVE))
_FILE_FUNCTIONS = frozenset(("load_extension", "writefile", "readfile"))
_VALUE_LIMIT = 16 * 1024 * 1024


def reviewed_view_selection(value):
    """Retain either the complete catalogue or an explicit immutable selection."""
    if isinstance(value, list):
        return deepcopy(value)
    if (not isinstance(value, dict) or set(value) != {"scope", "bindings"}
            or value.get("scope") != "selected"
            or not isinstance(value.get("bindings"), list)
            or not 1 <= len(value["bindings"]) <= 4096):
        raise StateError("DATASET_SQL_REVIEWED_VIEWS_INVALID")
    names = set()
    for binding in value["bindings"]:
        if (not isinstance(binding, dict)
                or set(binding) != {"name", "version_id", "revision"}
                or not isinstance(binding["name"], str)
                or not re.fullmatch(r"[a-zA-Z][a-zA-Z0-9_]{0,63}", binding["name"])
                or not isinstance(binding["version_id"], str)
                or not re.fullmatch(r"[a-f0-9]{64}", binding["version_id"])
                or type(binding["revision"]) is not int or binding["revision"] < 1
                or binding["name"].lower() in names):
            raise StateError("DATASET_SQL_REVIEWED_VIEWS_INVALID")
        names.add(binding["name"].lower())
    return deepcopy(value)


def resolve_view_selection(database, connection, expected_views):
    """Check the exact source bindings inside the query's own transaction.

    Selected mode allows unrelated views to be added while restricting SQL
    reads to the selected views and their immutable original physical tables.
    The ordinary list form continues to pin the entire catalogue.
    """
    observed = database._views(connection)
    if expected_views is None:
        return observed, None
    selected = reviewed_view_selection(expected_views)
    if isinstance(selected, list):
        if observed != selected:
            raise StateError("DATASET_SQL_VIEWS_CHANGED")
        return observed, None
    current = {item["name"].lower(): item for item in observed}
    bindings = selected["bindings"]
    if any(current.get(item["name"].lower()) != item for item in bindings):
        raise StateError("DATASET_SQL_VIEWS_CHANGED")
    allowed = {item["name"].lower() for item in bindings}
    allowed.update("sf_dataset_rows_" + item["version_id"] for item in bindings)
    return bindings, frozenset(allowed)


def row_bytes(values):
    return sum(len(value.encode("utf-8")) if isinstance(value, str)
               else len(value) if isinstance(value, bytes) else 8 for value in values)


class QueryStream:
    """A single-use iterator valid inside DatasetDatabase.stream_query().

    Rows are fetched individually from the original SQLite cursor. Exhaustion
    sets complete=True; an early break, cancellation or timeout never does.
    """

    def __init__(self, database, connection, *, views, timeout, cancel, allowed_reads=None):
        self._database = database
        self._connection = connection
        self._views = deepcopy(views)
        self._allowed_reads = allowed_reads
        self._deadline = time.monotonic() + timeout
        self._cancel = cancel
        self._reason = None
        self._tables = set()
        self._track_reads = True
        self._cursor = None
        self.columns = ()
        self.rows_read = 0
        self.bytes_read = 0
        self.largest_row_bytes = 0
        self.complete = False
        self.closed = False

    @property
    def views(self):
        return deepcopy(self._views)

    @property
    def read_tables(self):
        return tuple(sorted(self._tables))

    def _interrupted(self):
        if self._reason:
            return True
        try:
            if self._cancel is not None and self._cancel():
                self._reason = "DATASET_SQL_QUERY_CANCELLED"
            elif time.monotonic() >= self._deadline:
                self._reason = "DATASET_SQL_QUERY_TIMEOUT"
        except Exception:
            self._reason = "DATASET_SQL_CANCEL_CALLBACK_FAILED"
        return self._reason is not None

    def check(self):
        if self.closed:
            raise StateError("DATASET_SQL_STREAM_CLOSED")
        if self._interrupted():
            raise StateError(self._reason)

    def _authorize(self, action, first, second, database, trigger):
        if (action not in _READ_ACTIONS or action == sqlite3.SQLITE_FUNCTION
                and (second or first or "").lower() in _FILE_FUNCTIONS):
            return sqlite3.SQLITE_DENY
        if self._track_reads and action == sqlite3.SQLITE_READ and first:
            if self._allowed_reads is not None and first.lower() not in self._allowed_reads:
                self._reason = "DATASET_SQL_SOURCE_OUTSIDE_SELECTION"
                return sqlite3.SQLITE_DENY
            self._tables.add(first)
        return sqlite3.SQLITE_OK

    def __iter__(self):
        return self

    def __next__(self):
        if self.complete:
            raise StopIteration
        self.check()
        try:
            row = self._cursor.fetchone()
        except sqlite3.Error as exc:
            raise StateError(self._reason or "DATASET_SQL_QUERY_FAILED") from exc
        self.check()
        if row is None:
            self.complete = True
            raise StopIteration
        values = tuple(row)
        size = row_bytes(values)
        self.rows_read += 1
        self.bytes_read += size
        self.largest_row_bytes = max(self.largest_row_bytes, size)
        return values

    def dictionaries(self):
        if len(set(self.columns)) != len(self.columns):
            raise StateError("DATASET_SQL_DUPLICATE_RESULT_NAMES_USE_ALIASES")
        for row in self:
            yield dict(zip(self.columns, row))

    def source_versions(self):
        """Original imported records for physical tables actually read.

        Called inside the same read transaction. Metadata inspection does not
        add its own tables to query lineage. Other SQL tables remain visible
        in read_tables, without an invented acquisition record.
        """
        self.check()
        prefix = "sf_dataset_rows_"
        versions = sorted({name[len(prefix):] for name in self._tables
                           if name.startswith(prefix) and len(name) == len(prefix) + 64
                           and all(c in "0123456789abcdef" for c in name[len(prefix):])})
        self._track_reads = False
        try:
            return [self._database._version(self._connection, version) for version in versions]
        finally:
            self._track_reads = True


@contextmanager
def open_query(database, connection, sql, parameters=(), *, timeout=300,
               expected_views=None, cancel=None):
    """Authorize a cursor in an existing original database transaction."""
    if not connection.in_transaction:
        raise StateError("DATASET_SQL_TRANSACTION_REQUIRED")
    if (not isinstance(sql, str) or type(timeout) not in (int, float)
            or not math.isfinite(timeout) or not 0 < timeout <= 86400
            or cancel is not None and not callable(cancel)):
        raise StateError("DATASET_SQL_QUERY_OPTIONS_INVALID")
    views, allowed_reads = resolve_view_selection(database, connection, expected_views)
    stream = QueryStream(database, connection, views=views, timeout=timeout,
                         cancel=cancel, allowed_reads=allowed_reads)
    previous_length = connection.setlimit(sqlite3.SQLITE_LIMIT_LENGTH, _VALUE_LIMIT)
    connection.set_authorizer(stream._authorize)
    connection.set_progress_handler(lambda: int(stream._interrupted()), 1000)
    try:
        stream.check()
        try:
            stream._cursor = connection.execute(sql, parameters)
        except sqlite3.Error as exc:
            raise StateError(stream._reason or "DATASET_SQL_QUERY_FAILED") from exc
        stream.columns = tuple(column[0] for column in stream._cursor.description or ())
        if not stream.columns:
            raise StateError("DATASET_SQL_READ_QUERY_REQUIRED")
        yield stream
    finally:
        stream.closed = True
        try:
            if stream._cursor is not None:
                stream._cursor.close()
        finally:
            connection.set_authorizer(None)
            connection.set_progress_handler(None, 0)
            connection.setlimit(sqlite3.SQLITE_LIMIT_LENGTH, previous_length)

"""Paid Research delivery through the original merchant and Buyer workspace.

The native SF101 checkout owns the order and payment terms. The original Buyer
Runbook owns approval, execution, cancellation and retrieval. This Python client
retains full request/reply bytes and receives the same editable dossier, work
snapshot, reports and optional source workspace.
"""
from __future__ import annotations

import base64
from copy import deepcopy
from pathlib import Path
import re
import tempfile
from typing import Any, Iterator, TYPE_CHECKING

from .errors import StateError
from .research_workspace import _file_delivery, _json, _request_id
from .research_customer_updates import ResearchCustomerDelivery
from .storage import digest, parse, read

if TYPE_CHECKING:
    from .research_workspace import ResearchWorkspace
    from .research_commerce_types import (
        CommercePublicationRequest, CommercePublicationEnrollment,
        CommercePurchasePreparation, CommercePurchaseAction,
        CommercePurchaseCancellation, CommercePurchaseReconciliation,
        CommercePurchaseReceiving, CommerceOperationResult,
    )

COLLECTIONS = ("publications", "purchases")
FILE_PARTS = ("publication", "handoff", "archive", "received")
BUYER_ACTIONS = ("execute", "retrieve", "recover", "finalize", "cancel")
NATIVE_WRITES = (
    "commerce-publication-prepare", "commerce-publication-enroll",
    "commerce-purchase-receive", "commerce-purchase-prepare",
    "commerce-execute", "commerce-retrieve", "commerce-recover",
    "commerce-finalize", "commerce-cancel", "commerce-reconcile",
    "commerce-receive-dossier",
)
_WRITES = {*NATIVE_WRITES, "commerce-export", "commerce-replay", "commerce-archive-receive"}
_LOCAL = {"commerce-operation", "commerce-archive-inspect", "commerce-archive-receive"}
_RESPONSE = "sf88-research-commerce-python-response/v1"
_RESPONSE_FILE = "sf88-research-commerce-python-file/v1"
_OPERATOR = "sf88-research-commerce-operator-result/v1"
_EXPORT = "sf88-research-commerce-export-result/v1"
_ARCHIVE = "sf88-research-paid-archive-received/v1"
_CONTROL_LIMIT = 2 * 1024 * 1024
_PUBLICATION_LIMIT = 1024 * 1024
_ARCHIVE_LIMIT = 32 * 1024 * 1024
_RESPONSE_LIMIT = 66 * 1024 * 1024 + 65536
_HASH = re.compile(r"[a-f0-9]{64}")


def _need(value, code):
    if not value:
        raise StateError(code)


def _snapshot(value):
    return parse(_json(value))


def _hash(value):
    _need(isinstance(value, str) and _HASH.fullmatch(value),
          "RESEARCH_COMMERCE_SHA256_REQUIRED")
    return value


def _absolute(value):
    return str(Path(value).expanduser().absolute())


def _call_id(action, value, selected):
    if selected is not None:
        return _request_id(selected)
    native_id = value.get("requestId") or value.get("id")
    _need(isinstance(native_id, str), "RESEARCH_COMMERCE_CALL_ID_REQUIRED")
    return _request_id(action + ":" + native_id)


def _retained_file(value):
    _need(isinstance(value, dict) and isinstance(value.get("path"), str),
          "RESEARCH_COMMERCE_FILE_REQUIRED")
    return _file_delivery({**value, "file": value["path"]})


class ResearchCommerceArchive:
    """A complete locally received original Research handover.

    Construction reopens the compressed archive and every native member, using
    the original FileDelivery reader and ResearchCustomerDelivery contracts.
    No running Research server or original download location is needed.
    """
    def __init__(self, received):
        self._record = _snapshot(received)
        _need(isinstance(self._record, dict) and self._record.get("schema") == _ARCHIVE,
              "RESEARCH_COMMERCE_RECEIVED_ARCHIVE_REQUIRED")
        directory = self._record.get("directory")
        _need(isinstance(directory, str) and Path(directory).is_absolute(),
              "RESEARCH_COMMERCE_RECEIVED_ARCHIVE_REQUIRED")
        self.directory = Path(directory)
        selected = self._record.get("archive")
        _need(isinstance(selected, dict) and
              selected.get("name") == "research-customer.handover.gz" and
              selected.get("contentType") == "application/gzip" and
              type(selected.get("bytes")) is int and 0 < selected["bytes"] <= _ARCHIVE_LIMIT and
              selected.get("path") == str(self.directory / selected["name"]),
              "RESEARCH_COMMERCE_RECEIVED_ARCHIVE_CHANGED")
        _hash(self._record.get("manifestSha256"))
        self._archive = _retained_file(selected)
        self._handover = ResearchCustomerDelivery(self._record.get("handover"))
        _need(self._handover.manifest_sha256 == self._record["manifestSha256"] and
              self._handover.directory == self.directory / "handover",
              "RESEARCH_COMMERCE_RECEIVED_HANDOVER_CHANGED")
        with self._archive.open():
            pass

    @property
    def record(self):
        return deepcopy(self._record)

    @property
    def archive(self):
        return self._archive

    @property
    def handover(self):
        return self._handover

    def verify(self):
        with self._archive.open():
            pass
        return {"archive": deepcopy(self._record["archive"]),
                "handover": self._handover.verify(), "directory": str(self.directory)}


class ResearchCommerce:
    """Original paid-delivery operations on one retained ResearchWorkspace.

    Each write has a Python call ID and its original native request ID. The
    former identifies the local attempt; the latter remains unchanged through
    native receiving, retry and explicit replay.
    """
    def __init__(self, workspace: ResearchWorkspace):
        self.workspace = workspace

    def _decode(self, descriptor, action, selected, expected_workspace):
        _need(isinstance(descriptor, dict) and descriptor.get("schema") == _RESPONSE_FILE,
              "RESEARCH_COMMERCE_PYTHON_RESPONSE_INVALID")
        _hash(descriptor.get("callSha256"))
        value = _snapshot(selected)
        directory = Path(value.pop("responseDirectory"))
        file = descriptor.get("file")
        _need(isinstance(file, dict) and file.get("file") == str(directory / "response.json"),
              "RESEARCH_COMMERCE_PYTHON_RESPONSE_FILE_CHANGED")
        body = _file_delivery(file).json(limit=_RESPONSE_LIMIT)
        call = {"action": action, "input": value, "expectedWorkspaceId": expected_workspace}
        _need(isinstance(body, dict) and body.get("schema") == _RESPONSE and
              body.get("call") == call and body.get("callSha256") == descriptor["callSha256"] and
              body.get("workspaceId") == descriptor.get("workspaceId") and "result" in body,
              "RESEARCH_COMMERCE_PYTHON_RESPONSE_CHANGED")
        identity = body.get("workspaceId")
        if action in _LOCAL:
            _need(identity is None, "RESEARCH_LOCAL_WORKSPACE_CHANGED")
        else:
            _need(identity is not None and
                  (expected_workspace is None or identity == expected_workspace),
                  "RESEARCH_WORKSPACE_CHANGED")
            self.workspace._bind(identity)
        result = deepcopy(body["result"])
        if isinstance(result, dict):
            for key in ("pythonRuntime", "sourceCleanupFailed"):
                if descriptor.get(key) is not None:
                    result[key] = deepcopy(descriptor[key])
        return result

    def _read(self, action, value=None, *, cancel_event=None, _owned_event=None):
        value = _snapshot(value or {})
        local = action in _LOCAL
        with self.workspace._operation(cancel_event, owned_event=_owned_event) as event:
            with tempfile.TemporaryDirectory(prefix=".commerce-read-", dir=self.workspace.directory) as temporary:
                selected = {**value, "responseDirectory": str(Path(temporary).resolve())}
                expected = None if local else self.workspace.workspace_id
                descriptor = self.workspace._read(action, selected, _owned_event=event, local=local)
                return self._decode(descriptor, action, selected, expected)

    def _write(self, action, value, *, call_id, resume=False, cancel_event=None,
               _owned_event=None):
        _need(action in _WRITES, "RESEARCH_COMMERCE_ACTION_INVALID")
        value = _snapshot(value)
        _need(len(_json(value)) <= _CONTROL_LIMIT + 65536,
              "RESEARCH_COMMERCE_PYTHON_INPUT_TOO_LARGE")
        local = action in _LOCAL
        with self.workspace._operation(cancel_event, owned_event=_owned_event) as event:
            if self.workspace.workspace_id is None and not local:
                self.workspace._read("status", _owned_event=event)
            directory = self.workspace._directory_for_call(_request_id(call_id), create=True)
            selected = {**value,
                        "directory": value.get("directory", str(directory / "commerce-operation")),
                        "responseDirectory": str(directory / "commerce-response")}
            expected = None if local else self.workspace.workspace_id
            descriptor = self.workspace._write_call(action, selected, request_id=call_id,
                replay_safe=True, resume=resume, event=event, local=local)
            result = self._decode(descriptor, action, selected, expected)
            return self._verify_completed(action, result)

    @staticmethod
    def _verify_completed(action, result):
        if action in NATIVE_WRITES or action == "commerce-replay":
            _need(isinstance(result, dict) and result.get("schema") == _OPERATOR and
                  isinstance(result.get("result"), dict),
                  "RESEARCH_COMMERCE_OPERATOR_RESULT_CHANGED")
        elif action == "commerce-export":
            _need(isinstance(result, dict) and result.get("schema") == _EXPORT,
                  "RESEARCH_COMMERCE_EXPORT_RESULT_CHANGED")
            with _retained_file(result.get("file")).open():
                pass
        elif action == "commerce-archive-receive":
            ResearchCommerceArchive(result)
        return result

    def configuration(self, *, cancel_event=None):
        return self._read("commerce-configuration", cancel_event=cancel_event)

    def list(self, kind, *, offset=0, limit=30, snapshot=None, cancel_event=None):
        _need(kind in COLLECTIONS and type(offset) is int and offset >= 0 and
              type(limit) is int and 1 <= limit <= 100 and (offset == 0 or snapshot is not None),
              "RESEARCH_COMMERCE_PAGE_INVALID")
        options = {"offset": offset, "limit": limit}
        if snapshot is not None:
            options["snapshot"] = _hash(snapshot)
        return self._read("commerce-list", {"kind": kind, "options": options}, cancel_event=cancel_event)

    def iter_records(self, kind, *, limit=100, cancel_event=None) -> Iterator[dict[str, Any]]:
        """Read all original pages pinned to the first native collection snapshot."""
        offset, total, snapshot = 0, None, None
        while True:
            page = self.list(kind, offset=offset, limit=limit, snapshot=snapshot, cancel_event=cancel_event)
            _need((snapshot is None or page["snapshot"] == snapshot) and
                  (total is None or page["total"] == total),
                  "RESEARCH_COMMERCE_PAGE_CHANGED")
            snapshot, total = page["snapshot"], page["total"]
            yield from deepcopy(page["items"])
            following = page["nextOffset"]
            if following is None:
                return
            _need(type(following) is int and following > offset and following <= total,
                  "RESEARCH_COMMERCE_PAGE_CHANGED")
            offset = following

    def publication(self, publication_id, *, cancel_event=None):
        return self._read("commerce-publication", {"id": publication_id}, cancel_event=cancel_event)

    def purchase(self, purchase_id, *, refresh=False, cancel_event=None):
        _need(type(refresh) is bool, "RESEARCH_COMMERCE_REFRESH_INVALID")
        return self._read("commerce-purchase", {"id": purchase_id, "options": {"refresh": refresh}},
                          cancel_event=cancel_event)

    def file(self, kind, identifier, part, *, cancel_event=None):
        _need(kind in COLLECTIONS and part in FILE_PARTS, "RESEARCH_COMMERCE_FILE_SELECTION_REQUIRED")
        return self._read("commerce-file", {"kind": kind, "id": identifier, "part": part},
                          cancel_event=cancel_event)

    def submit(self, command, value, *, call_id=None, resume=False, cancel_event=None):
        """Send one complete original native input; monetary strings stay exact."""
        action = command if command.startswith("commerce-") else "commerce-" + command
        _need(action in NATIVE_WRITES, "RESEARCH_COMMERCE_COMMAND_INVALID")
        selected = _snapshot(value)
        _need(isinstance(selected, dict), "RESEARCH_COMMERCE_FIELDS_INVALID")
        return self._write(action, {"input": selected},
            call_id=_call_id(action, selected, call_id), resume=resume, cancel_event=cancel_event)

    def prepare_publication(self, value: CommercePublicationRequest, **options) -> CommerceOperationResult:
        return self.submit("publication-prepare", value, **options)

    def enroll_publication(self, value: CommercePublicationEnrollment, **options) -> CommerceOperationResult:
        return self.submit("publication-enroll", value, **options)

    def receive_purchase(self, value, **options) -> CommerceOperationResult:
        return self.submit("purchase-receive", value, **options)

    def receive_publication_file(self, path, *, buyer, request_id, call_id=None,
                                 expected_sha256=None, resume=False, cancel_event=None):
        """Retain complete selected publication bytes in the original request.

        An unchanged saved call can reopen when its donor file has moved. If the
        donor is still present, its complete bytes must match the retained input.
        """
        action = "commerce-purchase-receive"
        selected_id = _call_id(action, {"requestId": request_id}, call_id)
        source = Path(path).expanduser().absolute()
        if expected_sha256 is not None:
            _hash(expected_sha256)
        with self.workspace._operation(cancel_event) as event:
            call_directory = self.workspace._directory_for_call(selected_id, create=True)
            if (call_directory / "request.json").exists():
                saved = self.workspace.call_record(selected_id)["request"]
                value = saved.get("input", {}).get("input")
                _need(saved.get("action") == action and isinstance(value, dict) and
                      value.get("requestId") == request_id and value.get("buyer") == buyer and
                      value.get("filename") == source.name,
                      "RESEARCH_COMMERCE_PUBLICATION_INPUT_CHANGED")
                try:
                    body = base64.b64decode(value["base64"], validate=True)
                except (KeyError, ValueError):
                    raise StateError("RESEARCH_COMMERCE_PUBLICATION_ENCODING_INVALID") from None
                if source.exists() or source.is_symlink():
                    _need(read(source, _PUBLICATION_LIMIT) == body,
                          "RESEARCH_COMMERCE_PUBLICATION_INPUT_CHANGED")
            else:
                body = read(source, _PUBLICATION_LIMIT)
                value = {"requestId": request_id, "buyer": buyer, "filename": source.name,
                         "base64": base64.b64encode(body).decode("ascii")}
            _need(0 < len(body) <= _PUBLICATION_LIMIT and
                  (expected_sha256 is None or digest(body) == expected_sha256),
                  "RESEARCH_COMMERCE_PUBLICATION_INPUT_CHANGED")
            return self._write(action, {"input": value}, call_id=selected_id, resume=resume,
                               _owned_event=event)

    def prepare_purchase(self, value: CommercePurchasePreparation, **options) -> CommerceOperationResult:
        return self.submit("purchase-prepare", value, **options)

    def action(self, kind, value: CommercePurchaseAction, **options) -> CommerceOperationResult:
        _need(kind in BUYER_ACTIONS, "RESEARCH_COMMERCE_BUYER_ACTION_INVALID")
        return self.submit(kind, value, **options)

    def execute(self, value: CommercePurchaseAction, **options) -> CommerceOperationResult:
        return self.action("execute", value, **options)

    def retrieve(self, value: CommercePurchaseAction, **options) -> CommerceOperationResult:
        return self.action("retrieve", value, **options)

    def recover_purchase(self, value: CommercePurchaseAction, **options) -> CommerceOperationResult:
        """Ask the original Buyer to recover its selected purchase operation."""
        return self.action("recover", value, **options)

    def finalize(self, value: CommercePurchaseAction, **options) -> CommerceOperationResult:
        return self.action("finalize", value, **options)

    def cancel(self, value: CommercePurchaseCancellation, **options) -> CommerceOperationResult:
        """Reach the same execution from a separate retained call and native request."""
        return self.action("cancel", value, **options)

    def reconcile(self, value: CommercePurchaseReconciliation, **options):
        return self.submit("reconcile", value, **options)

    def receive_dossier(self, value: CommercePurchaseReceiving, **options) -> CommerceOperationResult:
        return self.submit("receive-dossier", value, **options)

    def export(self, kind, identifier, part, *, call_id, expected_sha256=None,
               resume=False, cancel_event=None):
        """Retain the full original file locally, then reopen it on subsequent calls."""
        _need(kind in COLLECTIONS and part in FILE_PARTS, "RESEARCH_COMMERCE_FILE_SELECTION_REQUIRED")
        value = {"kind": kind, "id": identifier, "part": part}
        if expected_sha256 is not None:
            value["expectedSha256"] = _hash(expected_sha256)
        return self._write("commerce-export", value, call_id=call_id, resume=resume,
                           cancel_event=cancel_event)

    @staticmethod
    def exported_file(result):
        _need(isinstance(result, dict) and result.get("schema") == _EXPORT,
              "RESEARCH_COMMERCE_EXPORT_RESULT_CHANGED")
        value = _retained_file(result.get("file"))
        with value.open():
            pass
        return value

    def inspect_archive(self, path, *, expected_sha256, expected_bytes, cancel_event=None):
        _need(type(expected_bytes) is int and 0 < expected_bytes <= _ARCHIVE_LIMIT,
              "RESEARCH_COMMERCE_ARCHIVE_SIZE_INVALID")
        return self._read("commerce-archive-inspect", {"path": _absolute(path),
            "expectedSha256": _hash(expected_sha256), "expectedBytes": expected_bytes},
            cancel_event=cancel_event)

    def receive_archive(self, *, expected_sha256, expected_bytes, manifest_sha256,
                        call_id, path=None, directory=None, resume=False, cancel_event=None):
        """Receive complete native archive members with a durable local write attempt."""
        _need(type(expected_bytes) is int and 0 < expected_bytes <= _ARCHIVE_LIMIT,
              "RESEARCH_COMMERCE_ARCHIVE_SIZE_INVALID")
        value = {"expectedSha256": _hash(expected_sha256), "expectedBytes": expected_bytes,
                 "manifestSha256": _hash(manifest_sha256)}
        with self.workspace._operation(cancel_event) as event:
            call_directory = self.workspace._directory_for_call(_request_id(call_id), create=True)
            if (call_directory / "request.json").exists():
                saved = self.workspace.call_record(call_id)["request"]
                prior = saved.get("input", {})
                _need(saved.get("action") == "commerce-archive-receive" and
                      all(prior.get(key) == item for key, item in value.items()) and
                      (directory is None or _absolute(directory) == prior.get("directory")) and
                      (path is None or _absolute(path) == prior.get("path")),
                      "RESEARCH_COMMERCE_ARCHIVE_SELECTION_CHANGED")
                value = {key: item for key, item in prior.items() if key != "responseDirectory"}
            else:
                if directory is not None:
                    value["directory"] = _absolute(directory)
                if path is not None:
                    value["path"] = _absolute(path)
            return self._write("commerce-archive-receive", value, call_id=call_id,
                               resume=resume, _owned_event=event)

    def saved(self, call_id):
        """Return the first completed local result without dispatching native work."""
        saved = self.workspace.call_record(_request_id(call_id))
        request, record = saved["request"], saved.get("result")
        _need(request.get("action") in _WRITES and request.get("replaySafe") is True,
              "RESEARCH_COMMERCE_SAVED_CALL_REQUIRED")
        if not record:
            return {"request": deepcopy(request), "attempts": saved["attempts"], "completed": False}
        from .research_workspace import _completed_reply, _value
        if not _completed_reply(record):
            return {"request": deepcopy(request), "attempts": saved["attempts"],
                    "completed": False, "attempt": deepcopy(record)}
        result = self._decode(_value(record, call_id), request["action"], request["input"],
                              request["workspaceId"])
        return {"request": deepcopy(request), "attempts": saved["attempts"], "completed": True,
                "result": self._verify_completed(request["action"], result)}

    def recover(self, call_id, *, cancel_event=None):
        """Recover this same local call; preserve its original native request and reply."""
        saved = self.workspace.call_record(_request_id(call_id))["request"]
        _need(saved.get("action") in _WRITES and saved.get("replaySafe") is True,
              "RESEARCH_COMMERCE_SAVED_CALL_REQUIRED")
        with self.workspace._operation(cancel_event) as event:
            descriptor = self.workspace._write_call(saved["action"], saved["input"],
                request_id=call_id, replay_safe=True, resume=True, event=event,
                local=saved.get("local", False))
            result = self._decode(descriptor, saved["action"], saved["input"], saved["workspaceId"])
            return self._verify_completed(saved["action"], result)

    def replay(self, call_id, *, replay_id, cancel_event=None):
        """Actually submit the original native request in a distinct durable attempt.

        Recovering replay_id subsequently returns its first saved reply. A replay
        may be the original request's first completed mutation, so it always uses
        ResearchWorkspace's mutating attempt and uncertain-outcome semantics.
        """
        _request_id(call_id);_request_id(replay_id)
        _need(call_id != replay_id, "RESEARCH_COMMERCE_REPLAY_CALL_ID_REQUIRED")
        with self.workspace._operation(cancel_event) as event:
            target = self.workspace._directory_for_call(replay_id, create=True)
            if (target / "request.json").exists():
                saved_replay = self.workspace.call_record(replay_id)["request"]
                expected_source = str(self.workspace._directory_for_call(call_id, create=True) /
                                      "commerce-operation")
                _need(saved_replay.get("action") == "commerce-replay" and
                      saved_replay.get("input", {}).get("sourceDirectory") == expected_source,
                      "RESEARCH_COMMERCE_REPLAY_CALL_CHANGED")
                value = {key: item for key, item in saved_replay["input"].items()
                         if key not in {"directory", "responseDirectory"}}
            else:
                original = self.workspace.call_record(call_id)["request"]
                _need(original.get("action") in {*NATIVE_WRITES, "commerce-replay"} and
                      original.get("replaySafe") is True,
                      "RESEARCH_COMMERCE_REPLAY_SOURCE_REQUIRED")
                native = (deepcopy(original["input"]["original"])
                          if original["action"] == "commerce-replay" else
                          {"action": original["action"], "input": deepcopy(original["input"]["input"]),
                           "workspaceId": original["workspaceId"]})
                value = {"sourceDirectory": original["input"]["directory"], "original": native}
            return self._write("commerce-replay", value, call_id=replay_id,
                               resume=True, _owned_event=event)

    def operation(self, call_id, *, cancel_event=None):
        """Inspect the existing original native operator directory for a Python call."""
        original = self.workspace.call_record(_request_id(call_id))["request"]
        _need(original.get("action") in {*NATIVE_WRITES, "commerce-replay", "commerce-export"},
              "RESEARCH_COMMERCE_OPERATOR_CALL_REQUIRED")
        return self._read("commerce-operation", {"directory": original["input"]["directory"]},
                          cancel_event=cancel_event)

"""Original document/job controls and a portable source for native Analysis."""
from __future__ import annotations

from copy import deepcopy
from dataclasses import dataclass
from datetime import datetime, timezone
import hashlib
import os
from pathlib import Path
import stat
import tempfile

from .errors import StateError
from .result import FileDelivery
from .runtime import Runtime, CLI
from .storage import digest, dump, parse, private_directory, read, sync_directory
from .research_workspace import _CALL, _LIMIT, _HASH, _value, _file_delivery

_SOURCE_RECEIPT = "stellar-forge.research-document-analysis.v1"


def _pin_file(path, maximum):
    path = Path(path).expanduser().absolute()
    fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW)
    with os.fdopen(fd, "rb") as stream:
        before = os.fstat(stream.fileno())
        if not stat.S_ISREG(before.st_mode) or not 0 <= before.st_size <= maximum:
            raise StateError("RESEARCH_SELECTED_FILE_INVALID")
        checksum = hashlib.sha256()
        count = 0
        while block := stream.read(1024 * 1024):
            count += len(block)
            if count > maximum:
                raise StateError("RESEARCH_SELECTED_FILE_CHANGED")
            checksum.update(block)
        after = os.fstat(stream.fileno())
        fields = ("st_dev", "st_ino", "st_size", "st_mtime_ns", "st_ctime_ns")
        if count != before.st_size or any(getattr(before, key) != getattr(after, key) for key in fields):
            raise StateError("RESEARCH_SELECTED_FILE_CHANGED")
    return {"file": str(path), "bytes": count, "sha256": checksum.hexdigest()}


@dataclass(frozen=True)
class ResearchInputFile:
    file: Path
    sha256: str
    filename: str | None = None
    content_type: str | None = None

    @classmethod
    def from_file(cls, file, *, filename=None, content_type=None):
        pin = _pin_file(file, 50_000_000)
        return cls(Path(pin["file"]), pin["sha256"], filename, content_type)

    def as_request(self):
        if not isinstance(self.sha256, str) or not _HASH.fullmatch(self.sha256):
            raise StateError("RESEARCH_SELECTED_FILE_DIGEST_REQUIRED")
        value = {"file": str(Path(self.file).expanduser().absolute()), "sha256": self.sha256}
        if self.filename is not None:
            value["filename"] = self.filename
        if self.content_type is not None:
            value["contentType"] = self.content_type
        return value


