@dataclass(frozen=True)
class Run:
    returncode: int
    output: dict | None
    error: str | None
    interrupted: bool = False


class Runtime:
    def __init__(self, checkout, *, node="node", environment=None, timeout=360, output_limit=2_097_152):
        self.checkout = Path(checkout).expanduser().resolve()
        self.cli = self.checkout / CLI
        self.node = shutil.which(os.fspath(node))
        if not self.node or not self.cli.is_file():
            raise StateError("ORIGINAL_NODE_RUNTIME_REQUIRED")
        if not 1 <= timeout <= 3600 or not 8192 <= output_limit <= 16_777_216:
            raise StateError("RUNTIME_LIMIT_INVALID")
        self.environment = None if environment is None else dict(environment)
        self.timeout = timeout
        self.output_limit = output_limit

    def run(self, arguments, *, logs: Path | None = None, started=None, target="buyer", cancel_event=None) -> Run:
        if cancel_event is not None and not isinstance(cancel_event, threading.Event):
            raise StateError("NATIVE_CANCEL_EVENT_INVALID")
        if cancel_event is not None and cancel_event.is_set():
            raise StateError("NATIVE_CANCELLED_BEFORE_START")
        if target != "buyer" and target not in APPLICATIONS:
            raise StateError("ORIGINAL_RUNTIME_TARGET_INVALID")
        entry = self.cli if target == "buyer" else self.checkout / APPLICATIONS[target]
        if not entry.is_file():
            raise StateError("ORIGINAL_APPLICATION_RUNTIME_REQUIRED")
        # Keep the controlling terminal. SF81/SF62 opens /dev/tty itself; this
        # wrapper never synthesizes answers or replaces the native approval.
        stdout = bytearray()
        stderr = bytearray()
        process = None
        selector = selectors.DefaultSelector()
        log_files = {}
        interruption = None
        deadline = time.monotonic() + self.timeout
        kill_at = None
        try:
            if logs:
                for name in ("stdout", "stderr"):
                    fd = os.open(logs / (name + ".json"), os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
                    log_files[name] = os.fdopen(fd, "wb", buffering=0)
            try:
                process = subprocess.Popen([self.node, str(entry), *map(str, arguments)],
                    cwd=self.checkout, env=self.environment, shell=False,
                    stdin=subprocess.DEVNULL, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            except OSError:
                raise NativeError("NATIVE_PROCESS_START_FAILED") from None
            if started:
                started(process.pid)
            for stream, name in ((process.stdout, "stdout"), (process.stderr, "stderr")):
                os.set_blocking(stream.fileno(), False)
                selector.register(stream, selectors.EVENT_READ, name)
            while selector.get_map() or process.poll() is None:
                try:
                    now = time.monotonic()
                    if cancel_event is not None and cancel_event.is_set() and interruption is None:
                        interruption = "NATIVE_CANCELLED"
                    if now >= deadline and interruption is None:
                        interruption = "NATIVE_TIMEOUT"
                    if interruption and kill_at is None:
                        if process.poll() is None:
                            process.send_signal(signal.SIGTERM)
                        kill_at = now + 15
                    if kill_at is not None and now >= kill_at:
                        if process.poll() is None:
                            process.kill()
                        # Descendants cannot keep an abandoned output pipe open.
                        for key in list(selector.get_map().values()):
                            selector.unregister(key.fileobj)
                            key.fileobj.close()
                        break
                    for key, _ in selector.select(0.1):
                        chunk = os.read(key.fd, 65536)
                        if not chunk:
                            selector.unregister(key.fileobj)
                            key.fileobj.close()
                            continue
                        target = stdout if key.data == "stdout" else stderr
                        left = self.output_limit - len(target)
                        target.extend(chunk[:max(0, left)])
                        if logs and left > 0:
                            log_files[key.data].write(chunk[:left])
                        if len(chunk) > left:
                            interruption = "NATIVE_OUTPUT_LIMIT"
                except KeyboardInterrupt:
                    interruption = "NATIVE_INTERRUPTED"
            code = process.wait(timeout=5)
            output = self._object(stdout)
            error_record = self._object(stderr)
            error = error_record.get("error") if error_record else None
            if not isinstance(error, str) or not re.fullmatch(r"[A-Z0-9_]{1,120}", error):
                error = None
            if output is None and not error:
                error = "NATIVE_RESULT_INVALID"
            return Run(code, output, interruption or error, interruption is not None)
        finally:
            selector.close()
            if process:
                if process.poll() is None:
                    process.terminate()
                    try:
                        process.wait(timeout=15)
                    except subprocess.TimeoutExpired:
                        process.kill()
                        process.wait()
                for stream in (process.stdout, process.stderr):
                    if stream and not stream.closed:
                        stream.close()
            for stream in log_files.values():
                os.fsync(stream.fileno())
                stream.close()

    @staticmethod
    def _object(raw):
        try:
            value = parse(bytes(raw))
            return value if isinstance(value, dict) else None
        except StateError:
            return None

    def checked(self, arguments, *, mode: str, target="buyer") -> dict:
        result = self.run(arguments, target=target)
        if result.returncode or result.error or result.output is None or result.output.get("mode") != mode:
            raise NativeError(result.error or "NATIVE_COMMAND_FAILED", returncode=result.returncode)
        return result.output

"""Use original acquired datasets in a durable, local SQLite application."""
from __future__ import annotations

from contextlib import contextmanager
from dataclasses import dataclass
from datetime import datetime, timezone
import hashlib
import json
import math
import os
from pathlib import Path
import re
import sqlite3
import stat
import tempfile
import time

from .datasets import DatasetDelivery
from .dataset_semantics import read_delivery_semantics, sql_descriptor, sql_context
from .errors import StateError
from .storage import digest, parse, private_directory, sync_directory

_APPLICATION = 0x53464442
_FORMAT = "stellar-forge.python-dataset-sqlite.v1"
_HEX = re.compile(r"[a-f0-9]{64}")
_ORDINAL = "_sf_row_number"
_META = "sf_dataset_versions"
_HEADS = "sf_dataset_views"
_HISTORY = "sf_dataset_activations"
_SEMANTICS = "sf_dataset_semantics"


def _json(value):
    return json.dumps(value, ensure_ascii=False, allow_nan=False, sort_keys=True, separators=(",", ":"))


def _identifier(value):
    if not isinstance(value, str) or not value or len(value.encode("utf-8")) > 512 or any(ord(c) < 32 for c in value):
        raise StateError("DATASET_SQL_IDENTIFIER_INVALID")
    return '"' + value.replace('"', '""') + '"'


def _view_name(value):
    if not isinstance(value, str) or not re.fullmatch(r"[a-zA-Z][a-zA-Z0-9_]{0,63}", value) or value.lower().startswith(("sqlite_", "sf_dataset_")):
        raise StateError("DATASET_SQL_VIEW_NAME_INVALID")
    return value


def _scalar(value):
    if value is None:
        return value, "null"
    if type(value) is bool:
        return int(value), "boolean"
    if type(value) is int and -(2**63) <= value < 2**63:
        return value, "integer"
    if type(value) is float and math.isfinite(value):
        return value, "number"
    if isinstance(value, str):
        value.encode("utf-8")
        return value, "string"
    raise StateError("DATASET_SQL_VALUE_NOT_REPRESENTABLE")


@dataclass(frozen=True)
class QueryResult:
    columns: tuple[str, ...]
    rows: tuple[tuple, ...]
    truncated: bool
    views: tuple[dict, ...] = ()
    read_tables: tuple[str, ...] = ()

    def dictionaries(self):
        if len(set(self.columns)) != len(self.columns):
            raise StateError("DATASET_SQL_DUPLICATE_RESULT_NAMES_USE_ALIASES")
        return [dict(zip(self.columns, row)) for row in self.rows]


class DatasetDatabase:
    """A private customer database; acquisition and payment remain in SF88.

    Imports retain independent immutable tables. Named SQL views select a
    version only through activate(), using its current revision. A standard
    SQLite client can read the resulting database without this Python package.
    """

    def __init__(self, directory, *, create=True, busy_timeout=30):
        if not isinstance(busy_timeout, (int, float)) or not math.isfinite(busy_timeout) or not 0 < busy_timeout <= 300:
            raise StateError("DATASET_SQL_BUSY_TIMEOUT_INVALID")
        self.directory = private_directory(Path(directory), create=create)
        self.path = self.directory / "datasets.sqlite3"
        self.busy_timeout = busy_timeout
        if create:
            try:
                fd = os.open(self.path, os.O_CREAT | os.O_EXCL | os.O_RDWR | os.O_NOFOLLOW, 0o600)
            except FileExistsError:
                pass
            else:
                os.close(fd)
                sync_directory(self.directory)
        self._check_file()
        with self._connection(readonly=not create) as db:
            db.execute("BEGIN IMMEDIATE" if create else "BEGIN")
            try:
                application = db.execute("PRAGMA application_id").fetchone()[0]
                version = db.execute("PRAGMA user_version").fetchone()[0]
                objects = db.execute("SELECT name FROM sqlite_master LIMIT 1").fetchone()
                if create and not application and not version and not objects:
                    db.execute(f"CREATE TABLE {_META}(sequence INTEGER PRIMARY KEY,version_id TEXT UNIQUE NOT NULL,created_at TEXT NOT NULL,record TEXT NOT NULL,manifest BLOB NOT NULL)")
                    db.execute(f"CREATE TABLE {_HEADS}(name TEXT PRIMARY KEY COLLATE NOCASE,version_id TEXT NOT NULL REFERENCES {_META}(version_id),revision INTEGER NOT NULL CHECK(revision>0))")
                    db.execute(f"CREATE TABLE {_HISTORY}(sequence INTEGER PRIMARY KEY,name TEXT NOT NULL,version_id TEXT NOT NULL REFERENCES {_META}(version_id),previous_version TEXT,revision INTEGER NOT NULL,activated_at TEXT NOT NULL)")
                    db.execute(f"PRAGMA application_id={_APPLICATION}")
                    db.execute("PRAGMA user_version=1")
                elif application != _APPLICATION or version != 1:
                    raise StateError("DATASET_SQL_DATABASE_FORMAT_MISMATCH")
                if create:
                    # Additive storage belongs to the same immutable edition and
                    # travels in the original SQLite backup/portable workspace.
                    db.execute(f"CREATE TABLE IF NOT EXISTS {_SEMANTICS}(version_id TEXT PRIMARY KEY REFERENCES {_META}(version_id),document BLOB NOT NULL)")
                db.commit()
            except BaseException:
                db.rollback()
                raise

    def _check_file(self):
        if private_directory(self.directory, create=False) != self.directory:
            raise StateError("DATASET_SQL_DIRECTORY_CHANGED")
        try:
            fd = os.open(self.path, os.O_RDONLY | os.O_NOFOLLOW)
            try:
                info = os.fstat(fd)
                if not stat.S_ISREG(info.st_mode) or info.st_nlink != 1 or info.st_mode & 0o077:
                    raise StateError("DATASET_SQL_PRIVATE_FILE_REQUIRED")
            finally:
                os.close(fd)
        except OSError:
            raise StateError("DATASET_SQL_FILE_UNAVAILABLE") from None

    @contextmanager
    def _connection(self, *, readonly=False):
        self._check_file()
        db = sqlite3.connect(self.path.as_uri() + ("?mode=ro" if readonly else "?mode=rw"), uri=True,
                             isolation_level=None, timeout=self.busy_timeout)
        try:
            db.row_factory = sqlite3.Row
            db.execute("PRAGMA foreign_keys=ON")
            db.execute("PRAGMA trusted_schema=OFF")
            if readonly:
                db.execute("PRAGMA query_only=ON")
            else:
                db.execute("PRAGMA synchronous=FULL")
            yield db
        finally:
            db.close()

    @staticmethod
    def _version(db, version_id):
        row = db.execute(f"SELECT sequence,record FROM {_META} WHERE version_id=?", (version_id,)).fetchone()
        if row is None:
            raise StateError("DATASET_SQL_VERSION_NOT_FOUND")
        record = {**parse(row["record"].encode()), "sequence": row["sequence"]}
        if record.get("semantics") is not None:
            retained = db.execute(f"SELECT document FROM {_SEMANTICS} WHERE version_id=?", (version_id,)).fetchone()
            if retained is None:
                raise StateError("DATASET_SQL_SEMANTIC_DOCUMENT_MISSING")
            context = sql_context(bytes(retained["document"]), record["semantics"], version_id)
            record["semantic_dictionary"] = context["document"]
        return record

    def import_delivery(self, delivery: DatasetDelivery, *, columns=None):
        """Commit the verified complete room once; do not change any named view.

        columns optionally maps original field names to SQLite column names.
        Values keep their native JSON scalar types; SQLite stores booleans as
        integers and this record retains each column's observed JSON types.
        """
        if not isinstance(delivery, DatasetDelivery):
            raise StateError("DATASET_SQL_ORIGINAL_DELIVERY_REQUIRED")
        native = delivery.native
        status = native.get("nativeStatus") or {}
        binding = native.get("sourceBindingSha256")
        if native.get("schema") not in {"stellar-forge.sf88.dataset-delivery.v1", "stellar-forge.sf100.dataset-delivery.v1"} or not isinstance(binding, str) or not _HEX.fullmatch(binding) or status.get("complete") is not True or status.get("finalized") is not True:
            raise StateError("DATASET_SQL_COMPLETE_NATIVE_DELIVERY_REQUIRED")
        manifest_bytes = delivery.file("manifest.json").read_bytes(limit=4 * 1024 * 1024)
        manifest_sha = digest(manifest_bytes)
        if manifest_sha != native["outputs"]["manifest.json"]["sha256"]:
            raise StateError("DATASET_SQL_MANIFEST_CHANGED")
        manifest = parse(manifest_bytes)
        dataset = manifest.get("dataset") or {}
        fields = dataset.get("projectedFields")
        total = dataset.get("rows")
        source_pages = manifest.get("sourcePages")
        if manifest.get("schema") != "stellar-forge.buyer-delivery-manifest.v1" or not isinstance(fields, list) or not fields or len(fields) > 1024 or not all(isinstance(field, str) for field in fields) or len(set(fields)) != len(fields) or type(total) is not int or not 0 <= total <= 1_000_000 or status.get("rows") != total or status.get("snapshot") != dataset.get("snapshot") or not isinstance(source_pages, list) or status.get("pages") != len(source_pages) or manifest.get("paymentStatus") != native.get("paymentStatus"):
            raise StateError("DATASET_SQL_MANIFEST_BINDING_INVALID")
        columns = {} if columns is None else columns
        if not isinstance(columns, dict) or set(columns) - set(fields):
            raise StateError("DATASET_SQL_COLUMN_MAPPING_INVALID")
        mapped = [columns.get(field, field) for field in fields]
        quoted = [_identifier(column) for column in mapped]
        folded = [column.lower() for column in mapped]
        if len(set(folded)) != len(folded) or _ORDINAL in folded:
            raise StateError("DATASET_SQL_COLUMN_COLLISION_USE_MAPPING")
        source = native["outputs"]["dataset.jsonl"]
        if manifest.get("outputs", {}).get("dataset.jsonl") != {key: source[key] for key in ("bytes", "sha256")}:
            raise StateError("DATASET_SQL_ROW_BINDING_INVALID")
        semantics = read_delivery_semantics(delivery, manifest=manifest)
        semantic_mapping = sql_descriptor(semantics, fields, mapped) if semantics else None
        identity = {"schema": _FORMAT, "manifestSha256": manifest_sha, "sourceBindingSha256": binding,
                    "columns": list(zip(fields, mapped))}
        return self._import_rows(manifest_bytes=manifest_bytes, identity=identity, fields=fields,
            mapped=mapped, total=total, source=source, opener=delivery.file("dataset.jsonl").open,
            semantics=semantics,
            details={"dataset": dataset, "sourceDirectory": native.get("sourceDirectory"),
                     "source_pages": len(source_pages), "originalPaymentStatus": native.get("paymentStatus"),
                     **({"semantics": semantic_mapping} if semantic_mapping else {})})

    def import_response(self, projection, *, allow_incomplete=False):
        """Commit a complete analytical projection with its distinct source manifest.

        This consumes retained response records only. It neither fabricates an
        SF100 delivery nor changes the original source's payment/completion state.
        """
        from .response_tables import ResponseProjection, SCHEMA
        if not isinstance(projection, ResponseProjection) or projection.manifest.get("schema") != SCHEMA:
            raise StateError("DATASET_SQL_RESPONSE_PROJECTION_REQUIRED")
        manifest = parse(projection.manifest_bytes)
        if type(allow_incomplete) is not bool:
            raise StateError("ANALYSIS_INCOMPLETE_ACKNOWLEDGEMENT_INVALID")
        if manifest["completion"]["requiresIncompleteAcknowledgement"] and not allow_incomplete:
            raise StateError("ANALYSIS_ACKNOWLEDGE_INCOMPLETE_RESPONSE")
        manifest["completion"]["incompleteAcknowledged"] = allow_incomplete
        manifest_bytes = _json(manifest).encode()
        fields, source = manifest["projectedFields"], manifest["outputs"]["mapped.jsonl"]
        identity = {"schema": _FORMAT, "manifestSha256": digest(manifest_bytes),
                    "sourceBindingSha256": manifest["sourceBindingSha256"], "columns": list(zip(fields, fields))}
        dataset = {"kind": "retained-response", "name": manifest["name"], "rows": manifest["rows"],
                   "projectedFields": fields, "response": manifest["source"],
                   "completion": manifest["completion"], "mapping": manifest["mapping"],
                   "missingAsNull": manifest["missingAsNull"]}
        from .result import FileDelivery
        file = FileDelivery({"native": {"file": {**source, "path": str(projection.path)}}},
                            projection.path, 128 * 1024 * 1024)
        return self._import_rows(manifest_bytes=manifest_bytes, identity=identity, fields=fields,
            mapped=fields, total=manifest["rows"], source=source, opener=file.open,
            details={"dataset": dataset, "source_pages": None,
                     "row_representation": "explicit-response-projection",
                     "originalPaymentStatus": manifest["source"]["original"].get("paymentStatus")})

    def _import_rows(self, *, manifest_bytes, identity, fields, mapped, total, source, opener, details, semantics=None):
        """One original transaction and scalar/type policy for both native inputs."""
        version_id = digest(_json(identity).encode())
        table = "sf_dataset_rows_" + version_id
        quoted = [_identifier(column) for column in mapped]
        with self._connection() as db, opener() as stream:
            db.execute("BEGIN IMMEDIATE")
            try:
                existing = db.execute(f"SELECT version_id FROM {_META} WHERE version_id=?", (version_id,)).fetchone()
                if existing:
                    record = self._version(db, version_id)
                    db.commit()
                    return {**record, "import_status": "UNCHANGED"}
                # No declared type means no affinity conversion: numeric strings
                # and exact decimal text remain TEXT, while numbers remain numbers.
                db.execute(f"CREATE TABLE {_identifier(table)}({_identifier(_ORDINAL)} INTEGER PRIMARY KEY," + ",".join(quoted) + ")")
                insert = f"INSERT INTO {_identifier(table)} VALUES(" + ",".join("?" for _ in range(len(fields) + 1)) + ")"
                observed = [set() for _ in fields]
                checksum = hashlib.sha256()
                count = size = 0
                while raw := stream.readline(2_097_153):
                    if len(raw) > 2_097_152 or not raw.endswith(b"\n"):
                        raise StateError("DATASET_SQL_ROW_FORMAT_INVALID")
                    checksum.update(raw)
                    size += len(raw)
                    count += 1
                    if count > total or size > source["bytes"]:
                        raise StateError("DATASET_SQL_ROWS_CHANGED")
                    row = parse(raw)
                    if not isinstance(row, dict) or set(row) != set(fields):
                        raise StateError("DATASET_SQL_ROW_FIELDS_MISMATCH")
                    values = []
                    for index, field in enumerate(fields):
                        value, kind = _scalar(row[field])
                        values.append(value)
                        observed[index].add(kind)
                    db.execute(insert, (count, *values))
                if count != total or size != source["bytes"] or checksum.hexdigest() != source["sha256"]:
                    raise StateError("DATASET_SQL_ROWS_CHANGED")
                record = {**identity, "version_id": version_id, "table": table,
                          "created_at": datetime.now(timezone.utc).isoformat(), "row_count": count,
                          **details,
                          "jsonl": {key: source[key] for key in ("bytes", "sha256")},
                          "column_types": [{"source": field, "column": mapped[index], "json_types": sorted(observed[index])}
                                           for index, field in enumerate(fields)], "row_order_column": _ORDINAL}
                db.execute(f"INSERT INTO {_META}(version_id,created_at,record,manifest) VALUES(?,?,?,?)",
                           (version_id, record["created_at"], _json(record), manifest_bytes))
                if semantics is not None:
                    db.execute(f"INSERT INTO {_SEMANTICS}(version_id,document) VALUES(?,?)",
                               (version_id, semantics["bytes"]))
                record = self._version(db, version_id)
                db.commit()
                return {**record, "import_status": "IMPORTED"}
            except BaseException:
                db.rollback()
                raise

    def version(self, version_id):
        with self._connection(readonly=True) as db:
            return self._version(db, version_id)

    def manifest(self, version_id):
        """Read the exact original manifest retained with the acquired rows."""
        return parse(self.manifest_bytes(version_id))

    def manifest_bytes(self, version_id):
        """Return the original, hash-verified bytes without JSON re-encoding."""
        with self._connection(readonly=True) as db:
            row = db.execute(f"SELECT manifest,record FROM {_META} WHERE version_id=?", (version_id,)).fetchone()
            if row is None:
                raise StateError("DATASET_SQL_VERSION_NOT_FOUND")
            if digest(row["manifest"]) != parse(row["record"].encode())["manifestSha256"]:
                raise StateError("DATASET_SQL_RETAINED_MANIFEST_CHANGED")
            return bytes(row["manifest"])

    def semantics(self, version_id):
        """Original meanings plus reviewed source-to-SQL mapping, or None."""
        with self._connection(readonly=True) as db:
            db.execute("BEGIN")
            version = self._version(db, version_id)
            if version.get("semantics") is None:
                return None
            return {**version["semantics"], "version_id": version_id,
                    "document": version["semantic_dictionary"]}

    def semantics_bytes(self, version_id):
        """Return the exact retained dictionary file from this SQL edition."""
        with self._connection(readonly=True) as db:
            db.execute("BEGIN")
            version = self._version(db, version_id)
            if version.get("semantics") is None:
                return None
            row = db.execute(f"SELECT document FROM {_SEMANTICS} WHERE version_id=?", (version_id,)).fetchone()
            raw = bytes(row["document"])
            sql_context(raw, version["semantics"], version_id)
            return raw

    def compare_semantics(self, before_id, after_id):
        """Compare source meaning and SQL mapping separately from row changes."""
        with self._connection(readonly=True) as db:
            db.execute("BEGIN")
            before = self._version(db, before_id)
            after = self._version(db, after_id)
        first, second = before.get("semantics"), after.get("semantics")
        def columns(version):
            meanings = {column["name"]: column for column in version.get("semantic_dictionary", {}).get("columns", [])}
            return {column["source"]: {"sql_column": column["column"], "meaning": meanings.get(column["source"])}
                    for column in version.get("column_types", [])}
        left, right = columns(before), columns(after)
        changes = [{"source": name, "before": left.get(name), "after": right.get(name)}
                   for name in sorted(set(left) | set(right)) if left.get(name) != right.get(name)]
        return {"schema": "stellar-forge.python-semantic-comparison.v1",
                "before_version": before_id, "after_version": after_id,
                "before": first, "after": second,
                "definition_changed": (first or {}).get("definition_sha256") != (second or {}).get("definition_sha256"),
                "capture_changed": (first or {}).get("capture_manifest_sha256") != (second or {}).get("capture_manifest_sha256"),
                "mapping_changed": before.get("columns") != after.get("columns"),
                "columns": changes,
                "before_document": before.get("semantic_dictionary"),
                "after_document": after.get("semantic_dictionary")}

    def versions(self, *, before=None, limit=100):
        if type(limit) is not int or not 1 <= limit <= 1000 or before is not None and (type(before) is not int or before < 1):
            raise StateError("DATASET_SQL_HISTORY_PAGE_INVALID")
        with self._connection(readonly=True) as db:
            rows = db.execute(f"SELECT sequence,record FROM {_META} WHERE (? IS NULL OR sequence<?) ORDER BY sequence DESC LIMIT ?", (before, before, limit + 1)).fetchall()
            return {"versions": [{**parse(row["record"].encode()), "sequence": row["sequence"]} for row in rows[:limit]],
                    "next_before": rows[limit - 1]["sequence"] if len(rows) > limit else None}

    def current(self, name):
        with self._connection(readonly=True) as db:
            db.execute("BEGIN")
            row = db.execute(f"SELECT * FROM {_HEADS} WHERE name=?", (_view_name(name),)).fetchone()
            return {"name": name, "revision": 0, "version": None} if row is None else {"name": row["name"], "revision": row["revision"], "version": self._version(db, row["version_id"])}

    def activate(self, name, version_id, *, expected_revision):
        """Atomically select an imported version for one ordinary SQL view."""
        with self._connection() as db:
            db.execute("BEGIN IMMEDIATE")
            try:
                result = self._activate(db, name, version_id, expected_revision=expected_revision)
                db.commit()
                return result
            except BaseException:
                db.rollback()
                raise

    def _activate(self, db, name, version_id, *, expected_revision):
        """Apply the original view transition inside an owner's transaction.

        The analysis workspace uses this same operation to retain its reviewed
        comparison and select the candidate in one commit.
        """
        name = _view_name(name)
        if type(expected_revision) is not int or expected_revision < 0:
            raise StateError("DATASET_SQL_REVISION_REQUIRED")
        version = self._version(db, version_id)
        current = db.execute(f"SELECT * FROM {_HEADS} WHERE name=?", (name,)).fetchone()
        revision = current["revision"] if current else 0
        if revision != expected_revision:
            raise StateError("DATASET_SQL_VIEW_CHANGED")
        if current and current["version_id"] == version_id:
            return {"name": current["name"], "revision": revision, "version": version, "activation_status": "UNCHANGED"}
        if current:
            db.execute(f"DROP VIEW {_identifier(current['name'])}")
        elif db.execute("SELECT 1 FROM sqlite_master WHERE name=? COLLATE NOCASE", (name,)).fetchone():
            raise StateError("DATASET_SQL_VIEW_NAME_IN_USE")
        db.execute(f"CREATE VIEW {_identifier(name)} AS SELECT * FROM {_identifier(version['table'])}")
        db.execute(f"INSERT INTO {_HEADS}(name,version_id,revision) VALUES(?,?,?) ON CONFLICT(name) DO UPDATE SET version_id=excluded.version_id,revision=excluded.revision", (name, version_id, revision + 1))
        db.execute(f"INSERT INTO {_HISTORY}(name,version_id,previous_version,revision,activated_at) VALUES(?,?,?,?,?)",
                   (name, version_id, current["version_id"] if current else None, revision + 1, datetime.now(timezone.utc).isoformat()))
        return {"name": name, "revision": revision + 1, "version": version, "activation_status": "ACTIVATED"}

    def view_bindings(self):
        """Current named-view identities, suitable for a later query review."""
        with self._connection(readonly=True) as db:
            return self._views(db)

    @staticmethod
    def _views(db):
        return [dict(row) for row in db.execute(f"SELECT name,version_id,revision FROM {_HEADS} ORDER BY name COLLATE NOCASE")]

    def query(self, sql, parameters=(), *, max_rows=1000, max_result_bytes=16 * 1024 * 1024, timeout=10, expected_views=None):
        """Read-only SQL with result limits and the exact transaction's views.

        Pass a previously reviewed view_bindings() list to reject a changed
        analytical selection. The view snapshot and rows share one read
        transaction; immutable physical table names are also retained.
        """
        with self._connection(readonly=True) as db:
            db.execute("BEGIN")
            return self._query(db, sql, parameters, max_rows=max_rows,
                               max_result_bytes=max_result_bytes, timeout=timeout,
                               expected_views=expected_views)

    def _query(self, db, sql, parameters=(), *, max_rows=1000, max_result_bytes=16 * 1024 * 1024, timeout=10, expected_views=None):
        """Use the original SQL reader inside an already opened transaction."""
        if not db.in_transaction:
            raise StateError("DATASET_SQL_TRANSACTION_REQUIRED")
        if not isinstance(sql, str) or type(max_rows) is not int or not 1 <= max_rows <= 100_000 or type(max_result_bytes) is not int or not 1 <= max_result_bytes <= 256 * 1024 * 1024 or not isinstance(timeout, (int, float)) or not math.isfinite(timeout) or not 0 < timeout <= 300:
            raise StateError("DATASET_SQL_QUERY_OPTIONS_INVALID")
        from .query_stream import open_query, row_bytes
        try:
            with open_query(self, db, sql, parameters, timeout=timeout,
                            expected_views=expected_views) as stream:
                rows, size, truncated = [], 0, False
                for values in stream:
                    length = row_bytes(values)
                    if len(rows) == max_rows or size + length > max_result_bytes:
                        truncated = True
                        break
                    rows.append(values)
                    size += length
                return QueryResult(stream.columns, tuple(rows), truncated,
                                   tuple(stream.views), stream.read_tables)
        except StateError as exc:
            # Keep the existing preview/report error contract.
            if exc.code == "DATASET_SQL_QUERY_TIMEOUT":
                raise StateError("DATASET_SQL_QUERY_FAILED") from exc
            raise

    @contextmanager
    def stream_query(self, sql, parameters=(), *, timeout=300, expected_views=None, cancel=None):
        """Yield every row from one reviewed snapshot without materializing it.

        Use as a context manager so an early break closes the cursor and read
        transaction. cancel is an optional callable such as Event.is_set.
        """
        from .query_stream import open_query
        with self._connection(readonly=True) as db:
            db.execute("BEGIN")
            with open_query(self, db, sql, parameters, timeout=timeout,
                            expected_views=expected_views, cancel=cancel) as stream:
                yield stream

    def export_query(self, sql, parameters=(), *, destination, **options):
        """Write a complete private JSONL/CSV/SQLite result from the same reader."""
        from .query_export import export_query
        return export_query(self, sql, parameters, destination=destination, **options)

    def backup(self, destination):
        """Publish a consistent, create-only database copy that reopens normally."""
        folder = private_directory(Path(destination), create=True)
        target = folder / "datasets.sqlite3"
        if target.exists():
            raise StateError("DATASET_SQL_BACKUP_DESTINATION_EXISTS")
        fd, temporary = tempfile.mkstemp(prefix=".database-", dir=folder)
        os.close(fd)
        try:
            with self._connection(readonly=True) as source:
                copy = sqlite3.connect(temporary)
                try:
                    source.backup(copy)
                finally:
                    copy.close()
            with open(temporary, "rb") as stream:
                os.fsync(stream.fileno())
            os.link(temporary, target)
            sync_directory(folder)
        finally:
            os.unlink(temporary)
            sync_directory(folder)
        return target

"""Private local operation storage. No wallet keys or substitute payment ledger."""
from __future__ import annotations

from contextlib import contextmanager
import fcntl
import hashlib
import json
import os
from pathlib import Path
import stat
import tempfile

from .errors import StateError


def digest(raw: bytes) -> str:
    return hashlib.sha256(raw).hexdigest()


def unique_object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise StateError("DUPLICATE_JSON_KEY")
        result[key] = value
    return result


def parse(raw: bytes):
    try:
        return json.loads(raw.decode("utf-8"), object_pairs_hook=unique_object,
                          parse_constant=lambda _: (_ for _ in ()).throw(ValueError()))
    except (ValueError, UnicodeError):
        raise StateError("INVALID_JSON") from None


def read(path: Path, limit: int) -> bytes:
    try:
        fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW)
        with os.fdopen(fd, "rb") as stream:
            info = os.fstat(stream.fileno())
            if not stat.S_ISREG(info.st_mode) or info.st_size > limit:
                raise StateError("FILE_LIMIT_OR_TYPE_INVALID")
            data = stream.read(limit + 1)
        if len(data) > limit:
            raise StateError("FILE_LIMIT_OR_TYPE_INVALID")
        return data
    except OSError:
        raise StateError("FILE_UNAVAILABLE") from None


def private_directory(path: Path, *, create=True) -> Path:
    path = path.expanduser().absolute()
    if create:
        path.mkdir(mode=0o700, parents=True, exist_ok=True)
    try:
        info = path.lstat()
        if not stat.S_ISDIR(info.st_mode) or info.st_mode & 0o077:
            raise StateError("PRIVATE_DIRECTORY_REQUIRED")
    except OSError:
        raise StateError("PRIVATE_DIRECTORY_REQUIRED") from None
    return path.resolve()


def sync_directory(path: Path):
    fd = os.open(path, os.O_RDONLY | os.O_DIRECTORY)
    try:
        os.fsync(fd)
    finally:
        os.close(fd)


def write(path: Path, data: bytes, *, exclusive=False):
    fd, name = tempfile.mkstemp(prefix=".write-", dir=path.parent)
    try:
        with os.fdopen(fd, "wb") as stream:
            stream.write(data)
            stream.flush()
            os.fsync(stream.fileno())
        if exclusive:
            # Publish a complete record without overwriting an existing one.
            # Readers cannot observe an empty/partial final result or attempt.
            os.link(name, path)
        else:
            os.replace(name, path)
        sync_directory(path.parent)
    finally:
        try:
            os.unlink(name)
        except FileNotFoundError:
            pass


def dump(path: Path, value, *, exclusive=False):
    write(path, (json.dumps(value, ensure_ascii=False, allow_nan=False, indent=2) + "\n").encode(),
          exclusive=exclusive)


@contextmanager
def lock(directory: Path):
    fd = os.open(directory / "operation.lock", os.O_RDWR | os.O_CREAT | os.O_NOFOLLOW, 0o600)
    try:
        try:
            fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except BlockingIOError:
            raise StateError("OPERATION_BUSY") from None
        yield
    finally:
        os.close(fd)

"""Typed, reusable records from the original Node retained-response reader."""
from __future__ import annotations

from dataclasses import dataclass
import json
import os
from pathlib import Path
import shutil
import tempfile
from typing import Any, Iterator
from types import SimpleNamespace

from .errors import DeliveryError, StateError
from .storage import digest, lock, parse, private_directory, read, sync_directory, write

SCHEMA = "stellar-forge.python-stream-export.v1"
MAX_EXPORT_BYTES = 256 * 1024 * 1024


@dataclass(frozen=True)
class SSEEvent:
    index: int
    event: str
    data: str
    id: str
    retry: int | None = None

    def json(self) -> Any:
        """Parse application JSON explicitly; ordinary SSE data stays text."""
        return parse(self.data.encode("utf-8"))


@dataclass(frozen=True)
class NDJSONRecord:
    index: int
    value: Any


@dataclass(frozen=True)
class StreamDelivery:
    """The fully validated native record export; original raw bytes stay retained."""
    directory: Path
    manifest: dict

    @property
    def format(self):
        return self.manifest["format"]

    @property
    def complete(self):
        return self.manifest["complete"]

    @property
    def count(self):
        return self.manifest["records"]

    @property
    def source(self):
        return dict(self.manifest["source"])

    @property
    def file(self):
        from .result import FileDelivery
        metadata = {**self.manifest["file"], "path": str(self.directory / "records.jsonl")}
        return FileDelivery({"returncode": 0, "native": {"status": "FILE_SAVED", "file": metadata}},
                            Path(metadata["path"]), self.manifest["maxExportBytes"])

    def records(self, *, start=0) -> Iterator[SSEEvent | NDJSONRecord]:
        """Resume application consumption by original zero-based record index."""
        if type(start) is not int or not 0 <= start <= self.count:
            raise DeliveryError("STREAM_RECORD_INDEX_INVALID")
        # Reuse the existing Python file reader: it hashes the complete file
        # before exposing the same open descriptor, including when resuming.
        with self.file.open() as stream:
            index = 0
            maximum = self.manifest["maxExportBytes"]
            while raw := stream.readline(maximum + 1):
                if len(raw) > maximum or not raw.endswith(b"\n"):
                    raise DeliveryError("STREAM_EXPORT_RECORD_INVALID")
                value = parse(raw)
                if (not isinstance(value, dict) or value.get("format") != self.format
                        or type(value.get("index")) is not int or value["index"] != index):
                    raise DeliveryError("STREAM_EXPORT_RECORD_INVALID")
                if self.format == "sse":
                    if (not all(isinstance(value.get(key), str) for key in ("event", "data", "id"))
                            or ("retry" in value and (type(value["retry"]) is not int or value["retry"] < 0))):
                        raise DeliveryError("STREAM_EXPORT_RECORD_INVALID")
                    record = SSEEvent(index, value["event"], value["data"], value["id"], value.get("retry"))
                else:
                    if "value" not in value:
                        raise DeliveryError("STREAM_EXPORT_RECORD_INVALID")
                    record = NDJSONRecord(index, value["value"])
                if index >= start:
                    yield record
                index += 1
            if index != self.count:
                raise DeliveryError("STREAM_EXPORT_COUNT_CHANGED")

    def events(self, *, start=0) -> Iterator[SSEEvent]:
        if self.format != "sse":
            raise DeliveryError("RESPONSE_STREAM_FORMAT_MISMATCH")
        yield from self.records(start=start)

    def ndjson(self, *, start=0) -> Iterator[Any]:
        if self.format != "ndjson":
            raise DeliveryError("RESPONSE_STREAM_FORMAT_MISMATCH")
        for record in self.records(start=start):
            yield record.value


def _manifest(directory, fingerprint):
    result = parse(read(directory / "manifest.json", 1_048_576))
    if (not isinstance(result, dict) or result.get("schema") != SCHEMA
            or result.get("requestSha256") != fingerprint
            or result.get("format") not in ("sse", "ndjson")
            or type(result.get("complete")) is not bool
            or type(result.get("records")) is not int or result["records"] < 0
            or not isinstance(result.get("source"), dict)
            or not isinstance(result.get("file"), dict)
            or result["file"].get("path") != "records.jsonl"
            or type(result.get("maxExportBytes")) is not int
            or not 1 <= result["maxExportBytes"] <= 1_073_741_824):
        raise DeliveryError("STREAM_EXPORT_MANIFEST_INVALID")
    return StreamDelivery(directory, result)


def export_stream(result, *, format=None, allow_partial=False, max_record_bytes=None,
                  max_records=None, max_export_bytes=MAX_EXPORT_BYTES, cache_dir=None):
    runtime = result._runtime
    configuration = result._response_file
    if runtime is None or not isinstance(configuration, dict):
        raise StateError("ORIGINAL_STREAM_RUNTIME_REQUIRED")
    selected = configuration.get("stream") or result.delivery.get("stream") or {}
    format = selected.get("format") if format is None else format
    if format not in ("sse", "ndjson") or type(allow_partial) is not bool:
        raise DeliveryError("RESPONSE_STREAM_READ_OPTIONS_INVALID")
    if type(max_export_bytes) is not int or not 1 <= max_export_bytes <= 1_073_741_824:
        raise DeliveryError("STREAM_EXPORT_BYTE_LIMIT_INVALID")
    options = {"allowPartial": allow_partial}
    if max_record_bytes is not None:
        options["maxRecordBytes"] = max_record_bytes
    if max_records is not None:
        options["maxRecords"] = max_records
    payload = {"schema": "stellar-forge.python-stream-request.v1", "record": result.record,
               "responseFile": configuration, "format": format, "options": options,
               "maxExportBytes": max_export_bytes}
    raw = (json.dumps(payload, sort_keys=True, ensure_ascii=False, allow_nan=False,
                      separators=(",", ":")) + "\n").encode("utf-8")
    fingerprint = digest(raw)
    if cache_dir is None:
        if result._operation_directory is None:
            raise StateError("STREAM_EXPORT_DIRECTORY_REQUIRED")
        cache_dir = result._operation_directory / "stream-exports"
    root = private_directory(Path(cache_dir))
    destination = root / fingerprint
    with lock(root):
        if destination.exists():
            private_directory(destination, create=False)
            return _manifest(destination, fingerprint)
        temporary = Path(tempfile.mkdtemp(prefix=".stream-", dir=root))
        try:
            request = temporary / "source.json"
            write(request, raw, exclusive=True)
            native = runtime.checked(["export-stream", "--input", request, "--out", temporary],
                                     mode="ORIGINAL_PYTHON_STREAM_EXPORTED", target="consumer")
            saved = _manifest(temporary, fingerprint)
            if native != saved.manifest:
                raise DeliveryError("STREAM_EXPORT_RESULT_CHANGED")
            # Publish a complete directory only after the original reader's
            # framing and both source hash passes have finished successfully.
            os.rename(temporary, destination)
            sync_directory(root)
            return StreamDelivery(destination, saved.manifest)
        finally:
            if temporary.exists():
                shutil.rmtree(temporary)


def read_retained_response(*, checkout, config_file, result_file, cache_dir,
                           node="node", timeout=360):
    """Open an existing SF88 result for local consumption without buyer import.

    Accept the original CLI result or its existing Node/Python application
    envelope. This does not create an operation, approval or payment record.
    """
    from .result import BuyerResult
    from .runtime import Runtime
    config_raw = read(Path(config_file).expanduser().absolute(), 65536)
    result_raw = read(Path(result_file).expanduser().absolute(), 2_097_152)
    config, record = parse(config_raw), parse(result_raw)
    if not isinstance(config, dict) or not isinstance(record, dict):
        raise StateError("ORIGINAL_RETAINED_RESULT_REQUIRED")
    if record.get("mode") == "ORIGINAL_OPERATOR_APPROVED_BUYER_ATTEMPT":
        record = {"native": record}
    native = record.get("native")
    if (not isinstance(native, dict) or native.get("mode") != "ORIGINAL_OPERATOR_APPROVED_BUYER_ATTEMPT"
            or native.get("intentId") != config.get("operation", {}).get("intentId")):
        raise StateError("ORIGINAL_RETAINED_RESULT_REQUIRED")
    # Bind these original files into the export identity without changing them
    # or pretending a raw CLI result recorded a process exit code.
    if record.get("configSha256") is not None and record["configSha256"] != digest(config_raw):
        raise StateError("RESULT_CONFIG_MISMATCH")
    record = {**record, "retainedSourceFiles": {"configSha256": digest(config_raw),
                                              "resultSha256": digest(result_raw)}}
    response = config.get("responseFile")
    if not isinstance(response, dict) or not response.get("destination"):
        raise StateError("ORIGINAL_RESPONSE_FILE_REQUIRED")
    root = private_directory(Path(cache_dir))
    return BuyerResult(record, Path(response["destination"]), response.get("maxBytes", 67_108_864),
                       _runtime=Runtime(checkout, node=node, timeout=timeout),
                       _response_file={"maxBytes": 67_108_864, **response}, _operation_directory=root)


def export_saved_stream(*, checkout, response_file, saved, cache_dir, node="node", timeout=360, **options):
    """Consume an original SF31 writer receipt without creating a buyer attempt.

    ``response_file`` is the actual writer configuration. ``saved`` is its
    retained SAVED/FAILED responseFile view, including original stream metadata.
    The existing Node reader validates the full source hash and framed prefix.
    """
    from .runtime import Runtime
    if not isinstance(response_file, dict) or not isinstance(saved, dict):
        raise StateError("ORIGINAL_RESPONSE_FILE_REQUIRED")
    source = SimpleNamespace(
        record={"retainedSourceKind": "SF31_RESPONSE_FILE", "native": {"responseFile": saved}},
        delivery=saved, _response_file={"maxBytes": 67_108_864, **response_file},
        _runtime=Runtime(checkout, node=node, timeout=timeout),
        _operation_directory=private_directory(Path(cache_dir)),
    )
    return export_stream(source, **options)

"""Synthesis routes on the original Analysis origin and capability owner."""
from ._analysis_export_http import send_export
from .evidence_synthesis import need


def assets():
    from . import _analysis_synthesis_ui as ui
    return {"/synthesis": (ui.HTML, "text/html;charset=utf-8"),
            "/synthesis.js": (ui.JS, "text/javascript;charset=utf-8"),
            "/synthesis.css": (ui.CSS, "text/css;charset=utf-8")}


def _only(query, allowed):
    need(not set(query) - set(allowed), "QUERY_FIELDS_INVALID")


def get(handler, workspace, url, query, parts):
    if handler.command not in {"GET", "HEAD"}:
        return False
    value = lambda key, default=None: query.get(key, [default])[0]
    optional_int = lambda key: int(value(key)) if value(key) is not None else None
    owner = workspace.synthesis
    result = None
    if url.path == "/api/synthesis":
        _only(query, {"kind", "before", "limit"})
        result = owner.history(kind=value("kind", "protocols"), before=optional_int("before"),
                               limit=int(value("limit", "25")))
    elif len(parts) == 3 and parts[:2] == ["api", "synthesis-publications"]:
        _only(query, {"revision", "offset", "limit"})
        result = owner.publication(parts[2], revision=optional_int("revision"),
                                   offset=int(value("offset", "0")), limit=int(value("limit", "50")))
    elif len(parts) == 4 and parts[:2] == ["api", "synthesis-publications"] and parts[3] == "source":
        need(set(query) == {"revision"}, "SOURCE_REVISION_REQUIRED")
        with owner.download_publication(parts[2], int(value("revision"))) as (stream, record):
            send_export(handler, stream, record)
        return True
    elif len(parts) == 3 and parts[:2] == ["api", "synthesis-protocols"]:
        _only(query, {"revision"})
        result = owner.protocol(parts[2], revision=optional_int("revision"))
    elif len(parts) == 3 and parts[:2] == ["api", "synthesis-runs"]:
        _only(query, {})
        result = owner.result(parts[2])
    elif len(parts) == 5 and parts[:2] == ["api", "synthesis-runs"] and parts[3] == "files":
        _only(query, {})
        with owner.download(parts[2], parts[4]) as (stream, record):
            send_export(handler, stream, record)
        return True
    else:
        return False
    handler._reply(200, result)
    return True


def post(handler, workspace, url, parts, body):
    owner = workspace.synthesis
    if url.path == "/api/synthesis-publications":
        result = owner.import_publication(body)
    elif url.path == "/api/synthesis-protocols":
        result = owner.save_protocol(body)
    elif url.path == "/api/synthesis-review":
        need(set(body) == {"name", "revision"}, "REVIEW_FIELDS_INVALID")
        result = owner.review(body["name"], revision=body["revision"])
    elif url.path == "/api/synthesis-runs":
        result = workspace.start("synthesis", body)
    elif len(parts) == 4 and parts[:2] == ["api", "synthesis-runs"] and parts[3] == "cancel":
        need(not body, "CANCEL_FIELDS_INVALID")
        result = owner.cancel(parts[2])
    else:
        return False
    handler._reply(200, result)
    return True

"""Review and save a new workbook edition from complete retained result sources.

The original workbook store supplies definition CAS, request identities, typed
projection and complete delivery. This module never executes a query or purchase.
"""
from __future__ import annotations

from collections import Counter
from datetime import date, datetime
import json

from .analysis_reports import AnalysisReports
from .analysis_workbooks import _error, _hash, _id, _json, _page, _source_key, _text, _unpack, project_cell
from .errors import BuyerError
from .query_export import QueryExport, _bindings
from .storage import digest, parse

_SCHEMA = "stellar-forge.workbook-refresh-review.v1"
_ORIGIN = "stellar-forge.workbook-refresh-origin.v1"


def _canonical(value):
    return json.dumps(value, ensure_ascii=False, allow_nan=False, sort_keys=True, separators=(",", ":"))


class WorkbookRefresh:
    def __init__(self, workbooks):
        self.workbooks = workbooks
        self.database = workbooks.database

    def _base(self, name, revision, sha=None):
        if type(revision) is not int or revision < 1:
            _error("REFRESH_BASE_REVISION_REQUIRED")
        result = self.workbooks.definition(name, revision=revision)
        if sha is not None and _hash(sha) != result["definition_sha256"]:
            _error("REFRESH_BASE_CHANGED")
        return result

    def _lineage(self, source):
        current = self.workbooks.source(source)
        if current != source:
            _error("SOURCE_CHANGED")
        with self.database._connection(readonly=True) as db:
            db.execute("BEGIN")
            if source["kind"] == "query-export":
                row = db.execute("SELECT sequence,request,finished_at FROM sf_analysis_jobs WHERE id=? AND kind='query-export' AND status='COMPLETE'",
                                 (source["id"],)).fetchone()
                if row is None:
                    _error("COMPLETE_TYPED_QUERY_EXPORT_REQUIRED")
                request = parse(row["request"].encode())
                manifest = QueryExport(self.database.directory / "analysis-query-exports" / source["id"]).manifest
                binding = manifest["binding"]
                return {"kind": "query-export", "sequence": row["sequence"], "completed_at": row["finished_at"],
                        "query_id": request.get("query_id"), "sql": binding["sql"], "parameters": binding["parameters"],
                        "views": binding["views"], "read_tables": binding["readTables"],
                        "source_versions": binding["sourceVersions"], "binding_sha256": manifest["bindingSha256"]}
            row = db.execute("SELECT * FROM sf_analysis_report_publications WHERE id=?", (source["id"],)).fetchone()
            publication = _unpack(row)
            publication, report = self.workbooks.reports._export_input(
                db, {"publication_id": source["id"], "publication_sha256": source["sha256"]})
            section = report["sections"][source["section"]]
            selected = report["definition"]["sections"][source["section"]]
            return {"kind": "report", "sequence": row["sequence"], "completed_at": publication["published_at"],
                    "report_name": publication["name"], "publication_revision": publication["revision"],
                    "definition_revision": publication["definition_revision"], "section": section["ordinal"],
                    "query_name": section["query_name"], "query_revision": section["query_revision"],
                    "query_sha256": section["query_sha256"], "sql": selected["query"]["sql"],
                    "parameters": _bindings(self.workbooks.reports.parse_parameters(section["parameters_text"])),
                    "query_sections": [s["ordinal"] for s in report["sections"] if s["query_name"] == section["query_name"]],
                    "views": report["views"], "read_tables": section["read_tables"], "source_versions": report["sources"]}

    @staticmethod
    def _match(before, after):
        if before["kind"] != after["kind"] or after["sequence"] <= before["sequence"]:
            return None
        if before["kind"] == "query-export":
            if before["sql"] == after["sql"] and _canonical(before["parameters"]) == _canonical(after["parameters"]):
                return "Exact original SQL and typed parameters"
            return None
        if before["report_name"] != after["report_name"] or before["query_name"] != after["query_name"]:
            return None
        if len(before["query_sections"]) == len(after["query_sections"]) == 1:
            return "Same saved report and uniquely identified saved query"
        if before["section"] == after["section"]:
            return "Same saved report, saved query and repeated-section position"
        return None

    @staticmethod
    def _comparison(before, after, old_lineage, new_lineage):
        old_names, new_names = before["columns"], after["columns"]
        old_counts, new_counts = Counter(old_names), Counter(new_names)
        return {"rows_before": before["row_count"], "rows_after": after["row_count"],
                "columns_before": old_names, "columns_after": new_names,
                "added_labels": list((new_counts - old_counts).elements()),
                "removed_labels": list((old_counts - new_counts).elements()),
                "duplicate_labels_before": [name for name, count in old_counts.items() if count > 1],
                "duplicate_labels_after": [name for name, count in new_counts.items() if count > 1],
                "column_order_changed": old_names != new_names,
                "sql_changed": old_lineage["sql"] != new_lineage["sql"],
                "parameters_changed": _canonical(old_lineage["parameters"]) != _canonical(new_lineage["parameters"]),
                "views_changed": _canonical(old_lineage["views"]) != _canonical(new_lineage["views"]),
                "source_versions_changed": _canonical(old_lineage["source_versions"]) != _canonical(new_lineage["source_versions"]),
                "section_moved": old_lineage.get("section") != new_lineage.get("section")}

    @staticmethod
    def _suggest_columns(sheet, source):
        result, unresolved = [], []
        for index, column in enumerate(sheet["columns"]):
            value = dict(column)
            positions = [i for i, name in enumerate(source["columns"]) if name == column["source"]]
            if len(positions) == 1 and sheet["source"]["columns"].count(column["source"]) == 1:
                value["source"] = source["columns"][positions[0]]
                if source["kind"] == "report":
                    value["source_index"] = positions[0]
                else:
                    value.pop("source_index", None)
            else:
                value["source"] = ""
                if source["kind"] == "report":
                    value["source_index"] = -1
                else:
                    value.pop("source_index", None)
                unresolved.append({"column": index, "header": column["header"], "old_source": column["source"],
                                   "reason": "Choose a source position for this repeated label." if positions else "Choose a replacement column or remove this Excel column."})
            result.append(value)
        return result, unresolved

    def candidates(self, name, *, revision, sheet=0, before=None, limit=25):
        _page(before, limit)
        base = self._base(name, revision)
        sheets = base["definition"]["sheets"]
        if type(sheet) is not int or not 0 <= sheet < len(sheets):
            _error("REFRESH_SHEET_REQUIRED")
        selected = sheets[sheet]
        lineage = self._lineage(selected["source"])
        with self.database._connection(readonly=True) as db:
            if lineage["kind"] == "query-export":
                rows = db.execute("SELECT sequence,id FROM sf_analysis_jobs WHERE kind='query-export' AND status='COMPLETE' AND sequence>? AND (? IS NULL OR sequence<?) ORDER BY sequence DESC LIMIT ?",
                                  (lineage["sequence"], before, before, limit + 1)).fetchall()
            else:
                rows = db.execute("SELECT sequence,id,job_id FROM sf_analysis_report_publications WHERE name=? AND sequence>? AND (? IS NULL OR sequence<?) ORDER BY sequence DESC LIMIT ?",
                                  (lineage["report_name"], lineage["sequence"], before, before, limit + 1)).fetchall()
        items, unavailable = [], []
        for row in rows[:limit]:
            requests = [{"kind": lineage["kind"], "id": row["id"]}]
            if lineage["kind"] == "report":
                with self.database._connection(readonly=True) as db:
                    report = AnalysisReports._report(db, row["job_id"])
                requests = [{"kind": "report", "id": row["id"], "section": s["ordinal"]} for s in report["sections"]]
            for request in requests:
                try:
                    source = self.workbooks.source(request)
                    candidate = self._lineage(source)
                except BuyerError as exc:
                    unavailable.append({"source": request, "error": exc.code})
                    continue
                basis = self._match(lineage, candidate)
                if basis is None:
                    continue
                columns, unresolved = self._suggest_columns(selected, source)
                items.append({"source": source, "lineage": candidate, "match_basis": basis,
                              "comparison": self._comparison(selected["source"], source, lineage, candidate),
                              "suggested_columns": columns, "unresolved_columns": unresolved})
        return {"name": name, "revision": revision, "definition_sha256": base["definition_sha256"],
                "sheet": sheet, "current_source": selected["source"], "current_lineage": lineage, "items": items,
                "unavailable": unavailable, "scanned_results": min(limit, len(rows)),
                "next_before": rows[limit - 1]["sequence"] if len(rows) > limit else None}

    def _preview(self, sheet, limit=20):
        keys = [_source_key(sheet["source"], column) for column in sheet["columns"]]
        rows, failures, observed = [], [], [set() for _ in keys]
        with self.workbooks._rows(sheet["source"]) as stream:
            for row_number, row in enumerate(stream, 1):
                values = []
                for index, (column, key) in enumerate(zip(sheet["columns"], keys)):
                    value = row[key]
                    observed[index].add("null" if value is None else "boolean" if type(value) is bool else
                                        "integer" if type(value) is int else "number" if type(value) is float else
                                        "binary" if isinstance(value, bytes) else "text")
                    try:
                        projected, number_format, conversion = project_cell(value, column)
                        display = (projected.isoformat() if isinstance(projected, (date, datetime))
                                   else str(projected) if type(projected) is int and abs(projected) >= 2**53 else projected)
                        values.append({"value": display, "format": number_format, "conversion": conversion,
                                       "excel_type": "blank" if projected is None else "text" if isinstance(projected, str) else
                                       "date" if isinstance(projected, (date, datetime)) else "boolean" if type(projected) is bool else "number"})
                    except BuyerError as exc:
                        failures.append({"row": row_number, "column": index, "header": column["header"], "error": exc.code})
                        values.append({"error": exc.code})
                rows.append(values)
                if row_number >= limit:
                    break
        return {"rows": rows, "errors": failures, "row_count": sheet["source"]["row_count"],
                "observed_types": [{"header": column["header"], "types": sorted(kinds)}
                                   for column, kinds in zip(sheet["columns"], observed)],
                "preview_only": len(rows) < sheet["source"]["row_count"]}

    def review(self, name, request, *, preview=True):
        if not isinstance(request, dict):
            _error("REFRESH_REQUEST_REQUIRED")
        base = self._base(name, request.get("base_revision"), request.get("definition_sha256"))
        expected = request.get("expected_revision")
        if type(expected) is not int or expected < base["definition"]["revision"]:
            _error("REVISION_REQUIRED")
        reason = _text(request.get("reason", ""), 8000, required=True)
        proposed = request.get("definition")
        if not isinstance(proposed, dict) or proposed.get("name") != name:
            _error("REFRESH_DEFINITION_REQUIRED")
        normalized = self.workbooks.compose(name, proposed)
        original = base["definition"]
        if len(original["sheets"]) != len(normalized["sheets"]):
            _error("REFRESH_KEEP_WORKSHEET_POSITIONS")
        changes, previews = [], []
        for index, (old, new) in enumerate(zip(original["sheets"], normalized["sheets"])):
            same = old["source"] == new["source"]
            old_lineage = self._lineage(old["source"])
            new_lineage = old_lineage if same else self._lineage(new["source"])
            basis = "Keep the original complete result" if same else self._match(old_lineage, new_lineage)
            if basis is None:
                _error("REFRESH_SOURCE_LINEAGE_CHANGED")
            change = {"sheet": index, "name_before": old["name"], "name_after": new["name"],
                      "action": "keep" if same else "replace", "before": old["source"], "after": new["source"],
                      "match_basis": basis, "lineage_before": old_lineage, "lineage_after": new_lineage,
                      "comparison": self._comparison(old["source"], new["source"], old_lineage, new_lineage),
                      "columns_before": old["columns"], "columns_after": new["columns"]}
            changes.append(change)
            if preview:
                previews.append({"sheet": index, "name": new["name"], **self._preview(new)})
        if not any(change["action"] == "replace" for change in changes):
            _error("REFRESH_NEW_COMPLETE_RESULT_REQUIRED")
        review = {"schema": _SCHEMA, "workspace_id": self.workbooks.identity, "name": name,
                  "base_revision": original["revision"], "definition_sha256": base["definition_sha256"],
                  "expected_revision": expected, "reason": reason, "definition": normalized, "sheets": changes}
        return {**review, "review_sha256": digest(_canonical(review).encode()),
                "current_head_revision": base["head_revision"], "previews": previews,
                "ready": all(not item["errors"] for item in previews)}

    def save(self, name, request):
        request_id = _id(request.get("id"))
        reviewed = self.review(name, request, preview=False)
        if _hash(request.get("review_sha256")) != reviewed["review_sha256"]:
            _error("REFRESH_REVIEW_CHANGED")
        origin = {"schema": _ORIGIN, "base_revision": reviewed["base_revision"],
                  "base_definition_sha256": reviewed["definition_sha256"],
                  "base_definition_file": "history/definition-" + str(reviewed["base_revision"]) + ".json",
                  "review_sha256": reviewed["review_sha256"],
                  "reason": reviewed["reason"], "sheets": reviewed["sheets"]}
        return self.workbooks.save(name, {"id": request_id, "expected_revision": reviewed["expected_revision"],
                                         **reviewed["definition"]}, refresh_origin=origin)

    def retain_history(self, definition, target, *, cancel=lambda: False):
        """Carry exact predecessor definitions and their complete sources once."""
        from .storage import private_directory, write
        result, current = [], definition
        while current.get("refresh_origin"):
            if cancel():
                _error("CANCELLED")
            origin = current["refresh_origin"]
            revision = origin["base_revision"]
            if type(revision) is not int or not 1 <= revision < current["revision"]:
                _error("REFRESH_HISTORY_CHANGED")
            parent = self._base(definition["name"], revision, origin["base_definition_sha256"])
            name = "history/definition-" + str(revision) + ".json"
            if origin.get("base_definition_file") != name:
                _error("REFRESH_HISTORY_CHANGED")
            private_directory(target / "history")
            raw = _json(parent["definition"]).encode()
            if digest(raw) != parent["definition_sha256"]:
                _error("REFRESH_HISTORY_CHANGED")
            write(target / name, raw)
            for sheet in parent["definition"]["sheets"]:
                if cancel():
                    _error("CANCELLED")
                if self.workbooks.source(sheet["source"]) != sheet["source"]:
                    _error("SOURCE_CHANGED")
                self.workbooks._retain_source(sheet["source"], target)
            result.append({"revision": revision, "definition_sha256": parent["definition_sha256"], "file": name})
            current = parent["definition"]
        return result

"""Inspect and recoverably receive a complete, offline Analysis workspace.

The original application owns normal database recovery after publication.
Receiving copies verified bytes; it never constructs an AnalysisWorkspace.
"""
from __future__ import annotations

import argparse
from datetime import datetime, timezone
import errno
import hashlib
import json
import os
from pathlib import Path, PurePosixPath
import re
import sqlite3
import sys
import uuid
import zipfile

from .analysis_workbooks import _open_private, _publish_received_directory
from .errors import BuyerError, StateError
from .storage import dump, lock, parse, private_directory, sync_directory

_ARCHIVE = "stellar-forge.analysis-workspace-archive.v1"
_JOURNAL = "stellar-forge.analysis-workspace-receiving.v1"
_RECEIPT = "stellar-forge.analysis-workspace-receipt.v1"
_MARKER = "workspace-archive-receipt.json"
_ID = re.compile(r"[a-f0-9]{32}")
_HASH = re.compile(r"[a-f0-9]{64}")
_MAX_RECORD = 1024 * 1024
_BLOCK = 1024 * 1024
_TABLES = {"sf_dataset_versions", "sf_dataset_views", "sf_dataset_activations",
           "sf_analysis_format", "sf_analysis_sources", "sf_analysis_queries",
           "sf_analysis_query_history", "sf_analysis_jobs"}


def _now():
    return datetime.now(timezone.utc).isoformat()


def _error(code, operation=None):
    raise StateError("WORKSPACE_ARCHIVE_RECEIVE_" + code, operation=operation)


def _identifier(value):
    if not isinstance(value, str) or not _ID.fullmatch(value):
        _error("OPERATION_ID_INVALID")
    return value


def _private_folder(path, *, create=True):
    missing, current = [], Path(path).expanduser().absolute()
    while create and not os.path.lexists(current):
        missing.append(current)
        current = current.parent
    # pathlib's parents=True does not apply mode to intermediate directories.
    # Create each original receiving directory explicitly so a caller's ordinary
    # umask cannot leave a 0755 parent inside this private payload tree.
    for created in reversed(missing):
        try:
            created.mkdir(mode=0o700)
        except FileExistsError:
            pass
        checked = private_directory(created, create=False)
        if hasattr(os, "getuid") and checked.lstat().st_uid != os.getuid():
            _error("PRIVATE_DIRECTORY_REQUIRED")
        sync_directory(checked)
        sync_directory(checked.parent)
    folder = private_directory(Path(path), create=False)
    info = folder.lstat()
    if hasattr(os, "getuid") and info.st_uid != os.getuid():
        _error("PRIVATE_DIRECTORY_REQUIRED")
    return folder


def _record(path):
    with _open_private(path) as stream:
        raw = stream.read(_MAX_RECORD + 1)
    if len(raw) > _MAX_RECORD:
        _error("JOURNAL_INVALID")
    result = parse(raw)
    if not isinstance(result, dict):
        _error("JOURNAL_INVALID")
    return result


def _relative(value):
    if not isinstance(value, str) or "\\" in value or "\0" in value:
        _error("MEMBER_PATH_INVALID")
    path = PurePosixPath(value)
    if (not path.parts or path.is_absolute() or str(path) != value
            or any(part in {"", ".", ".."} for part in path.parts)
            or value == _MARKER):
        _error("MEMBER_PATH_INVALID")
    return value


def _files(inspection):
    manifest = inspection.get("manifest")
    if not isinstance(manifest, dict) or manifest.get("schema") != _ARCHIVE:
        _error("MANIFEST_INVALID")
    _identifier(manifest.get("id"))
    _identifier(manifest.get("workspace_id"))
    files, names = manifest.get("files"), set()
    if not isinstance(files, list) or not files:
        _error("MANIFEST_INVALID")
    for item in files:
        if not isinstance(item, dict):
            _error("MANIFEST_INVALID")
        name = _relative(item.get("path"))
        if (name in names or type(item.get("bytes")) is not int or item["bytes"] < 0
                or not isinstance(item.get("sha256"), str)
                or not _HASH.fullmatch(item["sha256"])):
            _error("MANIFEST_INVALID")
        names.add(name)
    database = manifest.get("database")
    if (not isinstance(database, dict) or database.get("path") != "datasets.sqlite3"
            or sum(item == database for item in files) != 1):
        _error("DATABASE_MEMBER_INVALID")
    # A regular file cannot also be a directory for another retained payload.
    if any(str(parent) in names for name in names for parent in PurePosixPath(name).parents
           if str(parent) != "."):
        _error("MEMBER_PATH_INVALID")
    return manifest, files


def _file_matches(path, expected):
    if not os.path.lexists(path):
        return False
    with _open_private(path) as stream:
        info = os.fstat(stream.fileno())
        if info.st_size != expected["bytes"]:
            return False
        if hashlib.file_digest(stream, "sha256").hexdigest() != expected["sha256"]:
            return False
        # A killed writer may have left complete bytes in the page cache.
        os.fsync(stream.fileno())
    return True


def _member(package, entry, destination):
    if os.path.lexists(destination):
        with _open_private(destination):
            pass
        destination.unlink()
    sha, size = hashlib.sha256(), 0
    with package.open("workspace/" + entry["path"]) as source:
        with destination.open("xb") as output:
            os.fchmod(output.fileno(), 0o600)
            for block in iter(lambda: source.read(_BLOCK), b""):
                size += len(block)
                if size > entry["bytes"]:
                    _error("MEMBER_CHANGED")
                sha.update(block)
                output.write(block)
            output.flush()
            os.fsync(output.fileno())
    if size != entry["bytes"] or sha.hexdigest() != entry["sha256"]:
        _error("MEMBER_CHANGED")
    sync_directory(destination.parent)


def _staged_tree(staging, files, *, complete=False):
    expected = {entry["path"] for entry in files}
    allowed_dirs = {str(parent) for name in expected for parent in PurePosixPath(name).parents
                    if str(parent) != "."}
    found = set()
    for root, directories, names in os.walk(staging, followlinks=False):
        folder = Path(root)
        _private_folder(folder, create=False)
        for name in directories:
            path = folder / name
            if path.is_symlink() or path.relative_to(staging).as_posix() not in allowed_dirs:
                _error("STAGING_CHANGED")
        for name in names:
            path = folder / name
            relative = path.relative_to(staging).as_posix()
            if relative not in expected and relative != _MARKER:
                _error("STAGING_CHANGED")
            with _open_private(path):
                pass
            if relative != _MARKER:
                found.add(relative)
    if complete and found != expected:
        _error("STAGING_INCOMPLETE")


def _validate_database(staging, manifest):
    from .response_documents import allowed_document_payload, snapshot_document_files
    from .response_sources import allowed_response_payload, snapshot_response_files

    path = staging / "datasets.sqlite3"
    # Immutable inspection neither creates WAL/SHM files nor runs application
    # initialization or interrupted-job reconciliation on the original bytes.
    uri = path.as_uri() + "?mode=ro&immutable=1"
    try:
        db = sqlite3.connect(uri, uri=True)
        try:
            db.execute("PRAGMA query_only=ON")
            db.execute("PRAGMA trusted_schema=OFF")
            if (db.execute("PRAGMA application_id").fetchone()[0] != 0x53464442
                    or db.execute("PRAGMA user_version").fetchone()[0] != 1
                    or db.execute("PRAGMA quick_check").fetchall() != [("ok",)]):
                _error("DATABASE_INVALID")
            tables = {row[0] for row in db.execute("SELECT name FROM sqlite_master WHERE type='table'")}
            if not _TABLES.issubset(tables):
                _error("DATABASE_FORMAT_INVALID")
            identity = db.execute("SELECT schema,workspace_id FROM sf_analysis_format WHERE id=1").fetchall()
            if identity != [("stellar-forge.customer-analysis.v1", manifest["workspace_id"])]:
                _error("DATABASE_IDENTITY_CHANGED")
            counts = manifest.get("table_rows", {})
            if not isinstance(counts, dict):
                _error("DATABASE_COUNTS_INVALID")
            for name, expected in counts.items():
                if name not in tables or type(expected) is not int or expected < 0:
                    _error("DATABASE_COUNTS_INVALID")
                quoted = '"' + name.replace('"', '""') + '"'
                if db.execute("SELECT COUNT(*) FROM " + quoted).fetchone()[0] != expected:
                    _error("DATABASE_ROWS_CHANGED")
            # Reopen the original document descriptors below this receiving
            # directory and require the complete DB-referenced source closure.
            try:
                documents = snapshot_document_files(staging, db)
            except (StateError, OSError):
                _error("DOCUMENT_SOURCE_INVALID")
            expected_documents = {item["path"]: item for item in documents}
            received_documents = {
                item["path"]: {key: item[key] for key in ("path", "bytes", "sha256")}
                for item in manifest["files"] if allowed_document_payload(item["path"])
            }
            if received_documents != expected_documents:
                _error("DOCUMENT_SOURCE_CLOSURE_CHANGED")
            try:
                responses = snapshot_response_files(staging, db)
            except (StateError, OSError):
                _error("RESPONSE_SOURCE_INVALID")
            expected_responses = {item["path"]: item for item in responses}
            received_responses = {
                item["path"]: {key: item[key] for key in ("path", "bytes", "sha256")}
                for item in manifest["files"] if allowed_response_payload(item["path"])
            }
            if received_responses != expected_responses:
                _error("RESPONSE_SOURCE_CLOSURE_CHANGED")
        finally:
            db.close()
    except sqlite3.Error:
        _error("DATABASE_INVALID")


def _published(target, state):
    if not os.path.lexists(target):
        return False
    _private_folder(target, create=False)
    info = target.lstat()
    if (state.get("phase") not in {"prepared", "complete"}
            or state.get("directory") != {"device": info.st_dev, "inode": info.st_ino}
            or _record(target / _MARKER) != state.get("marker")):
        _error("TARGET_EXISTS", state["operation_id"])
    return True


def _finish(control, target, state, reused):
    # This also covers rename succeeding immediately before process termination.
    sync_directory(target.parent)
    sync_directory(control)
    if state["phase"] != "complete":
        state["phase"] = "complete"
        state["result"] = {**state["marker"], "state": "complete", "completed_at": _now()}
        dump(control / "operation.json", state)
    return {**state["result"], "reused": reused}


def _write_marker(control, staging, marker):
    # The existing atomic JSON writer may leave its temporary file on SIGKILL.
    # Keep those write temporaries in the private journal, outside payloads.
    temporary = control / "publication.json"
    dump(temporary, marker)
    os.replace(temporary, staging / _MARKER)
    sync_directory(staging)
    sync_directory(control)


def restore_archive(archive, target, *, operation=None, expected_sha256=None):
    """Receive one exact archive into an absent destination, with crash recovery.

    A caller can retain a UUID32 ``operation`` before dispatch. Without one, the
    destination's private journal allocates it once. Repeating the same command
    returns the saved result after completion, preserving later customer edits.
    """
    from .workspace_archive import inspect_archive

    if operation is not None:
        operation = _identifier(operation)
    inspection = inspect_archive(archive, expected_sha256=expected_sha256)
    manifest, files = _files(inspection)
    target = Path(target).expanduser().absolute()
    if not target.name or target.name in {".", ".."}:
        _error("TARGET_INVALID")
    parent = _private_folder(target.parent)
    target = parent / target.name
    control = parent / (".analysis-receive-" + hashlib.sha256(os.fsencode(target.name)).hexdigest()[:24])
    if os.path.lexists(target) and not os.path.lexists(control / "operation.json"):
        _error("TARGET_EXISTS", operation)
    control = _private_folder(control)
    sync_directory(control.parent)
    record_path, staging = control / "operation.json", control / "content"
    binding = {"schema": _JOURNAL, "target": str(target), "archive_id": manifest["id"],
               "workspace_id": manifest["workspace_id"], "archive_sha256": inspection["archive"]["sha256"],
               "archive_bytes": inspection["archive"]["bytes"], "manifest_sha256": inspection["manifest_sha256"]}
    with lock(control):
        reused = os.path.lexists(record_path)
        if reused:
            state = _record(record_path)
            if (any(state.get(key) != value for key, value in binding.items())
                    or state.get("phase") not in {"extracting", "prepared", "complete"}
                    or not isinstance(state.get("operation_id"), str)
                    or not _ID.fullmatch(state["operation_id"])
                    or operation is not None and operation != state["operation_id"]):
                _error("OPERATION_CHANGED", operation)
        else:
            if os.path.lexists(staging) or os.path.lexists(target):
                _error("TARGET_EXISTS", operation)
            operation = operation or uuid.uuid4().hex
            state = {**binding, "operation_id": operation, "phase": "extracting", "created_at": _now()}
            # The retained operation lock already serializes first creation.
            # Rename publication avoids a hardlink alias left by SIGKILL
            # between an exclusive writer's link and temporary-file unlink.
            dump(record_path, state)
        operation = state["operation_id"]
        if _published(target, state):
            # Keep later customer revisions, while still requiring each original
            # immutable source file carried by this completed receiving.
            from .response_documents import allowed_document_payload
            from .response_sources import allowed_response_payload
            for entry in files:
                source_kind = ("DOCUMENT" if allowed_document_payload(entry["path"])
                               else "RESPONSE" if allowed_response_payload(entry["path"]) else None)
                if source_kind and not _file_matches(target / entry["path"], entry):
                    _error(source_kind + "_SOURCE_CLOSURE_CHANGED", operation)
            return _finish(control, target, state, True)
        if state["phase"] == "complete":
            _error("PUBLISHED_DIRECTORY_MISSING", operation)
        if not os.path.lexists(staging):
            if state["phase"] == "prepared":
                _error("STAGING_MISSING", operation)
            _private_folder(staging)
            sync_directory(control)
        else:
            _private_folder(staging, create=False)
        if state["phase"] == "prepared":
            info = staging.lstat()
            if state.get("directory") != {"device": info.st_dev, "inode": info.st_ino}:
                _error("STAGING_CHANGED", operation)
        _staged_tree(staging, files)
        ready = {entry["path"] for entry in files if _file_matches(staging / entry["path"], entry)}
        # A partial ZIP member is re-extracted from its beginning. Release only
        # those exact incomplete private members before admitting the retry.
        for entry in files:
            path = staging / entry["path"]
            if entry["path"] not in ready and os.path.lexists(path):
                with _open_private(path):
                    pass
                path.unlink()
                sync_directory(path.parent)
        required = sum(entry["bytes"] for entry in files if entry["path"] not in ready)
        space = os.statvfs(control)
        free = (space.f_bfree if hasattr(os, "geteuid") and os.geteuid() == 0 else space.f_bavail) * space.f_frsize
        if required > free:
            _error("STORAGE_REQUIRED", operation)
        with _open_private(Path(inspection["archive"].get("path", archive)).expanduser().absolute()) as source:
            before = os.fstat(source.fileno())
            if (before.st_size != binding["archive_bytes"]
                    or hashlib.file_digest(source, "sha256").hexdigest() != binding["archive_sha256"]):
                _error("ARCHIVE_CHANGED", operation)
            source.seek(0)
            with zipfile.ZipFile(source) as package:
                raw = package.read("archive-manifest.json")
                if hashlib.sha256(raw).hexdigest() != binding["manifest_sha256"]:
                    _error("ARCHIVE_CHANGED", operation)
                for entry in files:
                    if entry["path"] in ready:
                        continue
                    destination = staging / entry["path"]
                    _private_folder(destination.parent)
                    _member(package, entry, destination)
            after = os.fstat(source.fileno())
            if ((before.st_dev, before.st_ino, before.st_size, before.st_mtime_ns, before.st_ctime_ns)
                    != (after.st_dev, after.st_ino, after.st_size, after.st_mtime_ns, after.st_ctime_ns)):
                _error("ARCHIVE_CHANGED", operation)
        _staged_tree(staging, files, complete=True)
        _validate_database(staging, manifest)
        if state["phase"] != "prepared":
            marker = {"schema": _RECEIPT, "operation_id": operation, "archive_id": manifest["id"],
                      "workspace_id": manifest["workspace_id"], "archive_sha256": binding["archive_sha256"],
                      "archive_bytes": binding["archive_bytes"], "manifest_sha256": binding["manifest_sha256"],
                      "target": str(target), "database_path": str(target / "datasets.sqlite3"),
                      "files": len(files), "bytes": sum(entry["bytes"] for entry in files),
                      "created_at": state["created_at"], "prepared_at": _now(), "reused_staged_files": len(ready)}
            _write_marker(control, staging, marker)
            info = staging.lstat()
            state.update(phase="prepared", directory={"device": info.st_dev, "inode": info.st_ino}, marker=marker)
        elif _record(staging / _MARKER) != state.get("marker"):
            _error("STAGING_CHANGED", operation)
        for root, directories, names in os.walk(staging, topdown=False):
            sync_directory(Path(root))
        dump(record_path, state)
        try:
            _publish_received_directory(staging, target)
        except StateError as error:
            if error.code == "ANALYSIS_WORKBOOK_ATOMIC_DIRECTORY_PUBLICATION_UNAVAILABLE":
                _error("ATOMIC_PUBLICATION_UNAVAILABLE", operation)
            raise
        return _finish(control, target, state, reused)


def main(argv=None):
    parser = argparse.ArgumentParser(description="Inspect or receive a complete original Analysis workspace archive.")
    commands = parser.add_subparsers(dest="command", required=True)
    inspect = commands.add_parser("inspect", help="Validate all archive members and print the receiving review")
    inspect.add_argument("archive", type=Path)
    inspect.add_argument("--sha256", dest="expected_sha256")
    receive = commands.add_parser("receive", help="Resume one private restore and atomically publish its complete workspace")
    receive.add_argument("archive", type=Path)
    receive.add_argument("target", type=Path, help="Absent destination below a private parent directory")
    receive.add_argument("--operation", help="Retained receiving operation UUID32")
    receive.add_argument("--sha256", dest="expected_sha256")
    args = parser.parse_args(argv)
    try:
        os.umask(0o077)
        if args.command == "inspect":
            from .workspace_archive import inspect_archive
            result = inspect_archive(args.archive, expected_sha256=args.expected_sha256)
        else:
            result = restore_archive(args.archive, args.target, operation=args.operation,
                                     expected_sha256=args.expected_sha256)
        print(json.dumps(result, ensure_ascii=False, allow_nan=False, separators=(",", ":")))
        return 0
    except BuyerError as error:
        result = {"error": error.code}
        if error.operation:
            result["operation_id"] = error.operation
    except (zipfile.BadZipFile, EOFError, KeyError, ValueError):
        result = {"error": "WORKSPACE_ARCHIVE_RECEIVE_ARCHIVE_INVALID"}
    except OSError as error:
        code = "STORAGE_FULL" if error.errno in {errno.ENOSPC, errno.EDQUOT} else "IO_ERROR"
        result = {"error": "WORKSPACE_ARCHIVE_RECEIVE_" + code, "errno": error.errno}
    except KeyboardInterrupt:
        print(json.dumps({"error": "WORKSPACE_ARCHIVE_RECEIVE_INTERRUPTED"}), file=sys.stderr)
        return 130
    print(json.dumps(result, ensure_ascii=False, allow_nan=False), file=sys.stderr)
    return 2


if __name__ == "__main__":
    raise SystemExit(main())

"""Complete portable Analysis snapshots on the original database and job owner.

The original SQLite backup selects the snapshot. Only immutable outputs named
by its completed jobs are included; producer paths are retained as provenance.
Local file authority always starts at the operator-selected database directory.
"""
from __future__ import annotations

from contextlib import contextmanager
from datetime import datetime, timezone
import hashlib
import json
import os
from pathlib import Path, PurePosixPath
import re
import sqlite3
import stat
import threading
import zipfile

from .analysis_workbooks import _open_private, _file_record
from .errors import StateError
from .response_documents import allowed_document_payload, snapshot_document_files
from .response_sources import allowed_response_payload, snapshot_response_files
from .storage import digest, dump, parse, private_directory, read, sync_directory, write

ARCHIVE_SCHEMA = "stellar-forge.analysis-workspace-archive.v1"
EXPORT_SCHEMA = "stellar-forge.analysis-workspace-export.v1"
_ID = re.compile(r"[a-f0-9]{32}")
_HASH = re.compile(r"[a-f0-9]{64}")
_CHUNK = 1024 * 1024
_MAX_MANIFEST = 64 * 1024 * 1024
_MAX_FILES = 1_000_000
_MANIFEST_NAME = "archive-manifest.json"
_OUTPUTS = {"query-export", "workbook", "report-export", "change-export", "backup", "workspace-export"}


def _now():
    return datetime.now(timezone.utc).isoformat()


def _json(value):
    return (json.dumps(value, ensure_ascii=False, allow_nan=False, sort_keys=True, indent=2) + "\n").encode()


def _need(condition, code):
    if not condition:
        raise StateError(code)


def _id(value):
    _need(isinstance(value, str) and _ID.fullmatch(value), "WORKSPACE_ARCHIVE_ID_INVALID")
    return value


def _relative(value):
    _need(isinstance(value, str) and 0 < len(value) <= 2048 and "\\" not in value
          and "\x00" not in value and ":" not in value, "WORKSPACE_ARCHIVE_PATH_INVALID")
    p = PurePosixPath(value)
    _need(not p.is_absolute() and p.as_posix() == value and
          all(part not in {"", ".", ".."} for part in p.parts), "WORKSPACE_ARCHIVE_PATH_INVALID")
    return value


def _allowed_payload(value):
    """The portable format carries data files, never a launcher or executable."""
    _relative(value)
    if value == "datasets.sqlite3" or allowed_document_payload(value) or allowed_response_payload(value):
        return True
    if re.fullmatch(r"analysis-query-exports/(?:[a-f0-9]{32}/(?:manifest\.json|rows\.(?:csv|jsonl|sqlite3))|control/[a-f0-9]{32}\.json)", value):
        return True
    if re.fullmatch(r"analysis-exports/(?:report|changes)-[a-f0-9]{64}\.(?:html|json|zip|csv)", value):
        return True
    if re.fullmatch(r"analysis-backups/[a-f0-9]{32}/datasets\.sqlite3", value):
        return True
    return bool(re.fullmatch(
        r"analysis-workbooks/[a-f0-9]{32}/(?:manifest\.json|handoff\.zip|workbook\.xlsx|definition\.json|"
        r"history/definition-[0-9]+\.json|sources/report-[a-f0-9]{32}/report\.json|"
        r"sources/query-export-[a-f0-9]{32}/(?:manifest\.json|rows\.(?:csv|jsonl|sqlite3)))", value))


def _entry(value):
    _need(isinstance(value, dict) and _allowed_payload(value.get("path")), "WORKSPACE_ARCHIVE_PAYLOAD_INVALID")
    _need(type(value.get("bytes")) is int and value["bytes"] >= 0 and
          isinstance(value.get("sha256"), str) and _HASH.fullmatch(value["sha256"]),
          "WORKSPACE_ARCHIVE_FILE_IDENTITY_INVALID")
    return {key: value[key] for key in ("path", "bytes", "sha256")}


def _payload(root, relative):
    _need(_allowed_payload(relative), "WORKSPACE_ARCHIVE_PAYLOAD_INVALID")
    root = private_directory(Path(root), create=False)
    path = root / relative
    for parent in reversed(path.parents):
        if parent == root or root in parent.parents:
            _need(private_directory(parent, create=False) == parent, "WORKSPACE_ARCHIVE_DIRECTORY_CHANGED")
    return path


def _signature(info):
    return info.st_dev, info.st_ino, info.st_size, info.st_mtime_ns, info.st_ctime_ns


def _table_rows(db):
    tables = db.execute("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name").fetchall()
    return {row[0]: db.execute('SELECT COUNT(*) FROM "' + row[0].replace('"', '""') + '"').fetchone()[0] for row in tables}


def inspect_archive(path, *, expected_sha256=None):
    """Stream-verify every exact member before a receiving operation publishes."""
    path = Path(path).expanduser().absolute()
    if expected_sha256 is not None:
        _need(isinstance(expected_sha256, str) and _HASH.fullmatch(expected_sha256), "WORKSPACE_ARCHIVE_DIGEST_INVALID")
    with _open_private(path) as source:
        before = os.fstat(source.fileno())
        archive_sha = hashlib.file_digest(source, "sha256").hexdigest()
        _need(expected_sha256 is None or archive_sha == expected_sha256, "WORKSPACE_ARCHIVE_DIGEST_CHANGED")
        source.seek(0)
        try:
            with zipfile.ZipFile(source) as archive:
                infos = archive.infolist()
                _need(2 <= len(infos) <= _MAX_FILES + 1, "WORKSPACE_ARCHIVE_MEMBER_COUNT_INVALID")
                names = [item.filename for item in infos]
                _need(len(set(names)) == len(names), "WORKSPACE_ARCHIVE_DUPLICATE_MEMBER")
                meta = archive.getinfo(_MANIFEST_NAME)
                _need(0 < meta.file_size <= _MAX_MANIFEST, "WORKSPACE_ARCHIVE_MANIFEST_SIZE_INVALID")
                raw = archive.read(meta)
                manifest = parse(raw)
                _need(isinstance(manifest, dict) and manifest.get("schema") == ARCHIVE_SCHEMA,
                      "WORKSPACE_ARCHIVE_FORMAT_INVALID")
                _id(manifest.get("id")); _id(manifest.get("workspace_id"))
                records = manifest.get("files")
                _need(isinstance(records, list) and 1 <= len(records) <= _MAX_FILES, "WORKSPACE_ARCHIVE_FILES_INVALID")
                records = [_entry(item) for item in records]
                paths = [item["path"] for item in records]
                _need(paths == sorted(set(paths)), "WORKSPACE_ARCHIVE_PAYLOAD_ORDER_INVALID")
                database = _entry(manifest.get("database"))
                _need(database["path"] == "datasets.sqlite3" and database in records,
                      "WORKSPACE_ARCHIVE_DATABASE_REQUIRED")
                _need(set(names) == {_MANIFEST_NAME, *("workspace/" + item for item in paths)},
                      "WORKSPACE_ARCHIVE_MEMBER_SET_CHANGED")
                expected = {"workspace/" + item["path"]: item for item in records}
                for info in infos:
                    mode = info.external_attr >> 16
                    _need(not info.is_dir() and not info.flag_bits & 1 and
                          stat.S_IFMT(mode) in {0, stat.S_IFREG}, "WORKSPACE_ARCHIVE_MEMBER_TYPE_INVALID")
                    _need(info.compress_type in {zipfile.ZIP_STORED, zipfile.ZIP_DEFLATED},
                          "WORKSPACE_ARCHIVE_COMPRESSION_UNSUPPORTED")
                    if info.filename == _MANIFEST_NAME:
                        continue
                    record = expected[info.filename]
                    _need(info.file_size == record["bytes"], "WORKSPACE_ARCHIVE_FILE_SIZE_CHANGED")
                    count, sha = 0, hashlib.sha256()
                    with archive.open(info) as stream:
                        while block := stream.read(_CHUNK):
                            count += len(block)
                            _need(count <= record["bytes"], "WORKSPACE_ARCHIVE_FILE_SIZE_CHANGED")
                            sha.update(block)
                    _need(count == record["bytes"] and sha.hexdigest() == record["sha256"],
                          "WORKSPACE_ARCHIVE_PAYLOAD_CHANGED")
        except (KeyError, zipfile.BadZipFile, zipfile.LargeZipFile, RuntimeError, EOFError):
            raise StateError("WORKSPACE_ARCHIVE_ZIP_INVALID") from None
        _need(_signature(before) == _signature(os.fstat(source.fileno())), "WORKSPACE_ARCHIVE_CHANGED_DURING_READ")
    return {"schema": "stellar-forge.analysis-workspace-archive-review.v1",
            "archive": {"path": str(path), "bytes": before.st_size, "sha256": archive_sha},
            "manifest": manifest, "manifest_sha256": digest(raw)}


class WorkspaceArchives:
    """One original job, one retained SQLite snapshot, one complete archive."""

    def __init__(self, database, *, identity, read_job):
        self.database, self.identity, self.read_job = database, identity, read_job
        self.root = database.directory / "analysis-workspace-archives"
        self._closing = threading.Event()
        self._verified = {}
        self._verification_mutex = threading.Lock()

    def prepare(self, request):
        include = request.get("include_previous_backups", False)
        _need(type(include) is bool, "WORKSPACE_ARCHIVE_BACKUP_SELECTION_INVALID")
        return {"include_previous_backups": include}

    def prepare_intent(self, identifier, spec):
        """Persist the original operation before the RUNNING job is committed."""
        folder = self._folder(identifier, create=True)
        # The intent's leaf fsync must also have durable parent entries before
        # the database commits a job that can only resume from this directory.
        sync_directory(folder.parent)
        sync_directory(self.database.directory)
        operation_path = folder / "operation.json"
        operation = {"schema": EXPORT_SCHEMA, "id": identifier, "workspace_id": self.identity, "request": spec}
        if operation_path.exists():
            _need(parse(read(operation_path, _MAX_MANIFEST)) == operation, "WORKSPACE_ARCHIVE_REQUEST_CHANGED")
        else:
            # The workspace lock and single job owner serialize this directory.
            # Rename avoids an unfinished hardlink after process death.
            dump(operation_path, operation)
        return folder

    def _folder(self, identifier, *, create=False):
        _id(identifier)
        root = private_directory(self.root, create=create)
        return private_directory(root / identifier, create=create)

    def _progress(self, identifier, **values):
        path = self._folder(identifier, create=True) / "progress.json"
        dump(path, {"schema": "stellar-forge.analysis-workspace-export-progress.v1", "id": identifier,
                    "updated_at": _now(), **values})

    def progress(self, identifier):
        _id(identifier)
        try:
            return parse(read(self._folder(identifier) / "progress.json", _MAX_MANIFEST))
        except StateError:
            return None

    def cancel(self, identifier):
        job = self.read_job(_id(identifier))
        _need(job["kind"] == "workspace-export", "WORKSPACE_ARCHIVE_JOB_REQUIRED")
        if job["status"] == "RUNNING":
            dump(self._folder(identifier, create=True) / "cancel.json", {"id": identifier, "requested_at": _now()})
        return {"id": identifier, "status": job["status"], "cancel_requested": job["status"] == "RUNNING"}

    def resume(self, identifier):
        folder = self._folder(identifier)
        _need((folder / "operation.json").is_file(), "WORKSPACE_ARCHIVE_ORIGINAL_OPERATION_REQUIRED")
        (folder / "cancel.json").unlink(missing_ok=True)
        sync_directory(folder)

    def close(self):
        self._closing.set()

    def local_output(self, relative):
        """Resolve retained data at this selected workspace after receiving."""
        return _payload(self.database.directory, relative)

    def availability(self, identifier, status):
        """Describe local archive files without rewriting historical job rows."""
        try:
            folder = self._folder(identifier)
            operation = parse(read(folder / "operation.json", _MAX_MANIFEST))
            retained = (operation.get("schema") == EXPORT_SCHEMA and
                        operation.get("id") == identifier and operation.get("workspace_id") == self.identity)
            complete = retained and (folder / "workspace.zip").is_file() and (folder / _MANIFEST_NAME).is_file()
        except (StateError, OSError, AttributeError):
            retained, complete = False, False
        return {"retained": retained,
                "can_resume": retained and status in {"INTERRUPTED", "FAILED", "CANCELLED"},
                "can_download": complete and status == "COMPLETE",
                "reason": None if retained else "This archive remains separate from the restored workspace. Create a new complete backup to export the current saved data."}

    def _cancelled(self, folder):
        if self._closing.is_set() or (folder / "cancel.json").exists():
            raise StateError("WORKSPACE_ARCHIVE_CANCELLED")

    def _selection(self, db, *, include_previous_backups=False, review_missing=None):
        """Resolve only current local paths for immutable completed output IDs."""
        selected, outputs, exclusions = {}, [], []

        def add(path, record, owner):
            item = _entry({"path": path, "bytes": record.get("bytes"), "sha256": record.get("sha256")})
            if path in selected:
                _need(selected[path] == item, "WORKSPACE_ARCHIVE_OUTPUT_IDENTITY_CONFLICT")
            selected[path] = item

        for row in db.execute("SELECT id,kind,status,result FROM sf_analysis_jobs ORDER BY sequence"):
            identifier, kind, status, raw = row
            if kind not in _OUTPUTS or status != "COMPLETE":
                continue
            _id(identifier)
            result = parse(raw.encode()) if raw else {}
            if kind == "workspace-export" or kind == "backup" and not include_previous_backups:
                exclusions.append({"id": identifier, "kind": kind,
                                   "reason": "Earlier portable archives remain separate" if kind == "workspace-export" else "Earlier database backups not selected"})
                continue
            outputs.append({"id": identifier, "kind": kind,
                            "producer_directory": result.get("directory") or str(Path(result.get("path", "")).parent)})
            if kind == "query-export":
                _need(result.get("schema") == "stellar-forge.analysis-query-export.v1", "WORKSPACE_ARCHIVE_QUERY_EXPORT_INVALID")
                for item in result.get("files", []):
                    add("analysis-query-exports/" + identifier + "/" + item["name"], item, identifier)
                names = {item.get("name") for item in result.get("files", [])}
                _need(2 <= len(names) <= 4 and "manifest.json" in names and
                      names <= {"rows.csv", "rows.jsonl", "rows.sqlite3", "manifest.json"},
                      "WORKSPACE_ARCHIVE_COMPLETE_QUERY_EXPORT_REQUIRED")
                control = "analysis-query-exports/control/" + identifier + ".json"
                try:
                    if (self.database.directory / control).exists():
                        path = _payload(self.database.directory, control)
                        add(control, _file_record(path), identifier)
                except (StateError, OSError):
                    if review_missing is None:
                        raise StateError("WORKSPACE_ARCHIVE_QUERY_CONTROL_CHANGED") from None
                    review_missing.append({"path": control, "id": identifier,
                                           "reason": "query_control_changed"})
            elif kind == "workbook":
                _need(result.get("schema") == "stellar-forge.customer-workbook.v1" and result.get("id") == identifier,
                      "WORKSPACE_ARCHIVE_WORKBOOK_INVALID")
                base = "analysis-workbooks/" + identifier + "/"
                # These identities remain known in the original database even
                # when an older database-only backup lacks the source manifest.
                for item in result["files"]:
                    add(base + item["name"], item, identifier)
                try:
                    manifest_path = _payload(self.database.directory, base + "manifest.json")
                    raw_manifest = read(manifest_path, _MAX_MANIFEST)
                    _need(digest(raw_manifest) == result.get("manifest_sha256"), "WORKSPACE_ARCHIVE_WORKBOOK_MANIFEST_CHANGED")
                    manifest = parse(raw_manifest)
                    _need(isinstance(manifest, dict) and manifest.get("complete") is True and
                          manifest.get("id") == identifier and manifest.get("workspace_id") == self.identity and
                          manifest.get("definition_sha256") == result.get("definition_sha256"),
                          "WORKSPACE_ARCHIVE_WORKBOOK_BINDING_CHANGED")
                    _need(isinstance(manifest.get("files"), dict) and
                          all(isinstance(item, dict) for item in manifest["files"].values()),
                          "WORKSPACE_ARCHIVE_WORKBOOK_MANIFEST_CHANGED")
                    records = [_entry({"path": base + name, "bytes": item.get("bytes"),
                                       "sha256": item.get("sha256")}) for name, item in manifest["files"].items()]
                    for item in records:
                        add(item["path"], item, identifier)
                except (StateError, OSError):
                    if review_missing is None:
                        raise
                    review_missing.append({"path": base + "manifest.json", "id": identifier,
                                           "reason": "workbook_manifest_required_or_changed"})
            elif kind in {"report-export", "change-export"}:
                add("analysis-exports/" + result["filename"], result, identifier)
            elif kind == "backup":
                add("analysis-backups/" + identifier + "/datasets.sqlite3", result, identifier)
        # Resolve every registered source revision from this same database view.
        # During export this is the retained immutable SQLite snapshot; a newer
        # live registration cannot add files to an already selected backup.
        try:
            documents = snapshot_document_files(self.database.directory, db)
        except (StateError, OSError) as error:
            if review_missing is None:
                raise
            review_missing.append({"path": "analysis-response-documents",
                                   "reason": "source_document_required_or_changed",
                                   "code": error.code if isinstance(error, StateError) else "IO_ERROR"})
        else:
            for item in documents:
                add(item["path"], item, item["path"].split("/")[1])
        try:
            responses = snapshot_response_files(self.database.directory, db)
        except (StateError, OSError) as error:
            if review_missing is None:
                raise
            review_missing.append({"path": "analysis-response-sources",
                                   "reason": "retained_response_required_or_changed",
                                   "code": error.code if isinstance(error, StateError) else "IO_ERROR"})
        else:
            for item in responses:
                add(item["path"], item, item["path"].split("/")[1])
        return sorted(selected.values(), key=lambda item: item["path"]), outputs, exclusions

    def review(self, *, include_previous_backups=False):
        _need(type(include_previous_backups) is bool, "WORKSPACE_ARCHIVE_BACKUP_SELECTION_INVALID")
        missing = []
        with self.database._connection(readonly=True) as db:
            db.execute("BEGIN")
            files, outputs, exclusions = self._selection(db, include_previous_backups=include_previous_backups,
                                                         review_missing=missing)
        missing_paths = {item["path"] for item in missing}
        for item in files:
            if item["path"] in missing_paths:
                continue
            try:
                path = _payload(self.database.directory, item["path"])
                with _open_private(path) as stream:
                    if os.fstat(stream.fileno()).st_size != item["bytes"]:
                        missing.append({"path": item["path"], "reason": "size_changed"})
            except (StateError, OSError):
                missing.append({"path": item["path"], "reason": "retained_file_required"})
        return {"schema": "stellar-forge.analysis-workspace-export-plan.v1", "workspace_id": self.identity,
                "payload_files": len(files) + 1, "payload_bytes": sum(item["bytes"] for item in files),
                "database_bytes": self.database.path.stat().st_size,
                "outputs": outputs, "exclusions": exclusions, "missing": missing,
                "ready": not missing, "include_previous_backups": include_previous_backups}

    def _completed(self, identifier):
        folder = self._folder(identifier)
        record = parse(read(folder / "result.json", _MAX_MANIFEST))
        _need(record.get("schema") == EXPORT_SCHEMA and record.get("id") == identifier and
              record.get("workspace_id") == self.identity, "WORKSPACE_ARCHIVE_RESULT_CHANGED")
        _need({item.get("name") for item in record.get("files", [])} == {"workspace.zip", _MANIFEST_NAME},
              "WORKSPACE_ARCHIVE_RESULT_FILES_CHANGED")
        for item in record["files"]:
            _need(_file_record(folder / item["name"]) == {"bytes": item["bytes"], "sha256": item["sha256"]},
                  "WORKSPACE_ARCHIVE_RESULT_FILE_CHANGED")
        return record

    def run(self, identifier, spec):
        folder = self.prepare_intent(identifier, spec)
        if (folder / "result.json").exists():
            return self._completed(identifier)
        self._cancelled(folder)
        snapshot = private_directory(folder / "snapshot", create=True)
        database_path = snapshot / "datasets.sqlite3"
        # DatasetDatabase.backup publishes its completed copy by hardlink.
        # Release only this operation's same-inode temporary alias if the
        # process died before the original helper's unlink/finally completed.
        if database_path.exists():
            published = database_path.lstat()
            for alias in snapshot.glob(".database-*"):
                candidate = alias.lstat()
                if (stat.S_ISREG(candidate.st_mode) and not candidate.st_mode & 0o077
                        and (candidate.st_dev, candidate.st_ino) == (published.st_dev, published.st_ino)):
                    alias.unlink()
            sync_directory(snapshot)
        if not database_path.exists():
            self._progress(identifier, phase="SNAPSHOT", files_done=0, bytes_done=0)
            self.database.backup(snapshot)
        plan_path = folder / "archive-inputs.json"
        cached_plan = plan_path.exists()
        if cached_plan:
            manifest = parse(read(plan_path, _MAX_MANIFEST))
        else:
            with sqlite3.connect(database_path.as_uri() + "?mode=ro&immutable=1", uri=True) as db:
                db.execute("PRAGMA trusted_schema=OFF")
                _need(db.execute("SELECT workspace_id FROM sf_analysis_format WHERE id=1").fetchone()[0] == self.identity,
                      "WORKSPACE_ARCHIVE_SNAPSHOT_IDENTITY_CHANGED")
                selected, outputs, exclusions = self._selection(db, include_previous_backups=spec["include_previous_backups"])
                rows = _table_rows(db)
            database = {"path": "datasets.sqlite3", **_file_record(database_path)}
            manifest = {"schema": ARCHIVE_SCHEMA, "id": identifier, "workspace_id": self.identity,
                        "created_at": _now(), "source_directory": str(self.database.directory),
                        "database": database, "files": sorted([database, *selected], key=lambda item: item["path"]),
                        "table_rows": rows, "outputs": outputs, "exclusions": exclusions,
                        "runtime_files": "Receiving creates a fresh analysis.lock and launch capability; provider sessions remain operator-owned."}
            dump(plan_path, manifest)
        _need(manifest.get("schema") == ARCHIVE_SCHEMA and manifest.get("id") == identifier and
              manifest.get("workspace_id") == self.identity, "WORKSPACE_ARCHIVE_PLAN_CHANGED")
        files = manifest["files"]
        if cached_plan:
            # A retained plan predating document custody must not become a
            # COMPLETE archive that omits sources referenced by its own DB.
            # Recheck against that same snapshot, never the live workspace.
            with sqlite3.connect(database_path.as_uri() + "?mode=ro&immutable=1", uri=True) as db:
                db.execute("PRAGMA trusted_schema=OFF")
                _need(db.execute("SELECT workspace_id FROM sf_analysis_format WHERE id=1").fetchone()[0] == self.identity,
                      "WORKSPACE_ARCHIVE_SNAPSHOT_IDENTITY_CHANGED")
                documents = snapshot_document_files(self.database.directory, db)
                responses = snapshot_response_files(self.database.directory, db)
            expected_documents = {item["path"]: item for item in documents}
            planned_documents = {
                item["path"]: _entry(item) for item in files
                if allowed_document_payload(item.get("path"))
            }
            _need(planned_documents == expected_documents,
                  "WORKSPACE_ARCHIVE_DOCUMENT_SOURCE_SELECTION_CHANGED")
            expected_responses = {item["path"]: item for item in responses}
            planned_responses = {item["path"]: _entry(item) for item in files
                                 if allowed_response_payload(item.get("path"))}
            _need(planned_responses == expected_responses,
                  "WORKSPACE_ARCHIVE_RESPONSE_SOURCE_SELECTION_CHANGED")
        total = sum(item["bytes"] for item in files)
        self._progress(identifier, phase="ARCHIVING", files_done=0, files_total=len(files), bytes_done=0, bytes_total=total)
        temporary, target = folder / "workspace.zip.part", folder / "workspace.zip"
        # A partial ZIP is rebuilt from the same frozen database and original
        # immutable outputs. No acquisition, query, or new snapshot is repeated.
        temporary.unlink(missing_ok=True)
        fd = os.open(temporary, os.O_CREAT | os.O_EXCL | os.O_WRONLY | os.O_NOFOLLOW, 0o600)
        bytes_done = 0
        with os.fdopen(fd, "wb") as output:
            with zipfile.ZipFile(output, "w", compression=zipfile.ZIP_DEFLATED, compresslevel=6, allowZip64=True) as archive:
                for index, record in enumerate(files):
                    self._cancelled(folder)
                    record = _entry(record)
                    path = database_path if record["path"] == "datasets.sqlite3" else _payload(self.database.directory, record["path"])
                    info = zipfile.ZipInfo("workspace/" + record["path"], date_time=(1980, 1, 1, 0, 0, 0))
                    info.compress_type = zipfile.ZIP_DEFLATED
                    info.external_attr = (stat.S_IFREG | 0o600) << 16
                    count, sha = 0, hashlib.sha256()
                    with _open_private(path) as source, archive.open(info, "w", force_zip64=True) as dest:
                        before = os.fstat(source.fileno())
                        while block := source.read(_CHUNK):
                            self._cancelled(folder)
                            count += len(block); sha.update(block); dest.write(block)
                        _need(_signature(before) == _signature(os.fstat(source.fileno())) and
                              count == record["bytes"] and sha.hexdigest() == record["sha256"],
                              "WORKSPACE_ARCHIVE_SOURCE_CHANGED")
                    bytes_done += count
                    self._progress(identifier, phase="ARCHIVING", files_done=index + 1, files_total=len(files),
                                   bytes_done=bytes_done, bytes_total=total)
                meta = zipfile.ZipInfo(_MANIFEST_NAME, date_time=(1980, 1, 1, 0, 0, 0))
                meta.compress_type = zipfile.ZIP_DEFLATED
                meta.external_attr = (stat.S_IFREG | 0o600) << 16
                archive.writestr(meta, _json(manifest))
            output.flush(); os.fsync(output.fileno())
        if target.exists():
            _need(_file_record(target) == _file_record(temporary), "WORKSPACE_ARCHIVE_PUBLICATION_CHANGED")
            temporary.unlink()
        else:
            os.link(temporary, target); temporary.unlink()
        sync_directory(folder)
        write(folder / _MANIFEST_NAME, _json(manifest))
        result = {"schema": EXPORT_SCHEMA, "id": identifier, "workspace_id": self.identity,
                  "directory": str(folder), "created_at": manifest["created_at"],
                  "payload_files": len(files), "payload_bytes": total,
                  "files": [{"name": name, **_file_record(folder / name), "mime": mime} for name, mime in
                            [("workspace.zip", "application/zip"), (_MANIFEST_NAME, "application/json")]]}
        dump(folder / "result.json", result)
        self._progress(identifier, phase="COMPLETE", files_done=len(files), files_total=len(files), bytes_done=total, bytes_total=total)
        return result

    def recover_completed(self):
        with self.database._connection(readonly=True) as db:
            identifiers = [row[0] for row in db.execute("SELECT id FROM sf_analysis_jobs WHERE kind='workspace-export' AND status IN ('INTERRUPTED','FAILED')")]
        for identifier in identifiers:
            try:
                result = self._completed(identifier)
            except (StateError, OSError):
                continue
            with self.database._connection() as db:
                db.execute("UPDATE sf_analysis_jobs SET status='COMPLETE',result=?,error=NULL,finished_at=? WHERE id=? AND status IN ('INTERRUPTED','FAILED')",
                           (_json(result).decode(), _now(), identifier))

    def history(self, *, before=None, limit=25):
        _need(type(limit) is int and 1 <= limit <= 100 and (before is None or type(before) is int and before > 0),
              "WORKSPACE_ARCHIVE_PAGE_INVALID")
        with self.database._connection(readonly=True) as db:
            rows = db.execute("SELECT sequence,id FROM sf_analysis_jobs WHERE kind='workspace-export' " +
                              ("AND sequence<? " if before is not None else "") + "ORDER BY sequence DESC LIMIT ?",
                              ([before] if before is not None else []) + [limit + 1]).fetchall()
        return {"schema": "stellar-forge.analysis-workspace-export-history.v1",
                "items": [self.read_job(row[1]) for row in rows[:limit]],
                "next_before": rows[limit - 1][0] if len(rows) > limit else None}

    @contextmanager
    def download(self, identifier, name):
        _need(name in {"workspace.zip", _MANIFEST_NAME}, "WORKSPACE_ARCHIVE_DOWNLOAD_INVALID")
        job = self.read_job(_id(identifier))
        _need(job["kind"] == "workspace-export" and job["status"] == "COMPLETE", "WORKSPACE_ARCHIVE_COMPLETE_REQUIRED")
        result = job["result"]
        _need(result.get("schema") == EXPORT_SCHEMA and result.get("id") == identifier and
              result.get("workspace_id") == self.identity, "WORKSPACE_ARCHIVE_RESULT_CHANGED")
        record = next((item for item in result["files"] if item["name"] == name), None)
        _need(record is not None, "WORKSPACE_ARCHIVE_DOWNLOAD_INVALID")
        with _open_private(self._folder(identifier) / name) as stream:
            info = os.fstat(stream.fileno())
            cache_key = (identifier, name)
            signature = (*_signature(info), record["sha256"])
            with self._verification_mutex:
                if self._verified.get(cache_key) != signature:
                    _need(info.st_size == record["bytes"] and
                          hashlib.file_digest(stream, "sha256").hexdigest() == record["sha256"] and
                          _signature(info) == _signature(os.fstat(stream.fileno())),
                          "WORKSPACE_ARCHIVE_DOWNLOAD_CHANGED")
                    self._verified[cache_key] = signature
            stream.seek(0)
            yield stream, record

"""Private same-owner HTTP and assets for approved World Bank handover intake."""
from . import _analysis_worldbank_intake_ui
from .errors import StateError
from ._analysis_export_http import send_export

def assets():
    return {"/worldbank-intake": (_analysis_worldbank_intake_ui.HTML, "text/html;charset=utf-8"),
            "/worldbank-intake.js": (_analysis_worldbank_intake_ui.JS, "text/javascript;charset=utf-8"),
            "/worldbank-intake.css": (_analysis_worldbank_intake_ui.CSS, "text/css;charset=utf-8")}


def get(handler, workspace, url, query, parts):
    if handler.command not in {"GET", "HEAD"} or parts[:2] != ["api", "worldbank-intake"]:
        return False
    intake = workspace.worldbank_intake
    if len(parts) == 2 and handler.command == "GET":
        if set(query) - {"before", "limit"}:
            raise StateError("WORLDBANK_INTAKE_PAGE_INVALID")
        before = query.get("before", [None])[0]
        handler._reply(200, intake.history(before=int(before) if before else None,
                                         limit=int(query.get("limit", ["25"])[0])))
    elif len(parts) == 3 and handler.command == "GET":
        if query:
            raise StateError("WORLDBANK_INTAKE_QUERY_INVALID")
        handler._reply(200, intake.status(parts[2]))
    elif len(parts) == 4 and parts[3] == "original":
        if query:
            raise StateError("WORLDBANK_INTAKE_QUERY_INVALID")
        delivery, record = intake.original(parts[2])
        with delivery.open() as stream:
            send_export(handler, stream, record)
    else:
        return False
    return True


def post(handler, workspace, url, parts, body):
    if parts[:2] != ["api", "worldbank-intake"]:
        return False
    intake = workspace.worldbank_intake
    if len(parts) == 2:
        handler._reply(200, intake.begin(body))
    elif len(parts) == 4 and parts[3] == "chunks":
        handler._reply(200, intake.chunk(parts[2], body))
    elif len(parts) == 4 and parts[3] == "register":
        if set(body) - {"resume"}:
            raise StateError("WORLDBANK_INTAKE_REGISTER_FIELDS_INVALID")
        handler._reply(202, intake.register(parts[2], resume=body.get("resume", False)))
    else:
        return False
    return True

"""HTTP joins for the original World Bank recurring engine and live Analysis owner."""
from urllib.parse import unquote

from .errors import StateError


def _page(query, *, names=False):
    if set(query) - {"before", "limit"} or any(len(v) != 1 for v in query.values()):
        raise StateError("WORLDBANK_PROGRAMME_PAGE_INVALID")
    before = query.get("before", [None])[0]
    limit = int(query.get("limit", ["50"])[0])
    if not 1 <= limit <= 100:
        raise StateError("WORLDBANK_PROGRAMME_PAGE_INVALID")
    if before is not None and not names:
        before = int(before)
        if before < 1:
            raise StateError("WORLDBANK_PROGRAMME_PAGE_INVALID")
    return {"before": before, "limit": limit}


def get(handler, workspace, url, query, parts):
    if handler.command not in {"GET", "HEAD"} or parts[:2] != ["api", "worldbank-programmes"]:
        return False
    manager = workspace.worldbank_programmes
    if len(parts) == 2 and handler.command == "GET":
        handler._reply(200, manager.list(**_page(query, names=True)))
    elif len(parts) == 3 and parts[2] == "sources" and handler.command == "GET":
        handler._reply(200, manager.sources(**_page(query)))
    elif len(parts) == 3 and handler.command == "GET":
        if query:
            raise StateError("WORLDBANK_PROGRAMME_QUERY_INVALID")
        handler._reply(200, manager.definition(unquote(parts[2])))
    elif len(parts) == 4 and parts[3] == "history" and handler.command == "GET":
        handler._reply(200, manager.history(unquote(parts[2]), **_page(query)))
    elif len(parts) >= 5 and parts[3] == "operations":
        name, operation = unquote(parts[2]), parts[4]
        if query:
            raise StateError("WORLDBANK_PROGRAMME_QUERY_INVALID")
        if len(parts) == 5 and handler.command == "GET":
            handler._reply(200, manager.status(name, operation))
        elif len(parts) == 6 and parts[5] == "review" and handler.command == "GET":
            handler._reply(200, manager.review(name, operation))
        elif len(parts) == 7 and parts[5] == "files":
            path, record = manager.download(name, operation, unquote(parts[6]))
            # Reuse the original descriptor verification and streaming response.
            handler._file_reply(path, record)
        else:
            return False
    else:
        return False
    return True


def post(handler, workspace, url, parts, body):
    if parts[:2] != ["api", "worldbank-programmes"]:
        return False
    manager = workspace.worldbank_programmes
    if len(parts) == 3:
        if parts[2] == "sources":
            raise StateError("WORLDBANK_PROGRAMME_RESERVED_NAME")
        handler._reply(200, manager.save(unquote(parts[2]), body))
    elif len(parts) == 4 and parts[3] in ("prepare", "reopen"):
        handler._reply(202, getattr(manager, parts[3])(unquote(parts[2]), body))
    elif len(parts) == 6 and parts[3] == "operations" and parts[5] == "publish":
        if body.get("id") != parts[4]:
            raise StateError("WORLDBANK_PROGRAMME_OPERATION_ID_CHANGED")
        handler._reply(202, manager.publish(unquote(parts[2]), body))
    else:
        return False
    return True
